        {GRACEFUL_CAPE_WYRM_WORN,GRACEFUL_CAPE_WYRM},
        {GRACEFUL_TOP_WYRM_WORN,GRACEFUL_TOP_WYRM},
        {GRACEFUL_LEGS_WYRM_WORN,GRACEFUL_LEGS_WYRM},
        {GRACEFUL_GLOVES_WYRM_WORN,GRACEFUL_GLOVES_WYRM},
        {GRACEFUL_BOOTS_WYRM_WORN,GRACEFUL_BOOTS_WYRM},
        {SKILLCAPE_MAX_WORN,SKILLCAPE_MAX},
        {HUNTING_LIGHT_CAPE_WORN,HUNTING_LIGHT_CAPE},
        {HUNTING_LIGHTER_CAPE_WORN,HUNTING_LIGHTER_CAPE},
        {SKILLCAPE_AGILITY_TRIMMED_WORN,SKILLCAPE_AGILITY_TRIMMED},
        {SKILLCAPE_AGILITY_WORN,SKILLCAPE_AGILITY},
        {HUNTING_CAMOFLAUGE_ROBE_WOOD_WORN,HUNTING_CAMOFLAUGE_ROBE_WOOD},
        {HUNTING_TROUSERS_WOOD_WORN,HUNTING_TROUSERS_WOOD},
        {HUNTING_CAMOFLAUGE_ROBE_JUNGLE_WORN,HUNTING_CAMOFLAUGE_ROBE_JUNGLE},
        {HUNTING_TROUSERS_JUNGLE_WORN,HUNTING_TROUSERS_JUNGLE},
        {HUNTING_CAMOFLAUGE_ROBE_DESERT_WORN,HUNTING_CAMOFLAUGE_ROBE_DESERT},
        {HUNTING_TROUSERS_DESERT_WORN,HUNTING_TROUSERS_DESERT},
        {HUNTING_CAMOFLAUGE_ROBE_POLAR_WORN,HUNTING_CAMOFLAUGE_ROBE_POLAR},
        {HUNTING_TROUSERS_POLAR_WORN,HUNTING_TROUSERS_POLAR},
    };
    public static void main(String[] args)
    {
        PlanInputs.Choices choice=new PlanInputs.Choices(HERBS[4],Map.of(Patch.CATHERBY,Travel.MANUAL),ReturnToBank.FINISH,Compost.ULTRA,true,true,true,true,false,false);
        for(int[] pair:PAIRS)
        {
            int worn=pair[0],base=pair[1];
            RunPreferences prefs=new RunPreferences();prefs.put("outfit.1.name","Saved worn outfit");prefs.put("outfit.1.item."+worn,true);
            Set<Integer> gear=GearSets.load(prefs).current().items;
            check(gear.contains(base),"Saved worn outfit restores inventory ID "+base);
            for(int state=0;state<3;state++)
            {
                Map<Integer,Integer> inv=state==0?Map.of(base,1):Map.of();
                Map<Integer,Integer> eq=state==1?Map.of(worn,1):Map.of();
                Map<Integer,Integer> bank=state==2?Map.of(base,1):Map.of();
                PlanInputs in=new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank",Map.of(),inv,eq,Map.of(),bank).withGear(gear);
                PlanEngine.Supply supply=PlanEngine.evaluate(in,choice).supplies.stream().filter(item->item.id==base).findFirst().orElseThrow(AssertionError::new);
                check(supply.missing==0 && supply.withdraw==(state==2?1:0),"Checklist identity "+base+" state "+state);
            }
        }
        check(GearVariants.count(Map.of(ZEAH_GRACEFUL_HOOD_ARCEUUS_WORN,1),ZEAH_GRACEFUL_HOOD_HOSIDIUS)==0,"Different graceful colours remain distinct");
        check(GearVariants.count(Map.of(HUNTING_LIGHT_CAPE_WORN,1),HUNTING_LIGHTER_CAPE)==0,"Spotted does not replace spottier");
        check(GearVariants.count(Map.of(SKILLCAPE_AGILITY_WORN,1),SKILLCAPE_AGILITY_TRIMMED)==0,"Trimmed capes remain distinct");
        check(GearVariants.count(Map.of(AMULET_OF_GLORY_1,1),AMULET_OF_GLORY_2)==0,"Charges remain distinct");
        check(GearVariants.count(Map.of(CERT_HUNTING_CAMOFLAUGE_ROBE_WOOD_WORN,1),HUNTING_CAMOFLAUGE_ROBE_WOOD)==0,"Noted forms do not become usable gear");
        System.out.println(checks+" equipment-variant checks passed.");
    }
}

package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;

public final class PlanChecks
{
    private static int checks;
    private static final Map<String,Boolean> FLAGS=new LinkedHashMap<>();
    static
    {
        for(Patch p:Patch.values())if(p.gate!=null)FLAGS.put(p.gate,true);
        for(Travel t:Travel.values())if(t.gate!=null)FLAGS.put(t.gate,true);
    }
    private static PlanInputs input(Map<Integer,Integer> inv,Map<Integer,Integer> bank,int book)
    {return new PlanInputs(1,99,99,99,book,0,8,true,true,"Bank observed",FLAGS,inv,Collections.emptyMap(),Collections.emptyMap(),bank);}
    private static PlanInputs.Choices choices(Map<Patch,Travel> patches,ReturnToBank bank,boolean confirm)
    {return new PlanInputs.Choices(HERBS[4],patches,bank,Compost.ULTRA,confirm,confirm,confirm,false,true,false);}
    private static String plan(PlanInputs input,Map<Patch,Travel> patches,ReturnToBank bank)
    {return PlanEngine.build(input,choices(patches,bank,true));}
    private static void has(String text,String expected)
    {checks++;if(!text.contains(expected))throw new AssertionError("Missing: "+expected+"\n"+text);}
    private static void no(String text,String unexpected)
    {checks++;if(text.contains(unexpected))throw new AssertionError("Unexpected: "+unexpected+"\n"+text);}
    public static void main(String[] args)
    {
        Map<Integer,Integer> empty=Collections.emptyMap();
        Map<Patch,Travel> two=new EnumMap<>(Patch.class);two.put(Patch.FALADOR,Travel.FALADOR);two.put(Patch.CATHERBY,Travel.CAMELOT);
        String result=plan(input(Map.of(ItemID.LAWRUNE,2,ItemID.MISTRUNE,5),empty,0),two,ReturnToBank.WALK);
        has(result,"Mist rune × 5");has(result,"Air rune × 3");has(result,"Rune budget has a shortfall");
        has(result,"Ranarr seed × 2");has(result,"Ultracompost bucket × 2");
        result=plan(input(empty,Map.of(ItemID.LAWRUNE,2,ItemID.MISTRUNE,8),0),two,ReturnToBank.WALK);
        has(result,"Mist rune × 8\n   Carried 0 • withdraw 8");no(result,"Rune budget has a shortfall");
        result=plan(input(Map.of(ItemID.LAWRUNE,6,ItemID.WATERRUNE,20,ItemID.ASTRALRUNE,6),empty,2),
            Map.of(Patch.CATHERBY,Travel.CATHERBY),ReturnToBank.CATHERBY);
        has(result,"Law rune × 6");has(result,"Water rune × 20");has(result,"Astral rune × 6");
        result=plan(input(Map.of(ItemID.AMULET_OF_GLORY_1,1),empty,0),Map.of(Patch.FALADOR,Travel.GLORY),ReturnToBank.GLORY);
        has(result,"Glory (1) × 1");has(result,"Glory (6) × 1");has(result,"not in snapshot: 1");
        result=plan(input(Map.of(ItemID.AMULET_OF_GLORY_2,1),empty,0),Map.of(Patch.FALADOR,Travel.GLORY),ReturnToBank.GLORY);
        has(result,"Glory (2) × 1");no(result,"Glory (6)");
        result=plan(input(empty,Map.of(ItemID.AMULET_OF_GLORY_1,2),0),Map.of(Patch.FALADOR,Travel.GLORY),ReturnToBank.GLORY);
        has(result,"Glory (1) × 2\n   Carried 0 • withdraw 2");
        result=plan(input(empty,empty,0),Map.of(Patch.CATHERBY,Travel.CATHERBY),ReturnToBank.WALK);
        has(result,"active spellbook requirement is not met");
        result=PlanEngine.build(input(empty,empty,0),choices(Map.of(Patch.WEISS,Travel.ICY),ReturnToBank.AUTO,false));
        has(result,"Confirm that the Weiss Fire of Nourishment is built");
        result=PlanEngine.build(input(empty,empty,3),choices(Map.of(Patch.HARMONY,Travel.HARMONY),ReturnToBank.AUTO,false));
        has(result,"Confirm that the Morytania elite reward is claimed");
        result=PlanEngine.build(input(Map.of(ItemID.LUMBRIDGE_RING_MEDIUM,1),empty,0),choices(Map.of(Patch.FALADOR,Travel.RING),ReturnToBank.AUTO,false));
        has(result,"remaining uses unknown");
        result=plan(input(empty,null,0),Map.of(Patch.FALADOR,Travel.GLORY),ReturnToBank.GLORY);
        has(result,"bank unknown: need");
        result=plan(input(empty,empty,0),Map.of(Patch.CATHERBY,Travel.MANUAL),ReturnToBank.AUTO);
        has(result,"Walk to Catherby bank");has(result,"Manual travel: arrange its supplies yourself");
        PlanInputs free=new PlanInputs(1,99,99,99,0,0,0,false,false,"",FLAGS,empty,empty,empty,empty);
        has(plan(free,two,ReturnToBank.WALK),"members world is required");
        PlanInputs low=new PlanInputs(1,99,1,1,0,0,0,true,false,"",FLAGS,empty,empty,empty,empty);
        has(plan(low,two,ReturnToBank.WALK),"needs 32 current Farming");
        PlanInputs noGates=new PlanInputs(1,99,99,99,0,0,0,true,false,"",Collections.emptyMap(),empty,empty,empty,empty);
        has(plan(noGates,Map.of(Patch.TROLL,Travel.STONY),ReturnToBank.GLORY),"access requirement is not confirmed");
        Map<Integer,Integer> stock=new LinkedHashMap<>();stock.put(ItemID.LAWRUNE,20);stock.put(ItemID.AIRRUNE,20);
        PlanInputs immutable=input(stock,empty,0);stock.clear();
        has(plan(immutable,Map.of(Patch.CATHERBY,Travel.CAMELOT),ReturnToBank.WALK),"Law rune × 1\n   Carried 1");
        PlanInputs staff=new PlanInputs(1,99,99,99,0,2,8,true,false,"",FLAGS,Map.of(ItemID.LAWRUNE,1),empty,empty,empty);
        result=plan(staff,Map.of(Patch.CATHERBY,Travel.CAMELOT),ReturnToBank.WALK);
        no(result,"Air rune ×");has(result,"Keep it equipped");
        PlanInputs pouch=new PlanInputs(1,99,99,99,0,0,8,true,false,"",FLAGS,empty,empty,Map.of(ItemID.LAWRUNE,1,ItemID.AIRRUNE,5),empty);
        result=plan(pouch,Map.of(Patch.CATHERBY,Travel.CAMELOT),ReturnToBank.WALK);
        has(result,"Air rune × 5\n   Carried 5");
        PlanInputs full=new PlanInputs(1,99,99,99,0,0,28,true,false,"",FLAGS,empty,empty,empty,empty);
        has(plan(full,two,ReturnToBank.WALK),"Deposit items or adjust your setup");
        result=plan(input(empty,empty,0),two,ReturnToBank.WALK);
        checks++;if(result.indexOf("1. Falador")>result.indexOf("2. Catherby"))throw new AssertionError("Route order");
        checks++;if(immutable.sameState(input(empty,empty,0)))throw new AssertionError("Changed inventory must invalidate plan");
        PlanEngine.Report report=PlanEngine.report(input(empty,Map.of(ItemID.RANARR_SEED,100),0),
            choices(Map.of(Patch.CATHERBY,Travel.CAMELOT),ReturnToBank.FINISH,true));
        has(report.route,"Finish at Catherby");no(report.route,"Bank return");
        checks++;if(report.supplies.stream().noneMatch(x->x.id==ItemID.RANARR_SEED && x.need==1 && x.bank==100 && x.withdraw==1))
            throw new AssertionError("Bank stock must differ from withdrawal quantity");
        has(String.join(" ",report.problems),"Law rune");
        has(PlanEngine.unavailable(input(empty,empty,0),Travel.CATHERBY),"Lunar spellbook");
        checks++;if(!PlanEngine.unavailable(input(empty,empty,2),Travel.CATHERBY).isEmpty())throw new AssertionError("Lunar unlocked");
        report=PlanEngine.report(input(empty,empty,0),choices(Map.of(Patch.CATHERBY,Travel.CATHERBY),ReturnToBank.FINISH,true));
        has(report.route,"BLOCKED");has(String.join(" ",report.problems),"Lunar spellbook");
        System.out.println(checks+" plan checks passed");
    }
}

package com.herbrunplanner;
import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;
public final class PlannedStaffChecks
{
    private static int checks;
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static PlanInputs input(int worn,Set<Integer> gear)
    {return new PlanInputs(1,99,99,99,0,RuneEquipment.staff(worn),0,true,true,"Bank",Map.of(),Map.of(),worn>0?Map.of(worn,1):Map.of(),Map.of(),Map.of(ItemID.STAFF_OF_AIR,1,ItemID.LAWRUNE,20,ItemID.AIRRUNE,100)).withGear(gear);}
    private static PlanEngine.Report report(PlanInputs in)
    {return PlanEngine.evaluate(in,new PlanInputs.Choices(HERBS[4],Map.of(Patch.CATHERBY,Travel.CAMELOT,Patch.FALADOR,Travel.FALADOR),ReturnToBank.FINISH,Compost.ULTRA,true,true,true,true,false,false));}
    private static int need(PlanEngine.Report r,int id){return r.supplies.stream().filter(s->s.id==id).mapToInt(s->s.need).sum();}
    public static void main(String[] args)
    {
        PlanInputs in=input(0,Set.of(ItemID.STAFF_OF_AIR));PlanEngine.Report r=report(in);
        check(in.runeStaffMask==2,"Selected air staff supplies air");
        check(need(r,ItemID.AIRRUNE)==0,"Both casts omit air runes");
        check(need(r,ItemID.LAWRUNE)==2,"Other runes budgeted for both casts");
        check(need(r,ItemID.STAFF_OF_AIR)==1,"Only one staff requested");
        check(r.equipStaffRequired,"Banked staff requires equipping");
        check(r.blockedSteps==0,"Equip requirement does not change route availability scoring");
        r=report(input(ItemID.STAFF_OF_AIR,Set.of(ItemID.STAFF_OF_AIR)));
        check(!r.equipStaffRequired,"Equipping clears requirement");
        in=input(ItemID.STAFF_OF_WATER,Set.of(ItemID.STAFF_OF_AIR));
        check(in.runeStaffMask==2,"Selected staff replaces worn staff, does not combine");
        check(report(in).equipStaffRequired,"Wrong worn staff is not accepted");
        GearNames.equipment(ItemID.FAIRY_ENCHANTED_SECATEURS,3,false);
        in=input(ItemID.STAFF_OF_AIR,Set.of(ItemID.FAIRY_ENCHANTED_SECATEURS));
        check(in.runeStaffMask==0,"Non-elemental selected weapon removes worn staff benefit");
        check(need(report(in),ItemID.AIRRUNE)==8,"Replacement weapon requests all route air runes");
        check(input(ItemID.STAFF_OF_AIR,Set.of()).runeStaffMask==2,"No selected weapon preserves worn staff");
        check(input(0,Set.of(ItemID.STAFF_OF_AIR,ItemID.STAFF_OF_WATER)).runeStaffMask==0,"Malformed multi-staff gear never combines benefits");
        check(input(0,Set.of(ItemID.MIST_BATTLESTAFF)).runeStaffMask==6,"One combination staff retains both elements");
        check(in.withCompost(3,20).runeStaffMask==0,"Snapshot copies retain planned weapon");
        System.out.println(checks+" planned-staff checks passed.");
    }
}

package com.herbrunplanner;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

public class RuneSuppliesChecks
{
    private static int checks;
    private static void expect(boolean value)
    {
        if (!value) throw new AssertionError("Rune check " + (checks + 1));
        checks++;
    }
    public static void main(String[] args)
    {
        int[] camelot = {1,5,0,0,0,0,0,0};
        Map<Integer, Integer> inv = new HashMap<>(), bank = new HashMap<>();
        expect(RuneSupplies.oneCast(camelot, null, bank).contains("Unknown"));
        expect(RuneSupplies.oneCast(camelot, inv, null).contains("bank unknown"));
        expect(RuneSupplies.oneCast(camelot, inv, bank).contains("counted sources still short by 5"));
        inv.put(ItemID.LAWRUNE, 1);
        inv.put(ItemID.AIRRUNE, 5);
        expect(RuneSupplies.oneCast(camelot, inv, null).contains("Enough ordinary inventory"));
        inv.put(ItemID.AIRRUNE, 4);
        expect(RuneSupplies.oneCast(camelot, inv, bank).contains("inventory short by 1"));
        bank.put(ItemID.AIRRUNE, 10);
        String s = RuneSupplies.oneCast(camelot, inv, bank);
        expect(s.contains("Observed bank can cover"));
        expect(s.contains("withdraw 1 from observed bank stock"));
        expect(!s.contains("withdraw 10"));
        inv.clear(); bank.clear();
        bank.put(ItemID.LAWRUNE, 1); bank.put(ItemID.AIRRUNE, 3);
        s = RuneSupplies.oneCast(camelot, inv, bank);
        expect(s.contains("withdraw 3 from observed bank stock"));
        expect(s.contains("counted sources still short by 2"));
        expect(!s.contains("Observed bank can cover"));
        inv.put(ItemID.LAWRUNE, Integer.MAX_VALUE);
        inv.put(ItemID.AIRRUNE, Integer.MAX_VALUE);
