package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;

public final class TravelPlanningChecks
{
    private static int checks;
    private static final Map<Integer,Integer> EMPTY=Collections.emptyMap();
    private static PlanInputs input(Map<Integer,Integer> inv,Map<Integer,Integer> bank,Map<String,Boolean> flags)
    {return new PlanInputs(1,1,99,99,3,0,4,true,true,"Observed bank",flags,inv,EMPTY,EMPTY,bank);}
    private static PlanInputs.Choices choices(Map<Patch,Travel> patches,ReturnToBank bank)
    {return new PlanInputs.Choices(HERBS[4],patches,bank,Compost.ULTRA,true,true,true,false,true,false);}
    private static PlanEngine.Report report(PlanInputs input,Map<Patch,Travel> patches,ReturnToBank bank)
    {return PlanEngine.report(input,choices(patches,bank));}
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static PlanEngine.Supply supply(PlanEngine.Report r,int id)
    {return r.supplies.stream().filter(s->s.id==id).findFirst().orElseThrow(()->new AssertionError("Missing item "+id+"\n"+r.detail));}
    public static void main(String[] args)
    {
        PlanInputs low=input(Map.of(ItemID.LUNAR_TABLET_CATHERBY_TELEPORT,1),EMPTY,Collections.emptyMap());
        PlanEngine.Report r=report(low,Map.of(Patch.CATHERBY,Travel.AUTO),ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.CATHERBY)==Travel.CATHERBY_TAB,"Catherby tablet usable without Lunar/Magic levels");
        check(supply(r,ItemID.LUNAR_TABLET_CATHERBY_TELEPORT).have==1,"Counts carried tablet");
        check(r.supplies.stream().noneMatch(s->s.id==ItemID.LAWRUNE || s.id==ItemID.ASTRALRUNE),"Tablet must not require runes");
        r=report(low,Map.of(Patch.CATHERBY,Travel.CATHERBY_TAB),ReturnToBank.CATHERBY_TAB);
        check(supply(r,ItemID.LUNAR_TABLET_CATHERBY_TELEPORT).need==2,"Return consumes another tablet");
        check(supply(r,ItemID.LUNAR_TABLET_CATHERBY_TELEPORT).missing==1,"One tablet cannot pay twice");
        PlanInputs wrongQuest=input(Map.of(ItemID.POH_TABLET_ARDOUGNETELEPORT,1),EMPTY,Collections.emptyMap());
        check(!PlanEngine.unavailable(wrongQuest,Travel.ARDOUGNE_TAB).isEmpty(),"Ardougne tablet requires Plague City");
        PlanInputs plague=input(Map.of(ItemID.POH_TABLET_ARDOUGNETELEPORT,1),EMPTY,Map.of("PLAGUE_CITY",true));
        r=report(plague,Map.of(Patch.ARDOUGNE,Travel.AUTO),ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.ARDOUGNE)==Travel.ARDOUGNE_TAB,"Ardougne tablet selected with quest");
        r=report(input(Map.of(ItemID.LUNAR_TABLET_FISHING_GUILD_TELEPORT,1),EMPTY,Collections.emptyMap()),Map.of(Patch.ARDOUGNE,Travel.AUTO),ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.ARDOUGNE)==Travel.FISHING_TAB,"Fishing tablet has no Lunar quest gate");
        r=report(input(Map.of(ItemID.NZONE_TELETAB_KOUREND,1),EMPTY,Collections.emptyMap()),Map.of(Patch.HOSIDIUS,Travel.AUTO),ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.HOSIDIUS)==Travel.HOSIDIUS_TAB,"Already-made redirected tablet counted");
        r=report(input(Map.of(ItemID.JEWL_NECKLACE_OF_SKILLS_1,1),EMPTY,Collections.emptyMap()),Map.of(Patch.HOSIDIUS,Travel.AUTO),ReturnToBank.FINISH);
        check(r.route.contains("Woodcutting Guild entrance"),"Hosidius skills destination");
        r=report(input(Map.of(ItemID.JEWL_BRACELET_OF_COMBAT_1,1),EMPTY,Collections.emptyMap()),Map.of(Patch.ARDOUGNE,Travel.AUTO),ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.ARDOUGNE)==Travel.COMBAT,"Charged combat bracelet supported");
        r=report(input(Map.of(ItemID.JEWL_BRACELET_OF_COMBAT,1),EMPTY,Collections.emptyMap()),Map.of(Patch.ARDOUGNE,Travel.COMBAT),ReturnToBank.FINISH);
        check(supply(r,ItemID.JEWL_BRACELET_OF_COMBAT_6).missing==1,"Uncharged bracelet not usable");
        r=report(input(Map.of(ItemID.RING_OF_DUELING_1,1),EMPTY,Collections.emptyMap()),Map.of(Patch.FALADOR,Travel.MANUAL),ReturnToBank.AUTO);
        check(r.resolvedChoices.bankReturn==ReturnToBank.DUELING,"Dueling ring bank return");
        check(supply(r,ItemID.RING_OF_DUELING_1).need==1,"One charged ring budgeted");
        // Reserve two necklace charges for Guild and Hosidius by using the stocked tablet at Ardougne.
        Map<Patch,Travel> three=new EnumMap<>(Patch.class);
        three.put(Patch.GUILD,Travel.AUTO);three.put(Patch.ARDOUGNE,Travel.AUTO);three.put(Patch.HOSIDIUS,Travel.AUTO);
        r=report(input(Map.of(ItemID.JEWL_NECKLACE_OF_SKILLS_2,1),Map.of(ItemID.LUNAR_TABLET_FISHING_GUILD_TELEPORT,1),Collections.emptyMap()),three,ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.ARDOUGNE)==Travel.FISHING_TAB,"Whole-run comparison preserves scarce necklace charges");
        check(r.resolvedChoices.patches.get(Patch.HOSIDIUS)==Travel.SKILLS,"Reserved charge reaches Hosidius");
        check(supply(r,ItemID.JEWL_NECKLACE_OF_SKILLS_2).need==1,"Two uses share one 2-charge necklace");
        check(r.supplies.stream().noneMatch(s->s.id==ItemID.JEWL_NECKLACE_OF_SKILLS_6),"Must not suggest missing extra necklace");
        // Faster owned bank option should beat a slower carried option when coverage is equal.
        r=report(input(Map.of(ItemID.POH_TABLET_CAMELOTTELEPORT,1),Map.of(ItemID.LUNAR_TABLET_CATHERBY_TELEPORT,1),Collections.emptyMap()),Map.of(Patch.CATHERBY,Travel.AUTO),ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.CATHERBY)==Travel.CATHERBY_TAB,"Prefer faster owned teleport over fewer withdrawals");
        r=report(input(EMPTY,Map.of(ItemID.Placeholder.POH_TABLET_CAMELOTTELEPORT,50),Collections.emptyMap()),Map.of(Patch.CATHERBY,Travel.CAMELOT_TAB),ReturnToBank.FINISH);
        check(supply(r,ItemID.POH_TABLET_CAMELOTTELEPORT).missing==1,"Placeholder cannot provide teleport");
        r=report(input(EMPTY,null,Collections.emptyMap()),Map.of(Patch.CATHERBY,Travel.CAMELOT_TAB),ReturnToBank.FINISH);
        check(r.detail.contains("bank unknown: need"),"Unknown bank remains unknown");
        r=report(low,Map.of(Patch.CATHERBY,Travel.MANUAL),ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.CATHERBY)==Travel.MANUAL,"Explicit manual override respected");
        check(r.detail.contains("Supported alternatives:") && r.detail.contains("supplies detected"),"Actionable manual fallback explanation");
        check(!PlanEngine.unavailable(low,Travel.HARMONY_TAB).isEmpty(),"Harmony tablet retains quest gate");
        check(PlanEngine.unavailable(input(EMPTY,EMPTY,Map.of("THE_GREAT_BRAIN_ROBBERY",true)),Travel.HARMONY_TAB).isEmpty(),"Harmony tablet independent of Magic/book");
        r=report(input(Map.of(ItemID.TELETAB_FENK,1),EMPTY,Map.of("PRIEST_IN_PERIL",true)),Map.of(Patch.PHASMATYS,Travel.AUTO),ReturnToBank.FINISH);
        check(r.resolvedChoices.patches.get(Patch.PHASMATYS)==Travel.FENK_TAB,"Phasmatys alternative without Ghosts Ahoy");
        for(Travel t:Travel.values())if(t.item>0)check(PlanCatalog.stackable(t.item),"Tablet stacks: "+t);
        System.out.println(checks+" expanded travel checks passed.");
    }
}

