        check(r.travelShortfall==0 && r.resolvedChoices.patches.get(Patch.HOSIDIUS)==Travel.MANUAL,"One charge cannot cover two automatic steps");
        r=plan(input(Map.of(ItemID.POH_TABLET_CAMELOTTELEPORT,1),EMPTY),Map.of(Patch.CATHERBY,Travel.AUTO),ReturnToBank.AUTO,false);
