        r=plan(input(EMPTY,EMPTY),Map.of(Patch.GUILD,Travel.AUTO),ReturnToBank.FINISH,true);
        check(r.resolvedChoices.patches.get(Patch.GUILD)==Travel.SKILLS,"Opt-in allows acquisition suggestion");
        check(r.obtain.stream().anyMatch(s->s.id==ItemID.JEWL_NECKLACE_OF_SKILLS_6),"Acquisition item identified separately");
        check(r.resolvedChoices.includeObtain,"Mode retained through resolved choices");
        r=plan(input(EMPTY,EMPTY),Map.of(Patch.GUILD,Travel.SKILLS,Patch.ARDOUGNE,Travel.AUTO),ReturnToBank.FINISH,false);
        check(r.resolvedChoices.patches.get(Patch.ARDOUGNE)==Travel.MANUAL,"Explicit unowned jewellery cannot supply imaginary charges to automatic steps");
        check(!r.obtain.isEmpty(),"Unowned explicit override flagged as acquisition");
        r=plan(input(Map.of(ItemID.LAWRUNE,1,ItemID.AIRRUNE,5),EMPTY),Map.of(Patch.CATHERBY,Travel.AUTO),ReturnToBank.AUTO,false);
