package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;

public final class EndingChecks
{
    private static int checks;
    private static void check(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}
    private static PlanInputs.Choices choices(ReturnToBank bank)
    {return new PlanInputs.Choices(HERBS[4],Map.of(Patch.GUILD,Travel.SKILLS,Patch.FALADOR,Travel.MANUAL),bank,Compost.ULTRA,false,false,false,false,true,false);}
    public static void main(String[] args)
    {
        PlanInputs in=new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank open",Collections.emptyMap(),Map.of(ItemID.JEWL_NECKLACE_OF_SKILLS_1,1),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap());
        PlanEngine.Report r=PlanEngine.report(in,choices(ReturnToBank.AUTO));
        check(r.resolvedChoices.order.equals(Arrays.asList(Patch.FALADOR,Patch.GUILD)),"Guild should move last to replace unchecked return");
        check(r.resolvedChoices.bankReturn==ReturnToBank.GUILD_WALK,"Use local guild bank chest");
        check(r.travelShortfall==0,"Reordering must not invent extra charges");
        check(r.supplies.stream().anyMatch(s->s.id==ItemID.JEWL_NECKLACE_OF_SKILLS_1 && s.need==1),"One necklace use remains one charge");
        check(r.route.indexOf("Falador")<r.route.indexOf("Farming Guild"),"Report follows planned order");
        RunProgress progress=new RunProgress(r.resolvedChoices);
        check(progress.current().patch==Patch.FALADOR,"Active first step follows order");progress.advance(false);
        check(progress.current().patch==Patch.GUILD,"Next step is final guild patch");progress.advance(false);
        check(progress.current().bank && progress.current().travel.contains("Guild bank chest"),"Bank step uses selected ending");
        progress.back();check(progress.current().patch==Patch.GUILD,"Back follows reordered steps");
        check(PlanEngine.report(in,r.resolvedChoices).resolvedChoices.order.equals(r.resolvedChoices.order),"Resolved live refresh preserves order");
        r=PlanEngine.report(in,choices(ReturnToBank.FINISH));
        check(r.resolvedChoices.order.equals(Arrays.asList(Patch.GUILD,Patch.FALADOR)),"Finish preserves practical order");
        check(new RunProgress(r.resolvedChoices).steps.size()==2,"Finish adds no bank step");
        r=PlanEngine.report(in,choices(ReturnToBank.GUILD_WALK));
        check(r.resolvedChoices.order.get(1)==Patch.GUILD,"Explicit guild walk puts Guild last");
        PlanInputs.Choices noGuild=new PlanInputs.Choices(HERBS[4],Map.of(Patch.FALADOR,Travel.MANUAL),ReturnToBank.GUILD_WALK,Compost.ULTRA,false,false,false,false,true,false);
        check(PlanEngine.report(in,noGuild).blockedSteps>0,"Guild walk cannot be used without guild patch");
        try{choices(ReturnToBank.AUTO).withOrder(Arrays.asList(Patch.GUILD,Patch.GUILD));throw new AssertionError("Duplicate order accepted");}catch(IllegalArgumentException expected){checks++;}
        try{r.resolvedChoices.order.add(Patch.CATHERBY);throw new AssertionError("Mutable order");}catch(UnsupportedOperationException expected){checks++;}
        r=PlanEngine.report(in,choices(ReturnToBank.GLORY));
        check(r.resolvedChoices.order.equals(Arrays.asList(Patch.GUILD,Patch.FALADOR)) && r.resolvedChoices.bankReturn==ReturnToBank.GLORY,"Explicit bank teleport remains fixed");
        PlanInputs.Choices tie=new PlanInputs.Choices(HERBS[4],Map.of(Patch.GUILD,Travel.SKILLS,Patch.CATHERBY,Travel.MANUAL),ReturnToBank.AUTO,Compost.ULTRA,false,false,false,false,true,false);
        check(PlanEngine.report(in,tie).resolvedChoices.order.equals(tie.order),"Equal-scoring endings keep existing order");
        System.out.println(checks+" ending checks passed.");
    }
}

package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;

public final class TeleportUsesChecks
{
    private static int checks;
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static PlanInputs in(Map<Integer,Integer> items)
    {return new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank open",Map.of("Lumbridge Medium",true,"Ardougne Medium",true),items,Map.of(),Map.of(),Map.of());}
    private static PlanInputs.Choices choice(Patch p,Travel t)
    {return new PlanInputs.Choices(HERBS[4],Map.of(p,t),ReturnToBank.FINISH,Compost.ULTRA,false,false,false,false,true,false);}
    public static void main(String[] args)
    {
        check(TeleportUses.ringRemaining(0)==3 && TeleportUses.ringRemaining(3)==0,"Ring used counter is inverted");
        check(TeleportUses.ringRemaining(-1)==-1 && TeleportUses.ringRemaining(4)==-1,"Invalid counter stays unknown");
        PlanInputs ring=in(Map.of(ItemID.LUMBRIDGE_RING_MEDIUM,1));
        PlanInputs.Choices selected=choice(Patch.FALADOR,Travel.RING);
        PlanEngine.Report report=PlanEngine.report(ring.withTeleportUses(Map.of(Travel.RING,2)),selected);
        check(report.unconfirmedSteps==0 && report.blockedSteps==0,"Known positive uses require no checkbox");
        PlanInputs zero=ring.withTeleportUses(Map.of(Travel.RING,0));
        report=PlanEngine.report(zero,selected.withTransport(Set.of(TeleportUses.key(Travel.RING)),Travel.AUTO));
        check(report.blockedSteps==1,"Manual check cannot override detected zero");
        PlanInputs alternative=in(Map.of(ItemID.LUMBRIDGE_RING_MEDIUM,1,ItemID.POH_TABLET_FALADORTELEPORT,1)).withTeleportUses(Map.of(Travel.RING,0));
        report=PlanEngine.report(alternative,choice(Patch.FALADOR,Travel.AUTO));
        check(report.resolvedChoices.patches.get(Patch.FALADOR)==Travel.FALADOR_TAB,"Auto uses available alternative when ring exhausted");
        report=PlanEngine.report(ring,selected);
        check(report.unconfirmedSteps==1,"Unknown uses prompt for that item");
        report=PlanEngine.report(ring,selected.withTransport(Set.of(TeleportUses.key(Travel.CLOAK)),Travel.AUTO));
        check(report.unconfirmedSteps==1,"Checking cloak cannot confirm ring");
        report=PlanEngine.report(ring,selected.withTransport(Set.of(TeleportUses.key(Travel.RING)),Travel.AUTO));
        check(report.unconfirmedSteps==0,"Specific unknown-item confirmation accepted");
        check(TeleportUses.remaining(in(Map.of(ItemID.LUMBRIDGE_RING_HARD,1)).withTeleportUses(Map.of(Travel.RING,0)),Travel.RING)==Integer.MAX_VALUE,"Unlimited ring ignores limited-tier counter");
        check(ring.sameRequirements(zero) && !ring.sameState(zero),"Count updates refresh supplies without clearing requirements");
        ObservedTeleportUses observed=new ObservedTeleportUses();
        PlanInputs owned=in(Map.of(ItemID.XERIC_TALISMAN,1,ItemID.ARDY_CAPE_HARD,1));
        observed.message("Your talisman has 50 charges.",5,1);
        check(!observed.snapshot(0,owned,1).containsKey(Travel.XERIC),"Unscoped generic talisman message ignored");
        observed.click(ItemID.XERIC_TALISMAN,"Check",10);observed.message("Your talisman has 50 charges.",11,1);
        check(observed.snapshot(0,owned,1).get(Travel.XERIC)==50,"Checked Xeric message captured");
        observed.invalidateXeric();check(!observed.snapshot(0,owned,1).containsKey(Travel.XERIC),"Uncertain changes clear Xeric observation");
        observed.click(ItemID.XERIC_TALISMAN,"Check",20);observed.message("The talisman has one charge.",21,1);
        check(observed.snapshot(0,owned,1).get(Travel.XERIC)==1,"Singular charge parsed");
        observed.click(ItemID.XERIC_TALISMAN,"Check",30);observed.message("Your talisman has 500 charges.",40,1);
        check(!observed.snapshot(0,owned,1).containsKey(Travel.XERIC),"Late message is not attributed to stale check");
        observed.message("You have used 4 of your 5 Ardougne Farm teleports for today.",41,1);
        check(observed.snapshot(0,owned,1).get(Travel.CLOAK)==1,"Ardougne used/total message gives remaining uses");
        check(!observed.snapshot(0,in(Map.of(ItemID.ARDY_CAPE_MEDIUM,1)),1).containsKey(Travel.CLOAK),"Cloak count not applied to a different tier");
        check(!observed.snapshot(0,owned,2).containsKey(Travel.CLOAK),"Previous day's cloak count is not reused");
        observed.clear();check(!observed.snapshot(0,owned,2).containsKey(Travel.XERIC),"Session reset drops item observations");
        System.out.println(checks+" teleport-use checks passed.");
    }
}

