package com.herbrunplanner;

import static net.runelite.api.CollisionDataFlag.*;
import static com.herbrunplanner.PlanCatalog.Patch.*;
import net.runelite.api.gameval.ObjectID;
import java.util.function.BiPredicate;

public final class WalkingPathChecks
{
    private static int checks;
    private static final BiPredicate<Integer,Integer> LOADED=(x,y)->true;
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    private static LocalWalkingPath.Target target(int x,int y){return new LocalWalkingPath.Target(x,y,x,y);}
    public static void main(String[] args)
    {
        int[][] open=new int[12][12];
        LocalWalkingPath.Result straight=LocalWalkingPath.find(open,1,5,target(9,5),LOADED);
        check(straight.tiles.stream().allMatch(t->t.y==5),"Open eastward route stays straight");
        check(straight.tiles.size()==8,"Straight shortest path ends beside target");
        check(LocalWalkingPath.find(open,8,5,target(9,5),LOADED).tiles.size()==1,"Already beside patch");
        check(LocalWalkingPath.find(open,1,1,new LocalWalkingPath.Target(8,8,10,10),LOADED).tiles.size()==8,"Diagonal shortest route to multi-tile edge");
        check(LocalWalkingPath.find(open,1,1,target(9,9),(x,y)->x<5).tiles.isEmpty(),"Never route through unloaded tiles");
        check(LocalWalkingPath.find(null,1,1,target(2,2),LOADED).tiles.isEmpty(),"Missing map");
        check(LocalWalkingPath.find(open,-1,1,target(2,2),LOADED).tiles.isEmpty(),"Out of scene start");
        int[][] barrier=new int[12][12];
        for(int y=0;y<12;y++)barrier[5][y]=BLOCK_MOVEMENT_OBJECT;
        check(LocalWalkingPath.find(barrier,1,5,target(9,5),LOADED).tiles.isEmpty(),"Solid wall disconnects route");
        barrier[5][10]=0;
        LocalWalkingPath.Result detour=LocalWalkingPath.find(barrier,1,5,target(9,5),LOADED);
        check(detour.tiles.size()>straight.tiles.size(),"Detour goes through the gap");
        boolean gap=false;for(LocalWalkingPath.Tile tile:detour.tiles)if(tile.x==5 && tile.y==10)gap=true;
        check(gap,"Route traverses actual opening");
        int[][] corner=new int[4][4];corner[2][1]=BLOCK_MOVEMENT_OBJECT;
        check(!LocalWalkingPath.canMove(corner,1,1,1,1,LOADED),"No diagonal through object corner");
        corner[2][1]=0;corner[2][2]=BLOCK_MOVEMENT_SOUTH_WEST;
        check(!LocalWalkingPath.canMove(corner,1,1,1,1,LOADED),"Respect diagonal wall flags");
        corner[2][2]=0;corner[1][1]=BLOCK_MOVEMENT_EAST;
        check(!LocalWalkingPath.canMove(corner,1,1,1,0,LOADED),"Respect source wall flag");
        corner[1][1]=0;corner[2][1]=BLOCK_MOVEMENT_WEST;
        check(!LocalWalkingPath.canMove(corner,1,1,1,0,LOADED),"Respect destination wall flag");
        corner[2][1]=BLOCK_MOVEMENT_FLOOR;
        check(!LocalWalkingPath.canMove(corner,1,1,1,0,LOADED),"Water/floor collision");
        corner[2][1]=BLOCK_MOVEMENT_FLOOR_DECORATION;
        check(!LocalWalkingPath.canMove(corner,1,1,1,0,LOADED),"Floor decoration collision");
        int[][] blockedGoal=new int[5][5];blockedGoal[2][2]=BLOCK_MOVEMENT_OBJECT|BLOCK_MOVEMENT_NORTH|BLOCK_MOVEMENT_SOUTH|BLOCK_MOVEMENT_EAST|BLOCK_MOVEMENT_WEST;
        check(LocalWalkingPath.find(blockedGoal,0,0,target(2,2),LOADED).tiles.isEmpty(),"Cannot finish across a wall bordering patch");
        check(!LocalWalkingPath.find(new int[104][104],0,0,target(100,100),LOADED).tiles.isEmpty(),"Directed search can reach a distant loaded target");
        int[][] sealed=new int[104][104];sealed[100][100]=BLOCK_MOVEMENT_FULL|BLOCK_MOVEMENT_NORTH|BLOCK_MOVEMENT_SOUTH|BLOCK_MOVEMENT_EAST|BLOCK_MOVEMENT_WEST;
        check(LocalWalkingPath.find(sealed,0,0,target(100,100),LOADED).status.contains("Search limit"),"Unreachable target search remains bounded");
        check(HerbPatchObjects.herb(ObjectID.FARMING_HERB_PATCH_1),"Base farming object recognized");
        check(HerbPatchObjects.herb(ObjectID.MYARM_HERBPATCH),"Troll farming object recognized");
        check(HerbPatchObjects.herb(ObjectID.FARMING_HERB_PATCH_7) && HerbPatchObjects.herb(ObjectID.FARMING_HERB_PATCH_8) && HerbPatchObjects.herb(ObjectID.MY2ARM_HERBPATCH_ACCESS),"Guild Fortis and Weiss objects recognized");
        check(!HerbPatchObjects.herb(-1),"Unrelated object rejected");
        check(HerbPatchObjects.patch(12083)==FALADOR && HerbPatchObjects.patch(11321)==TROLL,"Target region mapping");
        check(HerbPatchObjects.patch(11325)==WEISS && HerbPatchObjects.patch(4922)==GUILD,"Northern patch mapping");
        check(HerbPatchObjects.patch(15148)==HARMONY && HerbPatchObjects.patch(6192)==FORTIS,"Island and Varlamore mapping");
        check(HerbPatchObjects.patch(6967)==HOSIDIUS && HerbPatchObjects.patch(14391)==PHASMATYS,"Kourend and Morytania mapping");
        check(HerbPatchObjects.patch(10548)==ARDOUGNE && HerbPatchObjects.patch(11062)==CATHERBY && HerbPatchObjects.patch(0)==null,"Remaining mapping and unknown region");
        System.out.println(checks+" walking-path checks passed.");
    }
}

package com.herbrunplanner;

import java.awt.*;
import java.util.*;
import javax.swing.*;
import static com.herbrunplanner.PlanCatalog.*;

public final class PreferenceChecks
{
    private static int checks;
    private static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    private static PlanInputs input(long account)
    {return new PlanInputs(account,99,99,99,0,0,0,true,false,"Unchecked",Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),null);}
    private static java.util.List<Component> all(Container c)
    {java.util.List<Component> out=new ArrayList<>();for(Component x:c.getComponents()){out.add(x);if(x instanceof Container)out.addAll(all((Container)x));}return out;}
    private static JCheckBox box(PlanPanel p,String label)
    {return (JCheckBox)all(p).stream().filter(x->x instanceof JCheckBox && ((JCheckBox)x).getText().equals(label)).findFirst().orElseThrow(AssertionError::new);}
    private static JComboBox<?> finish(PlanPanel p)
    {return (JComboBox<?>)all(p).stream().filter(x->x instanceof JComboBox && ((JComboBox<?>)x).getSelectedItem() instanceof ReturnToBank).findFirst().orElseThrow(AssertionError::new);}
    public static void main(String[] args)throws Exception
    {
        Map<Long,String> records=new HashMap<>();
        RunPreferences.Store store=new RunPreferences.Store(){public String load(long a){return records.get(a);}public void save(long a,String s){records.put(a,s);}};
        SwingUtilities.invokeAndWait(()->{
            PlanPanel first=new PlanPanel((id,label)->{},store);first.update(input(1));
            check(finish(first).getSelectedItem()==ReturnToBank.FINISH,"New account finishes at last patch");
            finish(first).setSelectedItem(ReturnToBank.AUTO);
            box(first,"Falador").doClick();box(first,"Show walking path").doClick();
            JCheckBox confirmation=(JCheckBox)all(first).stream().filter(x->x instanceof JCheckBox
                && "Installed and usable: House portal/nexus → Catherby".equals(((JCheckBox)x).getAccessibleContext().getAccessibleName())).findFirst().orElseThrow(AssertionError::new);
            confirmation.doClick();
            box(first,"External entry").doClick();
            String accountOne=records.get(1L);
            check(accountOne!=null,"Edits save immediately");first.dispose();
            PlanPanel restored=new PlanPanel((id,label)->{},store);restored.update(input(1));
            check(finish(restored).getSelectedItem()==ReturnToBank.AUTO,"Explicit ending survives recreation");
            check(!box(restored,"Falador").isSelected(),"Patch exclusion survives recreation");
            check(!box(restored,"Show walking path").isSelected(),"Walking preference survives recreation");
            check(records.get(1L).equals(accountOne),"Loading must not overwrite preferences");
            check(!accountOne.contains("POH_CATHERBY"),"House confirmations must not be saved");
            JCheckBox restoredConfirmation=(JCheckBox)all(restored).stream().filter(x->x instanceof JCheckBox
                && "Installed and usable: House portal/nexus → Catherby".equals(((JCheckBox)x).getAccessibleContext().getAccessibleName())).findFirst().orElseThrow(AssertionError::new);
            check(!restoredConfirmation.isSelected(),"House confirmation resets on login");
            check(box(restored,"External entry").isSelected(),"Network entry preference persists");
            check(!box(restored,"I checked my Ardougne cloak").isSelected(),"Charge confirmation resets");
            check(restored.bankPreparation()==null && restored.runOverlayState()==null,"No saved supplies or active run");
            restored.update(input(2));
            check(finish(restored).getSelectedItem()==ReturnToBank.FINISH,"Another account gets fresh ending");
            check(box(restored,"Falador").isSelected() && box(restored,"Show walking path").isSelected(),"Account choices are isolated");
            box(restored,"Show run overlay").doClick();
            check(records.get(1L).equals(accountOne),"Second account edits leave first unchanged");
            restored.update(input(1));check(!box(restored,"Show walking path").isSelected(),"Switching back restores first account");
            restored.suspend(true);restored.update(input(1));
            check(finish(restored).getSelectedItem()==ReturnToBank.AUTO,"Logout and login restores ending");restored.dispose();
        });
        RunPreferences bad=RunPreferences.decode("v1\nfinish=REMOVED\nwalking=garbage\n");
        check(bad.option("finish",ReturnToBank.FINISH)==ReturnToBank.FINISH,"Unknown enum falls back safely");
        check(bad.flag("walking",true),"Malformed boolean falls back safely");
        check(RunPreferences.decode("v99\nfinish=AUTO").values.isEmpty(),"Unknown schema does not restore stale data");
        check(!records.get(1L).contains("charges=") && !records.get(1L).contains("inventory="),"Transient state excluded from stored record");
        System.out.println(checks+" preference checks passed.");
    }
}

