    private static PlanInputs input(long account,int gear)
    {return new PlanInputs(account,99,99,99,0,0,0,true,true,"Bank",Map.of(),Map.of(),gear>0?Map.of(gear,1):Map.of(),Map.of(),Map.of());}
    private static JButton button(Container c,String text)
