        {if(x instanceof JButton && text.equals(((JButton)x).getText()))return (JButton)x;if(x instanceof Container){JButton b=button((Container)x,text);if(b!=null)return b;}}
        return null;
    }
    public static void main(String[] args)throws Exception
    {
        ObservedPatchCompletion p=new ObservedPatchCompletion();
        p.observe(1,4,32,true);check(!p.takeCompletion(3),"Unrelated inventory changes cannot complete a patch");
        p.planting(2,5,3,32);p.observe(3,4,32,true);
        check(!p.takeCompletion(3),"Planting alone waits for compost");
        p.composting(3);p.message("You treat the herb patch with ultracompost.",4,true);
        check(p.takeCompletion(3),"Planting and ultracompost complete the patch");
        check(!p.takeCompletion(3),"Completion emitted only once");
        p=new ObservedPatchCompletion();p.composting(1);p.message("You treat the herb patch with ultracompost.",2,true);
        p.planting(3,5,3,32);p.observe(4,4,32,true);check(p.takeCompletion(3),"Compost before planting is supported");
        p=new ObservedPatchCompletion();p.planting(1,5,3,32);p.observe(2,4,32,true);p.composting(2);
        p.message("You treat the herb patch with supercompost.",3,true);check(!p.takeCompletion(3),"Supercompost does not satisfy an ultra setup");
        p.composting(4);p.message("The herb patch has been treated with ultracompost.",5,true);check(p.takeCompletion(3),"Fertile Soil result supported");
        p=new ObservedPatchCompletion();p.planting(1,5,3,32);p.observe(32,4,32,true);p.composting(32);p.message("You treat the herb patch with ultracompost.",33,true);
        check(!p.takeCompletion(3),"Expired planting attempt cannot complete");
        p=new ObservedPatchCompletion();p.planting(1,5,3,32);p.observe(2,4,2,true);p.composting(2);p.message("You treat the herb patch with ultracompost.",3,true);
        check(!p.takeCompletion(3),"Dropping a seed and raking is not planting");
        p=new ObservedPatchCompletion();p.planting(1,5,3,32);p.observe(2,4,32,false);p.composting(2);p.message("You treat the herb patch with ultracompost.",3,false);
        check(!p.takeCompletion(3),"Remote observations rejected");
        p=new ObservedPatchCompletion();p.planting(1,5,3,32);p.observe(2,4,32,true);p.composting(2);p.message("You treat the herb patch with ultracompost.",33,true);
        check(!p.takeCompletion(3),"Expired compost message rejected");
        check(GearVariants.canonical(ItemID.GRACEFUL_HOOD_WORN)==ItemID.GRACEFUL_HOOD,"Worn graceful maps to its bank form");
        check(GearVariants.count(Map.of(ItemID.GRACEFUL_HOOD_WORN,1),ItemID.GRACEFUL_HOOD)==1,"Worn graceful counts as carried");
        check(GearVariants.canonical(ItemID.GRACEFUL_HOOD_HALLOWED_WORN)==ItemID.GRACEFUL_HOOD_HALLOWED,"Graceful colour is preserved");
        p=new ObservedPatchCompletion();p.composting(1);p.message("You treat the herb patch with ultracompost.",2,true);p.clearCompost();
        p.planting(20,5,3,32);p.observe(21,4,32,true);check(!p.takeCompletion(3),"Old crop compost cannot carry forward after its state changes");
        PlanInputs.Choices choices=new PlanInputs.Choices(HERBS[4],Map.of(Patch.FALADOR,Travel.MANUAL),ReturnToBank.FINISH,Compost.ULTRA,false,false,false,false,false,false);
