        check(report.supplies.stream().filter(s->s.id==ItemID.FAIRY_ENCHANTED_SECATEURS).allMatch(s->s.need==1 && s.have==1),"Gear shares an already-required item and counts worn equipment");
        check(input(1,0).withGear(Set.of(ItemID.SPADE)).withCompost(3,10).withTeleportUses(Map.of()).gear.contains(ItemID.SPADE),"Snapshot copies preserve saved gear");
        AutoStepRequest request=new AutoStepRequest(1,new RunProgress(choices),0);
