        checks++;
    }
    public static void main(String[] args)
    {
        BankSnapshot snapshot = new BankSnapshot();
        Map<Integer, Integer> inv = new HashMap<>(), worn = new HashMap<>(), bank = new HashMap<>();
        expect(snapshot.items() == null);
        expect(snapshot.status(false).contains("Bank unknown"));
