        expect(snapshot.items() != null && snapshot.items().isEmpty());
        expect(CarriedSupplies.render(inv, worn, snapshot.items(), snapshot.status(true)).contains("Not found in checked supplies"));
        bank.put(ItemID.JEWL_NECKLACE_OF_SKILLS_4, 2);
        expect(snapshot.items().isEmpty()); // defensive copy, not an aliased container
        snapshot.observe(bank, Instant.parse("2026-09-07T12:00:01Z"));
        String text = CarriedSupplies.render(inv, worn, snapshot.items(), snapshot.status(true));
        expect(text.contains("Skills necklace — In bank (observed)"));
        expect(text.contains("Bank (observed): 2 x Skills necklace — 4 charges per item"));
        expect(text.contains("withdraw 1 unnoted: Skills necklace — 4 charges"));
        inv.put(ItemID.JEWL_NECKLACE_OF_SKILLS_1, 1);
        text = CarriedSupplies.render(inv, worn, snapshot.items(), snapshot.status(false));
        expect(text.contains("Skills necklace — Carried"));
        expect(!text.contains("withdraw 1 unnoted"));
        expect(text.contains("Bank closed — last observed at"));
        inv.clear();
        inv.put(ItemID.JEWL_NECKLACE_OF_SKILLS, 1);
        text = CarriedSupplies.render(inv, worn, snapshot.items(), snapshot.status(false));
        expect(text.contains("withdraw 1 unnoted")); // empty carried necklace doesn't suppress charged bank option
        text = CarriedSupplies.render(null, worn, snapshot.items(), snapshot.status(false));
        expect(text.contains("Skills necklace — In bank (observed)"));
        expect(!text.contains("withdraw 1 unnoted")); // don't assume missing carried inventory
        bank.clear();
        bank.put(ItemID.Cert.AMULET_OF_GLORY_6, 1);
        bank.put(ItemID.Placeholder.AMULET_OF_GLORY_6, 1);
        text = CarriedSupplies.render(new HashMap<>(), worn, bank, "Observed");
        expect(text.contains("Amulet of glory — Not found in checked supplies"));
        bank.clear();
        bank.put(ItemID.ECTOPHIAL_EMPTY, 1);
        text = CarriedSupplies.render(new HashMap<>(), worn, bank, "Observed");
        expect(text.contains("Ectophial — In bank (observed)"));
        expect(!text.contains("withdraw 1 unnoted"));
        snapshot.observe(null, Instant.now());
        expect(snapshot.items().containsKey(ItemID.JEWL_NECKLACE_OF_SKILLS_4));
        snapshot.clear();
        expect(snapshot.items() == null && snapshot.status(false).contains("Bank unknown"));
        expect(CarriedSupplies.render(new HashMap<>(), worn, snapshot.items(), snapshot.status(false)).contains("bank unchecked"));
        System.out.println(checks + " bank-supply checks passed.");
    }
}

package com.herbrunplanner;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.ItemID;

public class CarriedSuppliesChecks
{
    private static int checks;
    private static void expect(String result, String fragment)
    {
        if (!result.contains(fragment)) throw new AssertionError("Missing: " + fragment + " in " + result);
        checks++;
    }

    public static void main(String[] args)
    {
        Map<Integer, Integer> inv = new HashMap<>();
        Map<Integer, Integer> worn = new HashMap<>();
        expect(CarriedSupplies.render(null, null), "Ectophial — Unknown");
        expect(CarriedSupplies.render(inv, worn), "Ectophial — Not carried (bank unchecked)");
        CarriedSupplies.add(inv, ItemID.ECTOPHIAL, 1);
        expect(CarriedSupplies.render(inv, worn), "Inventory: 1 x Filled ectophial");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.ECTOPHIAL_EMPTY, 1);
        expect(CarriedSupplies.render(inv, worn), "Empty ectophial — refill before use");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.AMULET_OF_GLORY_6, 1);
        CarriedSupplies.add(inv, ItemID.AMULET_OF_GLORY_6, 1);
        expect(CarriedSupplies.render(inv, worn), "Inventory: 2 x Glory — 6 charges per item");
        inv.clear();
        CarriedSupplies.add(worn, ItemID.AMULET_OF_GLORY_5, 1);
        expect(CarriedSupplies.render(inv, worn), "Equipped: 1 x Glory — 5 charges per item");
        expect(CarriedSupplies.render(inv, worn), "Amulet of glory — Carried");
        worn.clear();
        CarriedSupplies.add(inv, ItemID.AMULET_OF_GLORY, 1);
        expect(CarriedSupplies.render(inv, worn), "Glory — uncharged");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.TRAIL_AMULET_OF_GLORY_1, 1);
        expect(CarriedSupplies.render(inv, worn), "Trimmed glory — 1 charge per item");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.AMULET_OF_GLORY_INF, 1);
        expect(CarriedSupplies.render(inv, worn), "Eternal glory — unlimited charges");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.Cert.AMULET_OF_GLORY_6, 1);
        CarriedSupplies.add(inv, ItemID.Placeholder.AMULET_OF_GLORY_6, 1);
        expect(CarriedSupplies.render(inv, worn), "Amulet of glory — Not carried");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.JEWL_NECKLACE_OF_SKILLS_4, 1);
        expect(CarriedSupplies.render(inv, worn), "Skills necklace — 4 charges per item");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.JEWL_NECKLACE_OF_SKILLS, 1);
        expect(CarriedSupplies.render(inv, worn), "Skills necklace — uncharged");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.WEISS_TELEPORT_BASALT, 12);
        CarriedSupplies.add(inv, ItemID.STRONGHOLD_TELEPORT_BASALT, 4);
        expect(CarriedSupplies.render(inv, worn), "12 x Icy basalt");
        expect(CarriedSupplies.render(inv, worn), "4 x Stony basalt");
        inv.clear();
        CarriedSupplies.add(worn, ItemID.LUMBRIDGE_RING_EASY, 1);
        expect(CarriedSupplies.render(inv, worn), "no cabbage teleport");
        worn.clear();
        CarriedSupplies.add(worn, ItemID.LUMBRIDGE_RING_MEDIUM, 1);
        expect(CarriedSupplies.render(inv, worn), "daily teleports unverified");
        worn.clear();
        CarriedSupplies.add(worn, ItemID.ARDY_CAPE_EASY, 1);
        expect(CarriedSupplies.render(inv, worn), "no farm-patch teleport");
        worn.clear();
        CarriedSupplies.add(inv, ItemID.XERIC_TALISMAN, 1);
        expect(CarriedSupplies.render(inv, worn), "remaining charges unverified");
        expect(CarriedSupplies.render(inv, null), "equipment unknown");
        expect(CarriedSupplies.render(inv, null), "Xeric's talisman — Carried");
        inv.clear();
        CarriedSupplies.add(inv, ItemID.ECTOPHIAL, 0);
        CarriedSupplies.add(inv, -1, 1);
        expect(CarriedSupplies.render(inv, worn), "Ectophial — Not carried");
        System.out.println(checks + " carried-supply checks passed.");
    }
}

package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;

public final class ExtendedTravelChecks
{
    private static int checks;
    private static final Map<Integer,Integer> EMPTY=Collections.emptyMap();
    private static Map<String,Boolean> flags()
    {
        Map<String,Boolean> f=new HashMap<>();
        for(Travel t:Travel.values())if(t.gate!=null)f.put(t.gate,true);
        for(Patch p:Patch.values())if(p.gate!=null)f.put(p.gate,true);
        f.put("HOUSE_OWNED",true);f.put("HOUSE_HOSIDIUS",true);f.put("TREE_GNOME_VILLAGE",true);return f;
    }
    private static PlanInputs input(Map<Integer,Integer> inv,int book,Map<String,Boolean> flags)
    {return new PlanInputs(1,99,99,99,book,0,0,true,true,"Bank open",flags,inv,EMPTY,EMPTY,EMPTY);}
    private static PlanInputs.Choices choice(Map<Patch,Travel> patches,Set<String> checks,Travel entry)
    {return new PlanInputs.Choices(HERBS[4],patches,ReturnToBank.FINISH,Compost.ULTRA,true,true,false,false,true,false).withTransport(checks,entry);}
    private static void check(boolean v,String message){checks++;if(!v)throw new AssertionError(message);}
    private static int need(PlanEngine.Report r,int id){return r.supplies.stream().filter(s->s.id==id).mapToInt(s->s.need).sum();}
    private static PlanEngine.Report one(Travel method,Patch patch,int book,Map<Integer,Integer> inv)
    {return PlanEngine.evaluate(input(inv,book,flags()),choice(Map.of(patch,method),new HashSet<>(ExtendedTravel.CHECKS.keySet()),Travel.HOUSE_TAB));}
    public static void main(String[] args)
    {
        PlanEngine.Report r=one(Travel.ARDOUGNE,Patch.ARDOUGNE,0,Map.of(ItemID.LAWRUNE,2,ItemID.WATERRUNE,2));
        check(r.travelShortfall==0 && need(r,ItemID.LAWRUNE)==2 && need(r,ItemID.WATERRUNE)==2,"Ardougne spell recipe");
        r=one(Travel.FENK,Patch.PHASMATYS,3,Map.of(ItemID.LAWRUNE,1,ItemID.EARTHRUNE,1,ItemID.SOULRUNE,1));
        check(r.travelShortfall==0 && need(r,ItemID.SOULRUNE)==1,"Fenkenstrain spell recipe");
        r=one(Travel.BATTLEFRONT,Patch.GUILD,3,Map.of(ItemID.LAWRUNE,1,ItemID.EARTHRUNE,1,ItemID.FIRERUNE,1));
        check(r.travelShortfall==0 && need(r,ItemID.FIRERUNE)==1,"Battlefront spell recipe");
        r=one(Travel.FORTIS_TAB,Patch.FORTIS,2,Map.of(ItemID.POH_TABLET_FORTISTELEPORT,1));
        check(r.blockedSteps==0 && need(r,ItemID.POH_TABLET_FORTISTELEPORT)==1,"Tablet independent of spellbook");
        Map<Patch,Travel> houses=Map.of(Patch.WEISS,Travel.POH_WEISS,Patch.CATHERBY,Travel.POH_CATHERBY);
        Set<String> installed=Set.of("POH_WEISS","POH_CATHERBY");
        PlanInputs in=input(Map.of(ItemID.POH_TABLET_TELEPORTTOHOUSE,2),0,flags());
        r=PlanEngine.evaluate(in,choice(houses,installed,Travel.HOUSE_TAB));
        check(r.blockedSteps==0 && r.travelShortfall==0 && need(r,ItemID.POH_TABLET_TELEPORTTOHOUSE)==2,"Each house visit consumes entry tablet");
        check(need(r,ItemID.LAWRUNE)==0 && need(r,ItemID.WEISS_TELEPORT_BASALT)==0,"Installed portals need no destination consumables");
        check(r.resolvedChoices.travelChecks.equals(installed) && r.resolvedChoices.houseEntry==Travel.HOUSE_TAB,"Confirmations retained in resolved plan");
        check(new RunProgress(r.resolvedChoices).current().travel.contains("Teleport to House tablet"),"Active instructions include entry");
        r=PlanEngine.evaluate(in,choice(houses,Collections.emptySet(),Travel.HOUSE_TAB));
        check(r.blockedSteps==2,"House tablet cannot invent installed portals");
        Map<String,Boolean> homeless=flags();homeless.put("HOUSE_OWNED",false);
        check(PlanEngine.evaluate(input(in.inventory,0,homeless),choice(houses,installed,Travel.HOUSE_TAB)).blockedSteps==2,"Confirmations cannot bypass house ownership");
        r=PlanEngine.evaluate(input(Map.of(ItemID.POH_TABLET_TELEPORTTOHOUSE,1),0,flags()),choice(houses,installed,Travel.HOUSE_TAB));
        check(r.travelShortfall==1,"One house tablet cannot fund two trips");
        r=PlanEngine.report(input(Map.of(ItemID.LAWRUNE,2,ItemID.AIRRUNE,2,ItemID.EARTHRUNE,2),0,flags()),choice(houses,installed,Travel.AUTO));
        check(r.resolvedChoices.houseEntry==Travel.HOUSE_SPELL && r.travelShortfall==0,"Automatic house entry uses owned spell supplies");
        check(need(r,ItemID.LAWRUNE)==2 && need(r,ItemID.EARTHRUNE)==2,"Whole-run entry rune budget");
        Set<String> rings=Set.of("HOUSE_FAIRY_RING","FAIRY_ACCESS");
        PlanInputs.Choices fairy=choice(Map.of(Patch.GUILD,Travel.FAIRY_GUILD),rings,Travel.HOUSE_TAB);
        check(PlanEngine.evaluate(in,fairy).blockedSteps==1,"Fairy rings need staff without elite diary");
        r=PlanEngine.evaluate(input(Map.of(ItemID.DRAMEN_STAFF,1,ItemID.POH_TABLET_TELEPORTTOHOUSE,1),0,flags()),fairy);
        check(r.blockedSteps==0 && need(r,ItemID.DRAMEN_STAFF)==1,"Fairy staff is in loadout");
        Map<String,Boolean> elite=flags();elite.put("Lumbridge Elite",true);
        r=PlanEngine.evaluate(input(Map.of(ItemID.POH_TABLET_TELEPORTTOHOUSE,1),0,elite),fairy);
        check(r.blockedSteps==0 && need(r,ItemID.DRAMEN_STAFF)==0,"Elite fairy rings need no staff");
        PlanInputs.Choices destinationOnly=choice(Map.of(Patch.GUILD,Travel.SPIRIT_GUILD),Set.of("SPIRIT_GUILD_PLANTED"),Travel.HOUSE_TAB);
        check(PlanEngine.report(in,destinationOnly).blockedSteps==1,"Guild destination alone cannot unlock house entry");
        check(PlanEngine.report(in,choice(Map.of(Patch.GUILD,Travel.AUTO),Set.of("SPIRIT_GUILD_PLANTED"),Travel.AUTO)).resolvedChoices.patches.get(Patch.GUILD)!=Travel.SPIRIT_GUILD,"Automatic planning never invents a house spirit tree");
        PlanInputs.Choices tree=choice(Map.of(Patch.GUILD,Travel.SPIRIT_GUILD),Set.of("HOUSE_SPIRIT_TREE"),Travel.HOUSE_TAB);
        check(PlanEngine.evaluate(in,tree).blockedSteps==1,"Destination tree must be confirmed grown");
        r=PlanEngine.evaluate(in,tree.withTransport(Set.of("HOUSE_SPIRIT_TREE","SPIRIT_GUILD_PLANTED"),Travel.HOUSE_TAB));
        check(r.blockedSteps==0 && need(r,ItemID.POH_TABLET_TELEPORTTOHOUSE)==1,"House-to-grown-tree route budget");
        r=one(Travel.FARM_CAPE,Patch.GUILD,0,Map.of(ItemID.SKILLCAPE_FARMING_TRIMMED,1));
        check(r.travelShortfall==0 && need(r,ItemID.SKILLCAPE_FARMING_TRIMMED)==1,"Trimmed farming cape supported");
        Map<String,Boolean> low=flags();low.put("FARMING_99",false);
        check(PlanEngine.evaluate(input(Map.of(ItemID.SKILLCAPE_FARMING,1),0,low),choice(Map.of(Patch.GUILD,Travel.FARM_CAPE),Set.of(),Travel.AUTO)).blockedSteps==1,"Owned cape alone cannot bypass level check");
        r=PlanEngine.evaluate(input(Map.of(ItemID.HG_QUETZALWHISTLE_BASIC,1),0,flags()),choice(Map.of(Patch.FORTIS,Travel.QUETZAL),Set.of(),Travel.AUTO));
        check(r.blockedSteps==1,"Finite whistle needs charge confirmation");
        r=one(Travel.QUETZAL,Patch.FORTIS,0,Map.of(ItemID.HG_QUETZALWHISTLE_BASIC,1));
        check(r.blockedSteps==0 && need(r,ItemID.HG_QUETZALWHISTLE_BASIC)==1,"Confirmed finite whistle supported");
        r=PlanEngine.evaluate(input(Map.of(ItemID.HG_QUETZALWHISTLE_PERFECTED_INFINITE,1),0,flags()),choice(Map.of(Patch.FORTIS,Travel.QUETZAL),Set.of(),Travel.AUTO));
        check(r.blockedSteps==0 && r.travelShortfall==0,"Infinite whistle needs no charge confirmation");
        r=PlanEngine.evaluate(input(Map.of(ItemID.BOOK_OF_THE_DEAD,1),0,flags()),choice(Map.of(Patch.HOSIDIUS,Travel.MEMOIRS),Set.of(),Travel.AUTO));
        check(r.blockedSteps==1,"Book presence does not prove restored page or charges");
        for(int id:new int[]{ItemID.LUMBRIDGE_RING_HARD,ItemID.LUMBRIDGE_RING_ELITE})
        {r=one(Travel.RING,Patch.FALADOR,0,Map.of(id,1));check(r.unconfirmedSteps==0,"Unlimited ring tier has no charge warning");}
        r=one(Travel.RING,Patch.FALADOR,0,Map.of(ItemID.LUMBRIDGE_RING_MEDIUM,1));check(r.unconfirmedSteps==1,"Ring 2 remains limited");
        r=one(Travel.CLOAK,Patch.ARDOUGNE,0,Map.of(ItemID.ARDY_CAPE_ELITE,1));check(r.unconfirmedSteps==0,"Elite cloak is unlimited");
        r=one(Travel.CLOAK,Patch.ARDOUGNE,0,Map.of(ItemID.ARDY_CAPE_HARD,1));check(r.unconfirmedSteps==1,"Hard cloak remains limited");
        PlanInputs.Choices shared=new PlanInputs.Choices(HERBS[4],Map.of(Patch.FALADOR,Travel.GLORY),ReturnToBank.EDGEVILLE,Compost.ULTRA,true,true,true,false,true,false);
        r=PlanEngine.evaluate(input(Map.of(ItemID.AMULET_OF_GLORY_2,1),0,flags()),shared);
        check(need(r,ItemID.AMULET_OF_GLORY_2)==1 && r.travelShortfall==0,"Alternate glory destination shares charge pool");
        r=PlanEngine.evaluate(input(Map.of(ItemID.AMULET_OF_GLORY_1,1),0,flags()),shared);check(r.travelShortfall>0,"One glory charge cannot pay two destinations");
        check(PlanCatalog.jewelleryFamily(Travel.DUELING_FEROX)==Travel.DUELING,"Dueling variants share charge pool");
        PlanInputs.Choices externalFairy=fairy.withExternalNetworks(true).withTransport(Set.of("FAIRY_ACCESS"),Travel.HOUSE_TAB);
        r=PlanEngine.evaluate(input(Map.of(ItemID.AMULET_OF_GLORY_1,1,ItemID.DRAMEN_STAFF,1),0,homeless),externalFairy);
        check(r.blockedSteps==0 && r.travelShortfall==0 && need(r,ItemID.AMULET_OF_GLORY_1)==1,"External fairy entry needs no house and budgets glory");
        check(new RunProgress(r.resolvedChoices).current().travel.contains("DKR"),"External fairy instructions show the entry ring");
        PlanInputs.Choices externalTree=tree.withExternalNetworks(true).withTransport(Set.of("SPIRIT_GUILD_PLANTED"),Travel.HOUSE_TAB);
        r=PlanEngine.evaluate(input(Map.of(ItemID.RING_OF_WEALTH_I1,1),0,homeless),externalTree);
        check(r.blockedSteps==0 && need(r,ItemID.RING_OF_WEALTH_I1)==1,"External spirit entry budgets imbued wealth charge");
        check(r.resolvedChoices.externalNetworks,"External entry survives report copy");
        r=one(Travel.FARM_CAPE,Patch.GUILD,0,Map.of(ItemID.SKILLCAPE_MAX_WORN,1));
        check(r.travelShortfall==0 && need(r,ItemID.SKILLCAPE_MAX_WORN)==1,"Worn max cape item variant supported");
        r=one(Travel.HUNTER_CAPE,Patch.FORTIS,0,Map.of(ItemID.SKILLCAPE_HUNTING,1));
        check(r.unconfirmedSteps==0 && r.blockedSteps==0,"Hunter Guild cape destination does not use daily chinchompa allowance");
        check(ExtendedTravel.allowance(Travel.XERIC,ItemID.XERIC_TALISMAN),"Carried Xeric remains charge-limited");
        check(!PlanCatalog.name(ItemID.RING_OF_WEALTH_I1).startsWith("Item "),"Wealth variant has readable loadout name");
        // A plain Hosidius house needs no furniture confirmation to be a candidate.
        PlanInputs.Choices outside=choice(Map.of(Patch.HOSIDIUS,Travel.AUTO),Set.of(),Travel.AUTO);
        r=PlanEngine.report(input(Map.of(ItemID.POH_TABLET_TELEPORTTOHOUSE,1),0,flags()),outside);
        check(r.resolvedChoices.patches.get(Patch.HOSIDIUS)==Travel.POH_HOSIDIUS
            && r.resolvedChoices.houseEntry==Travel.HOUSE_TAB && need(r,ItemID.POH_TABLET_TELEPORTTOHOUSE)==1,
            "Automatic Hosidius outside-house route requires no furniture confirmation");
        r=PlanEngine.report(input(Map.of(ItemID.LAWRUNE,1,ItemID.AIRRUNE,1,ItemID.EARTHRUNE,1),0,flags()),outside);
        check(r.resolvedChoices.patches.get(Patch.HOSIDIUS)==Travel.POH_HOSIDIUS
            && r.resolvedChoices.houseEntry==Travel.HOUSE_SPELL && need(r,ItemID.LAWRUNE)==1,
            "Automatic Hosidius outside-house spell entry");
        Map<String,Boolean> elsewhere=flags();elsewhere.put("HOUSE_HOSIDIUS",false);
        r=PlanEngine.report(input(Map.of(ItemID.POH_TABLET_TELEPORTTOHOUSE,1),0,elsewhere),outside);
        check(r.resolvedChoices.patches.get(Patch.HOSIDIUS)!=Travel.POH_HOSIDIUS,
            "House in another town cannot provide Hosidius outside route");
        PlanInputs.Choices spells=choice(Map.of(Patch.ARDOUGNE,Travel.ARDOUGNE,Patch.CATHERBY,Travel.CAMELOT),Set.of(),Travel.AUTO);
        Map<Integer,Integer> runeStock=Map.of(ItemID.LAWRUNE,100,ItemID.WATERRUNE,100,ItemID.AIRRUNE,100,ItemID.EARTHRUNE,100);
        PlanInputs bankRunes=new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank open",flags(),EMPTY,EMPTY,EMPTY,runeStock);
        r=PlanEngine.report(bankRunes,spells);
        check(need(r,ItemID.LAWRUNE)==3 && need(r,ItemID.WATERRUNE)==2 && need(r,ItemID.AIRRUNE)==5,
            "Ardougne and Camelot combined whole-run rune totals");
        check(r.supplies.stream().filter(s->s.id==ItemID.LAWRUNE).allMatch(s->s.withdraw==3 && s.have==0),
            "Bank preparation requests all three law runes");
        PlanInputs partiallyWithdrawn=new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank open",flags(),Map.of(ItemID.LAWRUNE,2),EMPTY,EMPTY,Map.of(ItemID.LAWRUNE,98,ItemID.WATERRUNE,100,ItemID.AIRRUNE,100));
        r=PlanEngine.report(partiallyWithdrawn,r.resolvedChoices);
        BankPreparation.Row law=new BankPreparation(1,r,false).items.get(ItemID.LAWRUNE);
        check(law.need==3 && law.have==2 && law.withdraw==1 && law.color.equals(BankPreparation.GOLD),
            "Withdrawing Ardougne laws alone does not mark the whole run ready");
        PlanInputs pouchRunes=new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank open",flags(),Map.of(ItemID.BH_RUNE_POUCH,1),EMPTY,Map.of(ItemID.LAWRUNE,2),runeStock);
        r=PlanEngine.report(pouchRunes,spells);
        check(need(r,ItemID.LAWRUNE)==3 && r.supplies.stream().filter(s->s.id==ItemID.LAWRUNE).allMatch(s->s.withdraw==1),
            "Pouch covers only two of the three required law runes");
        PlanInputs.Choices withHouse=choice(Map.of(Patch.ARDOUGNE,Travel.ARDOUGNE,Patch.CATHERBY,Travel.CAMELOT,Patch.HOSIDIUS,Travel.POH_HOSIDIUS),Set.of(),Travel.AUTO);
        r=PlanEngine.report(bankRunes,withHouse);
        check(need(r,ItemID.LAWRUNE)==4 && need(r,ItemID.AIRRUNE)==6 && need(r,ItemID.WATERRUNE)==2 && need(r,ItemID.EARTHRUNE)==1,
            "Ardougne, Camelot and outside-house trip all contribute to rune budget");
        System.out.println(checks+" extended travel checks passed.");
    }
}

package com.herbrunplanner;

import net.runelite.api.gameval.ItemID;

public final class GearSetsChecks
{
    private static int count;
    private static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);count++;}
    public static void main(String[] args)
    {
        RunPreferences p=new RunPreferences();p.put("gear."+ItemID.GRACEFUL_HOOD_WORN,true);p.put("seed",123);
        GearSets s=GearSets.load(p);
        check(s.outfits.size()==1,"Legacy outfit migrated");
        check(s.current().items.contains(ItemID.GRACEFUL_HOOD),"Worn variants preserved as base item");
        int first=s.selected;
        GearSets.Outfit second=s.add("Travel gear");second.items.add(ItemID.FAIRY_ENCHANTED_SECATEURS);s.defaultId=first;s.save(p);
        check(!p.values.containsKey("gear."+ItemID.GRACEFUL_HOOD_WORN),"Legacy keys migrated on save");
        check(p.values.get("seed").equals("123"),"Unrelated preferences preserved");
        GearSets restored=GearSets.load(RunPreferences.decode(p.encode()));
        check(restored.outfits.size()==2,"Both sets round-trip");
        check(restored.selected==first,"Default wins over previous selection on login");
        check(restored.outfits.get(second.id).items.contains(ItemID.FAIRY_ENCHANTED_SECATEURS),"Inactive set contents retained");
        check(restored.outfits.get(second.id).name.equals("Travel gear"),"Set name retained");
        restored.defaultId=0;restored.selected=second.id;restored.save(p);
        check(GearSets.load(p).selected==second.id,"Without default retain last selected");
        p.put("outfitDefault",999);p.put("outfitSelected",999);
        check(GearSets.load(p).current()!=null,"Deleted or invalid selection falls back");
        check(GearSets.clean("a\nb=c").equals("a b c"),"Names cannot inject settings");
        check(GearSets.clean("x".repeat(80)).length()==50,"Names bounded for preference encoding");
        GearSets other=GearSets.load(new RunPreferences());
        check(other.current().items.isEmpty(),"New account has no inherited outfit");
        check(restored.outfits.size()==2,"Another account does not mutate first");
        int boots=ItemID.IKOV_BOOTSOFLIGHTNESS,wornBoots=ItemID.IKOV_BOOTSOFLIGHTNESSWORN;
        check(GearVariants.canonical(wornBoots)==boots,"Lightness worn form maps to inventory form");
        RunPreferences bootPrefs=new RunPreferences();bootPrefs.put("outfit.1.name","Boots");bootPrefs.put("outfit.1.item."+wornBoots,true);
        check(GearSets.load(bootPrefs).current().items.contains(boots),"Previously saved worn boots migrate");
        for(int state=0;state<3;state++)
        {
            java.util.Map<Integer,Integer> inv=state==0?java.util.Map.of(boots,1):java.util.Map.of();
            java.util.Map<Integer,Integer> eq=state==1?java.util.Map.of(wornBoots,1):java.util.Map.of();
            java.util.Map<Integer,Integer> bank=state==2?java.util.Map.of(boots,1):java.util.Map.of();
            PlanInputs in=new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank",java.util.Map.of(),inv,eq,java.util.Map.of(),bank).withGear(java.util.Set.of(boots));
            PlanInputs.Choices choice=new PlanInputs.Choices(PlanCatalog.HERBS[4],java.util.Map.of(PlanCatalog.Patch.CATHERBY,PlanCatalog.Travel.MANUAL),PlanCatalog.ReturnToBank.FINISH,PlanCatalog.Compost.ULTRA,true,true,true,true,false,false);
            PlanEngine.Supply supply=PlanEngine.evaluate(in,choice).supplies.stream().filter(item->item.id==boots).findFirst().orElseThrow(AssertionError::new);
            check(supply.missing==0,"Boots recognized in state "+state);
            check(supply.withdraw==(state==2?1:0),"Withdraw only banked boots in state "+state);
        }
        System.out.println(count+" gear-set checks passed.");
    }
}

package com.herbrunplanner;

import java.awt.*;
import java.awt.event.MouseEvent;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.BooleanSupplier;
import javax.swing.*;
import javax.swing.border.LineBorder;
import net.runelite.api.gameval.ItemID;

/** Standalone Swing checks; no RuneLite client or game interaction. */
public final class LivePlanChecks
{
    private static PlanPanel panel;
    private static int checks;
    private static final Color GREEN=new Color(109,180,130), GOLD=new Color(220,179,92);
    private static PlanInputs input(int carried,int bank)
    {
        return new PlanInputs(1,99,99,99,0,0,carried,true,true,"Bank observed",Collections.emptyMap(),
            Map.of(ItemID.SPADE,carried),Collections.emptyMap(),Collections.emptyMap(),Map.of(ItemID.SPADE,bank));
    }
    private static java.util.List<Component> components(Container parent)
    {
        java.util.List<Component> out=new ArrayList<>();
        for(Component c:parent.getComponents()){out.add(c);if(c instanceof Container)out.addAll(components((Container)c));}
        return out;
    }
    private static JButton button(String label)
    {
        return (JButton)components(panel).stream().filter(c->c instanceof JButton && ((JButton)c).getText().equals(label)).findFirst().orElseThrow(AssertionError::new);
    }
    private static JCheckBox runFilter()
    {return (JCheckBox)components(panel).stream().filter(c->c instanceof JCheckBox && ((JCheckBox)c).getText().equals("Show run items")).findFirst().orElseThrow(AssertionError::new);}
    private static JPanel spade()
    {
        return (JPanel)components(panel).stream().filter(c->c instanceof JPanel && ((JPanel)c).getToolTipText()!=null
            && ((JPanel)c).getToolTipText().startsWith("Spade ")).findFirst().orElse(null);
    }
    private static boolean color(Color value)
    {JPanel tile=spade();return tile!=null && ((LineBorder)tile.getBorder()).getLineColor().equals(value);}
    private static boolean text(String value)
    {return components(panel).stream().anyMatch(c->c instanceof JTextArea && ((JTextArea)c).getText().contains(value));}
    private static void edt(Runnable action)throws Exception{SwingUtilities.invokeAndWait(action);}
    private static void await(BooleanSupplier condition)throws Exception
    {
        CompletableFuture<Void> done=new CompletableFuture<>();
        edt(()->{
            javax.swing.Timer poll=new javax.swing.Timer(20,null);
            long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);
            poll.addActionListener(e->{try{
                if(condition.getAsBoolean()){poll.stop();done.complete(null);}
                else if(System.nanoTime()>deadline){poll.stop();done.completeExceptionally(new AssertionError("Timed out"));}
            }catch(Throwable ex){poll.stop();done.completeExceptionally(ex);}});poll.start();
        });
        done.get(6,TimeUnit.SECONDS);checks++;
    }
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    public static void main(String[] args)throws Exception
    {
        try
        {
            edt(()->{panel=new PlanPanel();panel.update(input(0,1));button("Prepare run").doClick();});
            await(()->color(GOLD));
            edt(()->{
                check(!panel.showRunItems(),"Run filter should begin off");
                panel.toggleRunItems(999);check(!panel.showRunItems(),"Stale-account bank click must be ignored");
                panel.toggleRunItems(1);check(panel.showRunItems() && runFilter().isSelected(),"Bank button must synchronize sidebar checkbox");
                panel.toggleRunItems(1);check(!panel.showRunItems() && !runFilter().isSelected(),"Bank button switches both controls off");
                runFilter().doClick();check(panel.showRunItems(),"Toggle must enable filter");
                runFilter().doClick();check(!panel.showRunItems(),"Toggle must disable filter");
                runFilter().doClick();
            });
            edt(()->check(panel.bankPreparation()!=null && panel.bankPreparation().items.get(ItemID.SPADE).withdraw==1,"Bank overlay must publish withdrawal quantity"));
            edt(()->{
                JPanel tile=spade();
                for(java.awt.event.MouseListener listener:tile.getMouseListeners())listener.mouseClicked(new MouseEvent(tile,MouseEvent.MOUSE_CLICKED,0,0,1,1,1,false));
                panel.update(input(1,0));
                check(panel.bankSearchPreparation()!=null,"Search item set must stay available during automatic quantity refresh");
            });
            await(()->color(GREEN) && text("Spade\nNeed 1 · Have 1\nBank 0 · Missing 0\nWithdraw 0"));
            edt(()->{check(panel.bankPreparation().items.get(ItemID.SPADE).color.equals(GREEN),"Bank overlay must turn carried items green");check(panel.showRunItems() && runFilter().isSelected(),"Quantity refresh must keep toggle selected");});
            edt(()->panel.update(input(0,1)));
            await(()->color(GOLD) && text("Spade\nNeed 1 · Have 0\nBank 1 · Missing 0\nWithdraw 1"));
            // Region loading must keep the rendered run and resume updates without Prepare.
            edt(()->{
                panel.suspend(false);
                check(panel.bankPreparation()==null,"Loading must hide overlay quantities");
                check(spade()!=null,"Region loading removed the bank grid");
                check(text("1. Farming Guild"),"Region loading removed the route");
                check(!button("Prepare run").isEnabled(),"Preparing with a loading snapshot must be disabled");
                panel.suspend(false);
                check(spade()!=null,"Repeated loading removed the prepared result");
                panel.update(input(1,0));
            });
            await(()->color(GREEN) && text("Supplies update automatically"));
            edt(()->{panel.suspend(false);panel.update(input(1,0));});
            await(()->color(GREEN) && !text("Loading map") && text("Supplies update automatically"));
            edt(()->check(panel.showRunItems(),"Map resume must retain run filter choice"));
            edt(()->panel.update(new PlanInputs(1,99,99,99,0,0,1,true,false,"Bank closed",Collections.emptyMap(),
                Map.of(ItemID.SPADE,1),Collections.emptyMap(),Collections.emptyMap(),Map.of(ItemID.SPADE,0))));
            await(()->text("Supplies update automatically"));
            edt(()->{check(panel.showRunItems(),"Bank close must retain filter choice");panel.update(input(1,0));});
            await(()->text("Supplies update automatically"));
            edt(()->check(panel.showRunItems(),"Bank reopen must retain filter choice"));
            // Rapid snapshots must display the newest state even with a worker in flight.
            edt(()->{panel.update(input(1,0));panel.update(input(0,1));panel.update(input(1,0));});
            await(()->color(GREEN));
            // Supply refreshes must not pull the user out of Setup.
            edt(()->{
                JTabbedPane tabs=(JTabbedPane)components(panel).stream().filter(c->c instanceof JTabbedPane).findFirst().get();
                tabs.setSelectedIndex(0);panel.update(input(0,1));
            });
            await(()->color(GOLD));
            edt(()->{
                JTabbedPane tabs=(JTabbedPane)components(panel).stream().filter(c->c instanceof JTabbedPane).findFirst().get();
                check(tabs.getSelectedIndex()==0,"Automatic refresh switched tabs");
                panel.update(input(1,0));panel.suspend(true);
            });
            await(()->text("Waiting for account data") && spade()==null);
            edt(()->panel.update(input(1,0)));
            edt(()->check(spade()==null,"Logout must forget prepared plan"));
            // Frozen automatic travel stays fixed when stock changes.
            PlanInputs before=input(0,1);
            PlanInputs.Choices choice=new PlanInputs.Choices(PlanCatalog.HERBS[4],Map.of(PlanCatalog.Patch.FALADOR,PlanCatalog.Travel.AUTO),
                PlanCatalog.ReturnToBank.AUTO,PlanCatalog.Compost.ULTRA,true,true,true,false,true,false);
            PlanEngine.Report first=PlanEngine.report(before,choice);
            PlanInputs after=new PlanInputs(1,99,99,99,0,0,1,true,true,"",Collections.emptyMap(),
                Map.of(ItemID.LAWRUNE,100,ItemID.AIRRUNE,100,ItemID.WATERRUNE,100),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap());
            PlanEngine.Report refreshed=PlanEngine.report(after,first.resolvedChoices);
            check(first.route.equals(refreshed.route),"Banking changed automatic travel");
            check(before.sameRequirements(after),"Supply changes should permit refresh");
            edt(()->{
                panel.update(new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank observed",Collections.emptyMap(),
                    Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Map.of(ItemID.SPADE,1)));
                button("Prepare run").doClick();
            });
            await(()->color(new Color(105,175,225)) && text("Collect from leprechaun"));
            edt(()->panel.update(new PlanInputs(1,99,99,99,0,0,1,true,true,"Bank observed",Collections.emptyMap(),
                Map.of(ItemID.SPADE,1),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Map.of(ItemID.SPADE,0))));
            await(()->color(GREEN));
            edt(()->{
                panel.suspend(false);
                panel.update(new PlanInputs(999,99,99,99,0,0,0,true,false,"Unknown",Collections.emptyMap(),
                    Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),null));
                check(spade()==null,"Different account inherited the retained run");
                check(panel.bankPreparation()==null,"Other account inherited overlay");
                check(panel.bankSearchPreparation()==null,"Other account inherited bank filter");
                check(!panel.showRunItems(),"Other account inherited filter toggle");
                panel.toggleRunItems(1);check(!panel.showRunItems(),"Queued click cannot affect another account");
            });
            System.out.println(checks+" live-plan checks passed.");
        }
        finally{if(panel!=null)edt(()->panel.dispose());}
    }
}

package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;

public final class BottomlessChecks
{
    private static int checks;
    private static void check(boolean ok,String reason){checks++;if(!ok)throw new AssertionError(reason);}
    private static PlanInputs input(boolean carried,boolean bank,int type,int charges)
    {return new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank",Map.of(),
        carried?Map.of(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED,1):Map.of(),Map.of(),Map.of(),
        bank?Map.of(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED,1):Map.of()).withCompost(type,charges);}
    private static int need(PlanEngine.Report r,int id)
    {return r.supplies.stream().filter(s->s.id==id).mapToInt(s->s.need).sum();}
    public static void main(String[] args)
    {
        PlanInputs.Choices c=new PlanInputs.Choices(HERBS[4],Map.of(Patch.FALADOR,Travel.MANUAL,Patch.CATHERBY,Travel.MANUAL),ReturnToBank.FINISH,Compost.ULTRA,false,false,false,false,false,false);
        PlanEngine.Report r=PlanEngine.report(input(true,false,3,2),c);
        check(need(r,ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED)==1 && need(r,ItemID.BUCKET_ULTRACOMPOST)==0,"Carried bucket covers both patches");
        r=PlanEngine.report(input(false,true,3,2),c);
        check(r.supplies.stream().anyMatch(s->s.id==ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED && s.withdraw==1),"Bank bucket must be withdrawn");
        r=PlanEngine.report(input(true,false,3,1),c);
        check(need(r,ItemID.BUCKET_ULTRACOMPOST)==1,"Partial bucket uses loose compost for the remainder; charges are not doubled");
        check(BottomlessCompost.available(input(true,false,2,50),Compost.ULTRA)==0,"Wrong type is not ultracompost");
        check(BottomlessCompost.available(input(false,false,3,50),Compost.ULTRA)==0,"Stored quantity alone does not imply bucket ownership");
        check(BottomlessCompost.available(input(true,false,3,0),Compost.ULTRA)==0,"Empty bucket gives no applications");
        check(BottomlessCompost.available(input(true,false,0,50),Compost.ULTRA)==0,"Unknown type gives no applications");
        check(BottomlessCompost.available(input(true,false,3,-1),Compost.ULTRA)==0,"Unknown count gives no applications");
        check(!input(true,false,3,1).sameState(input(true,false,3,2)),"Charge change refreshes supplies");
        check(input(true,false,3,1).sameRequirements(input(true,false,3,2)),"Using compost does not invalidate the route");
        check(BottomlessCompost.available(input(true,false,3,2).withTeleportUses(Map.of()),Compost.ULTRA)==2,"Teleport copy retains compost");
        System.out.println(checks+" bottomless checks passed.");
    }
}

package com.herbrunplanner;

import java.util.*;
import static com.herbrunplanner.PlanCatalog.*;

public final class TravelTimeChecks
{
    private static int checks;
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    public static void main(String[] args)
    {
        for(Patch patch:Patch.values())for(Travel method:patch.methods)
            check(TravelTime.seconds(patch,method)>0,"Missing supported timing: "+patch+" / "+method);
        check(TravelTime.seconds(Patch.CATHERBY,Travel.CATHERBY_TAB)<TravelTime.seconds(Patch.CATHERBY,Travel.CAMELOT_TAB),"Direct Catherby teleport should be faster");
        check(TravelTime.seconds(Patch.FALADOR,Travel.MANUAL)==-1,"Manual travel cannot be timed as zero");
        PlanInputs.Choices c=new PlanInputs.Choices(HERBS[4],Map.of(Patch.CATHERBY,Travel.CATHERBY_TAB),ReturnToBank.FINISH,Compost.ULTRA,false,false,false,false,true,false);
        check(TravelTime.total(c)==15 && TravelTime.unknown(c)==0,"Finish adds no bank leg");
        c=new PlanInputs.Choices(HERBS[4],Map.of(Patch.CATHERBY,Travel.CATHERBY_TAB,Patch.FALADOR,Travel.MANUAL),ReturnToBank.MANUAL,Compost.ULTRA,false,false,false,false,true,false);
        check(TravelTime.unknown(c)==2 && TravelTime.summary(c).contains("timed legs only"),"Partial estimates must not pretend to cover full run");
        check(TravelTime.summary(c).contains("calibration"),"Estimates identify provisional basis");
        check(TravelTime.bankSeconds(ReturnToBank.DUELING)<TravelTime.bankSeconds(ReturnToBank.WALK),"Bank return timing participates in comparison");
        System.out.println(checks+" travel-time checks passed.");
    }
}

