package com.herbrunplanner;

import java.awt.*;
import java.awt.event.MouseEvent;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.BooleanSupplier;
import javax.swing.*;
import javax.swing.border.LineBorder;
import net.runelite.api.gameval.ItemID;

/** Standalone Swing checks; no RuneLite client or game interaction. */
public final class RunModeChecks
{
    private static PlanPanel panel;
    private static int checks;
    private static final Color GREEN=new Color(109,180,130), GOLD=new Color(220,179,92);
    private static PlanInputs input(int carried,int bank)
    {
        return new PlanInputs(1,99,99,99,0,0,carried,true,true,"Bank observed",Collections.emptyMap(),
            Map.of(ItemID.SPADE,carried),Collections.emptyMap(),Collections.emptyMap(),Map.of(ItemID.SPADE,bank));
    }
    private static java.util.List<Component> components(Container parent)
    {
        java.util.List<Component> out=new ArrayList<>();
        for(Component c:parent.getComponents()){out.add(c);if(c instanceof Container)out.addAll(components((Container)c));}
        return out;
    }
    private static JButton button(String label)
    {
        return (JButton)components(panel).stream().filter(c->c instanceof JButton && ((JButton)c).getText().equals(label)).findFirst().orElseThrow(AssertionError::new);
    }
    private static JPanel spade()
    {
        return (JPanel)components(panel).stream().filter(c->c instanceof JPanel && ((JPanel)c).getToolTipText()!=null
            && ((JPanel)c).getToolTipText().startsWith("Spade ")).findFirst().orElse(null);
    }
    private static boolean color(Color value)
    {JPanel tile=spade();return tile!=null && ((LineBorder)tile.getBorder()).getLineColor().equals(value);}
    private static boolean text(String value)
    {return components(panel).stream().anyMatch(c->c instanceof JTextArea && ((JTextArea)c).getText().contains(value));}
    private static void edt(Runnable action)throws Exception{SwingUtilities.invokeAndWait(action);}
    private static void await(BooleanSupplier condition)throws Exception
    {
        CompletableFuture<Void> done=new CompletableFuture<>();
        edt(()->{
            javax.swing.Timer poll=new javax.swing.Timer(20,null);
            long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);
            poll.addActionListener(e->{try{
                if(condition.getAsBoolean()){poll.stop();done.complete(null);}
                else if(System.nanoTime()>deadline){poll.stop();done.completeExceptionally(new AssertionError("Timed out"));}
            }catch(Throwable ex){poll.stop();done.completeExceptionally(ex);}});poll.start();
        });
        done.get(6,TimeUnit.SECONDS);checks++;
    }
    private static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
    public static void main(String[] args)throws Exception
    {
        PlanInputs.Choices options=new PlanInputs.Choices(PlanCatalog.HERBS[4],
            Map.of(PlanCatalog.Patch.FALADOR,PlanCatalog.Travel.FALADOR,PlanCatalog.Patch.CATHERBY,PlanCatalog.Travel.CAMELOT),
            PlanCatalog.ReturnToBank.WALK,PlanCatalog.Compost.ULTRA,true,true,true,false,true,false);
        RunProgress progress=new RunProgress(options);
        check(progress.steps.size()==3,"Bank return must be a separate step");
        RunOverlayState firstOverlay=new RunOverlayState(1,progress);
        check(firstOverlay.heading.equals("Falador · 1 of 2"),"Patch denominator must exclude bank return");
        check(firstOverlay.instructions.contains(PlanCatalog.Travel.FALADOR.label),"Overlay must use chosen teleport");
        progress.back();check(progress.index()==0,"Back must stop at first step");
        progress.advance(false);progress.advance(true);
        check(progress.current().bank,"Bank return must follow patches");
        check(new RunOverlayState(1,progress).heading.equals("Bank return"),"Bank step must have its own heading");
        check(firstOverlay.heading.equals("Falador · 1 of 2"),"Published overlay must be immutable");
        progress.back();check(progress.count(RunProgress.State.SKIPPED)==0 && progress.index()==1,"Back must undo skipped step");
        progress.advance(false);progress.advance(false);progress.advance(false);
        check(progress.complete() && progress.count(RunProgress.State.DONE)==3,"Completion must stay within route");
        check(new RunOverlayState(1,progress).complete,"Completion must publish an overlay summary");
        progress.back();check(!progress.complete() && progress.current().bank,"Back from completion must restore bank step");
        RunProgress finish=new RunProgress(new PlanInputs.Choices(PlanCatalog.HERBS[4],
            Map.of(PlanCatalog.Patch.FALADOR,PlanCatalog.Travel.MANUAL),PlanCatalog.ReturnToBank.FINISH,
            PlanCatalog.Compost.ULTRA,true,true,true,false,true,false));
        check(finish.steps.size()==1,"Finish at patch must not add a bank step");
        try
        {
            edt(()->{panel=new PlanPanel();panel.update(input(1,0));button("Prepare run").doClick();});
            await(()->text("Supplies update automatically"));
            edt(()->{
                JCheckBox filter=(JCheckBox)components(panel).stream().filter(c->c instanceof JCheckBox && ((JCheckBox)c).getText().equals("Show run items")).findFirst().orElseThrow(AssertionError::new);
                filter.doClick();check(panel.showRunItems(),"Preparation filter enables");
                button("Start run").doClick();check(!panel.showRunItems(),"Start run clears filter toggle");
                panel.toggleRunItems(1);check(!panel.showRunItems(),"Queued header click after Start cannot re-enable bank filter");
                check(text("Run in progress") && spade()==null,"Start must replace bank checklist");
                check(panel.bankPreparation()==null,"Starting run must hide bank helper");
                check(panel.bankSearchPreparation()==null,"Starting run must clear bank filter");
                check(panel.runOverlayState()!=null && panel.runOverlayState().heading.startsWith("Farming Guild"),"Starting must publish current patch");
                check(panel.walkRequest()!=null,"Walking starts enabled by default");
                check(panel.walkRequest().patch==PlanCatalog.Patch.GUILD,"Walking target matches active patch");
                button("Hide run overlay").doClick();check(panel.runOverlayState()==null,"Hide must remove run overlay");
                check(panel.walkRequest()!=null,"Walking remains enabled when text overlay is hidden");
                button("Show run overlay").doClick();check(panel.runOverlayState()!=null,"Show must restore current step");
                check(!button("Back").isEnabled(),"First step must disable Back");
                button("Done").doClick();button("Skip").doClick();button("Back").doClick();
                check(text("Next:"),"Current step must show next destination");
                check(panel.runOverlayState().heading.startsWith("Falador"),"Done Skip Back must update overlay");
                check(panel.walkRequest().patch==PlanCatalog.Patch.FALADOR,"Done Skip Back updates walking destination");
                button("Hide walking path").doClick();check(panel.walkRequest()==null,"Walking toggle clears request");
                button("Show walking path").doClick();
                panel.update(input(0,0));
                check(text("Run in progress") && spade()==null,"Consumption must not restore preparation shortages");
                check(text("DONE · Farming Guild"),"Supply update must preserve completed step");
                panel.suspend(false);check(text("run progress retained"),"Loading must retain active run");
                check(panel.runOverlayState()!=null && panel.runOverlayState().heading.startsWith("Falador"),"Loading must retain overlay");
                check(panel.walkRequest().patch==PlanCatalog.Patch.FALADOR,"Loading retains intended walking destination");
                panel.update(input(0,0));check(text("DONE · Farming Guild"),"Loading resume must preserve progress");
                int limit=20;
                while(!text("Run checklist complete") && limit-->0)button("Done").doClick();
                check(limit>0,"Run must finish including bank return");
                button("Back").doClick();check(text("Run in progress"),"Back must reopen completed run");
                button("Done").doClick();button("Prepare another run").doClick();
                check(button("Prepare run").isEnabled(),"Another run must restore preparation");
                check(panel.runOverlayState()==null,"New preparation must clear run overlay");
                check(panel.walkRequest()==null,"End run clears walking request");
                button("Prepare run").doClick();
            });
            await(()->text("Supplies update automatically"));
            edt(()->{
                button("Start run").doClick();button("End run").doClick();
                check(button("Prepare run").isEnabled(),"End must restore Setup");
                button("Prepare run").doClick();
            });
            await(()->text("Supplies update automatically"));
            edt(()->{button("Start run").doClick();panel.suspend(true);check(!text("Run in progress"),"Logout must clear active run");check(panel.runOverlayState()==null,"Logout must clear overlay");panel.update(input(1,0));button("Prepare run").doClick();});
            await(()->text("Supplies update automatically"));
            edt(()->{
                button("Start run").doClick();
                panel.update(new PlanInputs(999,99,99,99,0,0,0,true,false,"Unknown",Collections.emptyMap(),
                    Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),null));
                check(!text("Run in progress") && button("Prepare run").isEnabled(),"Other account must not inherit run");
                check(panel.runOverlayState()==null,"Other account must not inherit overlay");
            });
            System.out.println(checks+" run-mode checks passed.");
        }
        finally{if(panel!=null)edt(()->panel.dispose());}
    }
}

package com.herbrunplanner;
public final class TravelTimerChecks
{
    private static int count;
    private static void check(boolean v,String m){count++;if(!v)throw new AssertionError(m);}
    public static void main(String[] args)
    {
        TravelTimer t=new TravelTimer();TravelTimer.Request r=new TravelTimer.Request(1,PlanCatalog.Patch.CATHERBY,PlanCatalog.Travel.CAMELOT);
        t.tick(r,0,0,0,0,false,true);t.tick(r,1,0,0,600,true,true);
        check(!t.describe().contains("sec approach"),"Normal walking is not a teleport");
        t.tick(r,100,100,0,1200,false,true);t.tick(r,102,100,0,7200,true,true);
        check(t.describe().contains("6.0 sec approach"),"Arrival to patch elapsed time");
        t.tick(r,102,100,0,13200,true,true);
        check(t.describe().indexOf("6.0 sec approach")==t.describe().lastIndexOf("6.0 sec approach"),"One sample per step");
        check(t.describe().contains("candidate sample"),"Uncertain teleport is labelled");
        t.tick(null,0,0,0,14000,false,true);check(t.describe().contains("6.0 sec approach"),"Samples remain after ending");
        r=new TravelTimer.Request(2,PlanCatalog.Patch.CATHERBY,PlanCatalog.Travel.CAMELOT);
        t.tick(r,0,0,0,15000,false,true);check(!t.describe().contains("6.0 sec approach"),"Account isolation");
        t.tick(r,100,100,0,16000,false,true);t.tick(r,200,200,0,17000,false,true);
        check(t.describe().contains("another large movement"),"Second teleport invalidates sample");
        t.clear();t.tick(r,0,0,0,0,false,true);t.tick(r,100,100,0,20000,true,true);
        check(!t.describe().contains("sec approach"),"Large observation gap cannot start sample");
        t.clear();t.tick(r,0,0,0,0,false,false);t.tick(r,100,100,0,600,true,false);
        check(!t.describe().contains("sec approach"),"Instances excluded");
        r=new TravelTimer.Request(2,PlanCatalog.Patch.CATHERBY,PlanCatalog.Travel.MANUAL);
        t.tick(r,0,0,0,0,false,true);t.tick(r,100,100,0,600,true,true);
        check(!t.describe().contains("sec approach"),"Manual legs excluded");
        System.out.println(count+" travel-timer checks passed.");
    }
}

package com.herbrunplanner;
import java.util.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import static com.herbrunplanner.PlanCatalog.*;
public final class LeprechaunChecks
{
    private static int checks;
    private static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}
    private static PlanInputs input(int carried,int bank,Map<Integer,Integer> stored)
    {
        return new PlanInputs(1,99,99,99,0,0,4,true,true,"Bank open",Collections.emptyMap(),
            Map.of(ItemID.BUCKET_ULTRACOMPOST,carried),Collections.emptyMap(),Collections.emptyMap(),Map.of(ItemID.BUCKET_ULTRACOMPOST,bank),stored);
    }
    private static PlanEngine.Report report(PlanInputs in)
    {
        return PlanEngine.report(in,new PlanInputs.Choices(HERBS[4],Map.of(Patch.FALADOR,Travel.MANUAL,Patch.ARDOUGNE,Travel.MANUAL,Patch.CATHERBY,Travel.MANUAL),
            ReturnToBank.FINISH,Compost.ULTRA,true,true,true,false,true,true));
    }
    private static PlanEngine.Supply ultra(PlanEngine.Report r){return r.supplies.stream().filter(s->s.id==ItemID.BUCKET_ULTRACOMPOST).findFirst().get();}
    public static void main(String[] args)
    {
        Map<Integer,Integer> vars=new HashMap<>();
        vars.put(VarbitID.FARMING_TOOLS_COMPOST,232);vars.put(VarbitID.FARMING_TOOLS_EXTRACOMPOST,3);
        vars.put(VarbitID.FARMING_TOOLS_SUPERCOMPOST,1);vars.put(VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST,2);
        vars.put(VarbitID.FARMING_TOOLS_SPADE,1);vars.put(VarbitID.FARMING_TOOLS_EXTRASPADES,2);
        vars.put(VarbitID.FARMING_TOOLS_SECATEURS,1);vars.put(VarbitID.FARMING_TOOLS_EXTRASECATEURS,1);
        vars.put(VarbitID.FARMING_TOOLS_FAIRYSECATEURS,1);vars.put(VarbitID.FARMING_TOOLS_ULTRACOMPOST,1000);
        Map<Integer,Integer> stored=LeprechaunStorage.read(id->vars.getOrDefault(id,0));
        check(stored.get(ItemID.BUCKET_COMPOST)==1000,"Compost high bits");
        check(stored.get(ItemID.BUCKET_SUPERCOMPOST)==513,"Supercompost high bits");
        check(stored.get(ItemID.SPADE)==5,"Tool high bits");
        check(stored.get(ItemID.FAIRY_ENCHANTED_SECATEURS)==3,"Magic secateurs type and quantity");
        check(stored.get(ItemID.BUCKET_ULTRACOMPOST)==1000,"Ultra direct quantity");
        vars.put(VarbitID.FARMING_TOOLS_FAIRYSECATEURS,0);
        check(LeprechaunStorage.read(id->vars.getOrDefault(id,0)).get(ItemID.FAIRY_ENCHANTED_SECATEURS)==0,"Normal secateurs cannot count as magic");
        try{LeprechaunStorage.read(id->-1);throw new AssertionError("Negative read accepted");}catch(IllegalArgumentException expected){checks++;}
        PlanEngine.Supply s=ultra(report(input(0,0,stored)));
        check(s.missing==0 && s.collect==3 && s.withdraw==0,"Leprechaun-only compost is covered but needs collection");
        s=ultra(report(input(1,1,stored)));
        check(s.have==1 && s.withdraw==1 && s.collect==1 && s.missing==0,"Sources combine without double counting");
        s=ultra(report(input(0,3,stored)));
        check(s.withdraw==3 && s.collect==0,"Bank supplies preferred when already available there");
        s=ultra(report(input(3,0,stored)));
        check(s.have==3 && s.collect==0 && s.withdraw==0,"Carried supplies preferred");
        s=ultra(report(input(0,0,Map.of(ItemID.BUCKET_ULTRACOMPOST,2))));
        check(s.collect==2 && s.missing==1 && !s.storageUnknown,"Real remaining deficit");
        s=ultra(report(input(0,0,null)));
        check(s.storageUnknown && s.collect==0,"Unseen storage stays unknown");
        s=ultra(report(input(0,0,Map.of(ItemID.BUCKET_SUPERCOMPOST,1000))));
        check(s.missing==3,"Do not substitute another compost type");
        PlanEngine.Report r=report(input(0,0,stored));
        check(r.supplies.stream().anyMatch(x->x.id==ItemID.SPADE && x.collect==1 && x.missing==0),"Stored tools covered");
        check(r.supplies.stream().anyMatch(x->x.id==ItemID.RANARR_SEED && x.missing==3),"Seeds unaffected");
        check(!input(0,0,stored).sameState(input(0,0,Collections.emptyMap())),"Storage changes trigger live refresh");
        check(input(0,0,stored).sameRequirements(input(0,0,Collections.emptyMap())),"Storage refresh retains travel choices");
        // Automatic equipment must follow observed ownership on every refresh.
        int magicId=ItemID.FAIRY_ENCHANTED_SECATEURS;
        PlanInputs.Choices automatic=new PlanInputs.Choices(HERBS[4],Map.of(Patch.FALADOR,Travel.MANUAL),
            ReturnToBank.FINISH,Compost.ULTRA,false,false,false,false,true,false);
        for(int source=0;source<4;source++)
        {
            Map<Integer,Integer> owned=Map.of(magicId,1), empty=Collections.emptyMap();
            PlanInputs in=new PlanInputs(1,99,99,99,0,0,0,true,true,"Bank open",Collections.emptyMap(),
                source==0?owned:empty,source==1?owned:empty,empty,source==2?owned:empty,source==3?owned:empty);
            PlanEngine.Supply tool=PlanEngine.report(in,automatic).supplies.stream().filter(x->x.id==magicId).findFirst().orElseThrow(AssertionError::new);
            check(tool.need==1 && tool.missing==0 && tool.have==(source<2?1:0)
                && tool.withdraw==(source==2?1:0) && tool.collect==(source==3?1:0),"Automatic secateurs source "+source);
        }
        check(PlanEngine.report(input(0,0,null),automatic).supplies.stream().noneMatch(x->x.id==magicId),"Unknown storage must not invent secateurs");
        check(report(input(0,0,Collections.emptyMap())).supplies.stream().noneMatch(x->x.id==magicId),"Old enabled choice must not require unowned secateurs");
        System.out.println(checks+" leprechaun checks passed.");
    }
}

