    }
}

package com.herbrunplanner;
import java.util.*;
import net.runelite.api.gameval.ItemID;

public class AdvancedRuneChecks
{
    private static int checks;
    private static void test(boolean condition)
    { if(!condition) throw new AssertionError("Advanced rune check "+(checks+1)); checks++; }
    public static void main(String[] args)
    {
        Map<Integer,Integer> inv=new HashMap<>(),bank=new HashMap<>(),pouch=new HashMap<>(),worn=new HashMap<>();
        int[] falador={1,3,1,0,0,0,0,0}, camelot={1,5,0,0,0,0,0,0}, fortis={2,0,0,1,1,0,0,0};
        inv.put(ItemID.LAWRUNE,1); inv.put(ItemID.MISTRUNE,3);
        test(RuneAllocation.solve(falador,inv,null,0).deficit()==0);
        inv.put(ItemID.MISTRUNE,1);
        test(RuneAllocation.solve(falador,inv,null,0).deficit()==2);
        bank.put(ItemID.AIRRUNE,2);
        RuneAllocation.Result r=RuneAllocation.solve(falador,inv,bank,0);
        test(r.deficit()==0 && r.withdraw.get(ItemID.AIRRUNE)==2);
        bank.clear();bank.put(ItemID.MISTRUNE,2);
        r=RuneAllocation.solve(falador,inv,bank,0);
        test(r.deficit()==0 && r.withdraw.get(ItemID.MISTRUNE)==2);
        inv.clear();bank.clear(); inv.put(ItemID.LAWRUNE,2);inv.put(ItemID.LAVARUNE,1);
        test(RuneAllocation.solve(fortis,inv,null,0).deficit()==0);
        inv.clear();inv.put(ItemID.LAWRUNE,1);worn.put(ItemID.STAFF_OF_AIR,1);
        test(RuneAllocation.solve(camelot,inv,null,RuneEquipment.staffMask(worn)).deficit()==0);
        worn.clear();inv.put(ItemID.STAFF_OF_AIR,1);
        test(RuneAllocation.solve(camelot,inv,null,RuneEquipment.staffMask(worn)).deficit()==5);
        worn.put(ItemID.MYSTIC_MUD_STAFF,1);
        test(RuneEquipment.staffMask(worn)==12);
        worn.clear();worn.put(ItemID.MYSTIC_STEAM_BATTLESTAFF_PRETTY,1);
        test(RuneEquipment.staffMask(worn)==20);
        inv.clear();pouch.put(ItemID.LAWRUNE,1);pouch.put(ItemID.AIRRUNE,5);
        test(RuneAllocation.solve(camelot,AdvancedRuneSupplies.merge(inv,pouch),null,0).deficit()==0);
        inv.put(ItemID.AIRRUNE,2);
        test(AdvancedRuneSupplies.merge(inv,pouch).get(ItemID.AIRRUNE)==7);
        test(pouch.get(ItemID.AIRRUNE)==5);
        inv.put(ItemID.BH_RUNE_POUCH,1);test(RuneEquipment.hasPouch(inv));
        inv.clear();test(!RuneEquipment.hasPouch(inv));
        inv.put(ItemID.DIVINE_RUNE_POUCH_TROUVER,1);test(RuneEquipment.hasPouch(inv));
        inv.clear();bank.clear();inv.put(ItemID.LAWRUNE,1);bank.put(ItemID.AIRRUNE,5);
        r=RuneAllocation.solve(camelot,inv,bank,2);
        test(r.deficit()==0 && r.withdraw.isEmpty());
        inv.clear();inv.put(ItemID.LAWRUNE,1);inv.put(ItemID.MISTRUNE,1);inv.put(ItemID.DUSTRUNE,1);
        // Mist must cover water, leaving dust for air/earth: greedy mist->air would fail.
        int[] overlap={1,1,1,1,0,0,0,0};
        test(RuneAllocation.solve(overlap,inv,null,0).deficit()==0);
        inv.clear();inv.put(ItemID.LAWRUNE,1);bank.clear();bank.put(ItemID.MISTRUNE,3);bank.put(ItemID.AIRRUNE,3);bank.put(ItemID.WATERRUNE,1);
        r=RuneAllocation.solve(falador,inv,bank,0);
        test(r.deficit()==0 && r.bankUnits()==3);
        String text=AdvancedRuneSupplies.render(inv,null,0,true,null,"Bank unknown");
        test(text.contains("Pouch: Unknown") && text.contains("shortfalls are provisional"));
        inv.clear();inv.put(ItemID.LAWRUNE,1);inv.put(ItemID.AIRRUNE,5);
        text=AdvancedRuneSupplies.render(inv,null,0,true,null,"Bank unknown");
        test(text.contains("Camelot — Counted carried sources cover 1 cast"));
        // Large bank counts must not cause unbounded branching.
        bank.put(ItemID.MISTRUNE,Integer.MAX_VALUE);
        test(RuneAllocation.solve(falador,inv,bank,0).deficit()==0);
        System.out.println(checks+" advanced rune checks passed.");
    }
}

package com.herbrunplanner;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

/** Session-only, defensive copy of observed bank data. Null is different from empty. */
public final class BankSnapshot
{
    private Map<Integer, Integer> items;
    private Instant observedAt;

    public void observe(Map<Integer, Integer> source, Instant time)
    {
        if (source == null) return;
        items = Collections.unmodifiableMap(new LinkedHashMap<>(source));
        observedAt = time;
    }

    public Map<Integer, Integer> items() { return items; }

    public void clear()
    {
        items = null;
        observedAt = null;
    }

    public String status(boolean open)
    {
        if (items == null) return "Bank unknown — open your bank to inspect supplies.";
        String time = DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault()).format(observedAt);
        return (open ? "Bank open — observed at " : "Bank closed — last observed at ") + time
            + " (local time)." + (open ? "" : " Reopen to refresh; quantities may have changed.");
    }
}

package com.herbrunplanner;

import java.util.*;

public final class PlanInputs
{
    final long account; final int magic, farming, baseFarming, book, staffMask, occupied;
    final int runeStaffMask, plannedStaff;
    final boolean members, bankOpen;
    final String bankStatus;
    final Map<PlanCatalog.Travel,Integer> teleportUses;
    final int compostType,compostApplications;
    final Set<Integer> gear;
    final Map<String,Boolean> flags;
    final Map<Integer,Integer> inventory,equipment,pouch,bank,leprechaun;
    public PlanInputs(long account,int magic,int farming,int baseFarming,int book,int staffMask,int occupied,
        boolean members,boolean bankOpen,String bankStatus,Map<String,Boolean> flags,
        Map<Integer,Integer> inventory,Map<Integer,Integer> equipment,Map<Integer,Integer> pouch,Map<Integer,Integer> bank)
    {
        this(account,magic,farming,baseFarming,book,staffMask,occupied,members,bankOpen,bankStatus,flags,inventory,equipment,pouch,bank,null);
    }
    public PlanInputs(long account,int magic,int farming,int baseFarming,int book,int staffMask,int occupied,
        boolean members,boolean bankOpen,String bankStatus,Map<String,Boolean> flags,
        Map<Integer,Integer> inventory,Map<Integer,Integer> equipment,Map<Integer,Integer> pouch,Map<Integer,Integer> bank,Map<Integer,Integer> leprechaun)
    {this(account,magic,farming,baseFarming,book,staffMask,occupied,members,bankOpen,bankStatus,flags,inventory,equipment,pouch,bank,leprechaun,Collections.emptyMap(),-1,-1,Collections.emptySet());}
    private PlanInputs(long account,int magic,int farming,int baseFarming,int book,int staffMask,int occupied,
        boolean members,boolean bankOpen,String bankStatus,Map<String,Boolean> flags,
        Map<Integer,Integer> inventory,Map<Integer,Integer> equipment,Map<Integer,Integer> pouch,Map<Integer,Integer> bank,Map<Integer,Integer> leprechaun,
        Map<PlanCatalog.Travel,Integer> teleportUses,int compostType,int compostApplications,Set<Integer> gear)
    {
        Set<Integer> normalized=new LinkedHashSet<>();for(int id:gear)if(id>0)normalized.add(GearVariants.canonical(id));
        this.gear=Collections.unmodifiableSet(normalized);
        int weapon=0,weapons=0;boolean unknown=false;
        for(int id:normalized)
        {
            if(RuneEquipment.staff(id)!=0 || GearNames.slot(id)==3){weapon=id;weapons++;}
            else if(GearNames.slot(id)<0)unknown=true;
        }
        plannedStaff=weapons==1 && RuneEquipment.staff(weapon)!=0?weapon:0;
        // Never combine multiple selected staves. Unknown gear cannot safely retain
        // an equipped staff's benefit until its equipment slot has been resolved.
        runeStaffMask=weapons==1?RuneEquipment.staff(weapon):weapons>1 || unknown?0:staffMask;
        this.compostType=compostType>=1 && compostType<=3?compostType:-1;this.compostApplications=compostApplications;
        this.teleportUses=Collections.unmodifiableMap(new LinkedHashMap<>(teleportUses));
        this.leprechaun=copy(leprechaun);
        this.account=account;this.magic=magic;this.farming=farming;this.baseFarming=baseFarming;this.book=book;
        this.staffMask=staffMask;this.occupied=occupied;this.members=members;this.bankOpen=bankOpen;this.bankStatus=bankStatus;
        this.flags=Collections.unmodifiableMap(new LinkedHashMap<>(flags));
        this.inventory=copy(inventory);this.equipment=copy(equipment);this.pouch=copy(pouch);this.bank=copy(bank);
    }
    PlanInputs withTeleportUses(Map<PlanCatalog.Travel,Integer> uses)
    {return new PlanInputs(account,magic,farming,baseFarming,book,staffMask,occupied,members,bankOpen,bankStatus,flags,inventory,equipment,pouch,bank,leprechaun,uses,compostType,compostApplications,gear);}
    PlanInputs withCompost(int type,int applications)
    {return new PlanInputs(account,magic,farming,baseFarming,book,staffMask,occupied,members,bankOpen,bankStatus,flags,inventory,equipment,pouch,bank,leprechaun,teleportUses,type,applications,gear);}
    PlanInputs withGear(Set<Integer> items)
    {return new PlanInputs(account,magic,farming,baseFarming,book,staffMask,occupied,members,bankOpen,bankStatus,flags,inventory,equipment,pouch,bank,leprechaun,teleportUses,compostType,compostApplications,items);}
    private static Map<Integer,Integer> copy(Map<Integer,Integer> source)
    {return source==null?null:Collections.unmodifiableMap(new LinkedHashMap<>(source));}
    boolean hasMagicSecateurs()
    {
        int id=net.runelite.api.gameval.ItemID.FAIRY_ENCHANTED_SECATEURS;
        return count(inventory,id)>0 || count(equipment,id)>0 || count(bank,id)>0 || count(leprechaun,id)>0;
    }
    boolean knownGate(String gate){return gate==null || Boolean.TRUE.equals(flags.get(gate));}
    boolean patchGate(PlanCatalog.Patch p)
    {return members && knownGate(p.gate) && (p!=PlanCatalog.Patch.GUILD || farming>=65);}
    boolean sameRequirements(PlanInputs other)
    {
        return other!=null && account==other.account && magic==other.magic && farming==other.farming
            && baseFarming==other.baseFarming && book==other.book && members==other.members && flags.equals(other.flags);
    }
    boolean sameState(PlanInputs other)
    {
        return other!=null && account==other.account && magic==other.magic && farming==other.farming
            && baseFarming==other.baseFarming && book==other.book && staffMask==other.staffMask && occupied==other.occupied
            && members==other.members && bankOpen==other.bankOpen && flags.equals(other.flags)
            && Objects.equals(inventory,other.inventory) && Objects.equals(equipment,other.equipment)
            && compostType==other.compostType && compostApplications==other.compostApplications
            && teleportUses.equals(other.teleportUses) && Objects.equals(pouch,other.pouch) && Objects.equals(bank,other.bank) && Objects.equals(leprechaun,other.leprechaun);
    }
    static int count(Map<Integer,Integer> m,int id){return m==null?0:Math.max(0,m.getOrDefault(id,0));}
    static Map<Integer,Integer> sum(Map<Integer,Integer> a,Map<Integer,Integer> b)
    {return AdvancedRuneSupplies.merge(a,b);}
    public static final class Choices
    {
