        }
        Choices(PlanCatalog.Herb herb,Map<PlanCatalog.Patch,PlanCatalog.Travel> patches,PlanCatalog.ReturnToBank bankReturn,
            PlanCatalog.Compost compost,boolean weiss,boolean harmony,boolean charges,boolean manualCompost,boolean rake,boolean secateurs,boolean includeObtain)
        {this(herb,patches,bankReturn,compost,weiss,harmony,charges,manualCompost,rake,secateurs,includeObtain,null,Collections.emptySet(),PlanCatalog.Travel.AUTO,false);}
        private Choices(PlanCatalog.Herb herb,Map<PlanCatalog.Patch,PlanCatalog.Travel> patches,PlanCatalog.ReturnToBank bankReturn,
            PlanCatalog.Compost compost,boolean weiss,boolean harmony,boolean charges,boolean manualCompost,boolean rake,boolean secateurs,boolean includeObtain,List<PlanCatalog.Patch> order,Set<String> travelChecks,PlanCatalog.Travel houseEntry,boolean externalNetworks)
        {
            this.externalNetworks=externalNetworks;
            this.travelChecks=Collections.unmodifiableSet(new HashSet<>(travelChecks));this.houseEntry=houseEntry;
            this.includeObtain=includeObtain;
            this.herb=herb;this.patches=new EnumMap<>(PlanCatalog.Patch.class);this.patches.putAll(patches);
            List<PlanCatalog.Patch> sequence=new ArrayList<>(order==null?this.patches.keySet():order);
            if(sequence.size()!=patches.size() || !new HashSet<>(sequence).equals(patches.keySet()))throw new IllegalArgumentException("Order must contain each selected patch once");
            this.order=Collections.unmodifiableList(sequence);
