        Choices withOrder(List<PlanCatalog.Patch> order)
        {return new Choices(herb,patches,bankReturn,compost,weiss,harmony,charges,manualCompost,rake,secateurs,includeObtain,order,travelChecks,houseEntry,externalNetworks);}
    }
