import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/** Read-only item cards. No menus, input handlers or server actions. */
final class BankGridComponent implements LayoutableRenderableEntity
{
    private final List<BankPreparation.Entry> entries;
    private final List<BufferedImage> icons=new ArrayList<>();
    private final List<Rectangle> cards=new ArrayList<>();
    private final Rectangle bounds=new Rectangle();
    private Point location=new Point();
    private int width=220;
    BankGridComponent(List<BankPreparation.Entry> entries,IntFunction<BufferedImage> images)
    {this.entries=entries;for(BankPreparation.Entry e:entries)icons.add(images.apply(e.row.id));}
    @Override public Rectangle getBounds(){return bounds;}
    @Override public void setPreferredLocation(Point point){location=point;}
    @Override public void setPreferredSize(Dimension size){width=Math.max(52,size.width);}
    @Override public Dimension render(Graphics2D graphics)
    {
        int columns=Math.max(1,Math.min(4,width/52)),cell=width/columns,height=((entries.size()+columns-1)/columns)*58;
        bounds.setBounds(location.x,location.y,width,height);cards.clear();
        for(int i=0;i<entries.size();i++)
        {
            BankPreparation.Entry entry=entries.get(i);
            int x=location.x+(i%columns)*cell,y=location.y+(i/columns)*58;
            Rectangle card=new Rectangle(x+1,y+1,cell-4,53);cards.add(card);
            graphics.setColor(new Color(35,35,35,210));graphics.fillRect(card.x,card.y,card.width,card.height);
            graphics.setColor(entry.group.color);graphics.drawRect(card.x,card.y,card.width,card.height);
            BufferedImage icon=icons.get(i);
            if(icon!=null)graphics.drawImage(icon,x+(cell-icon.getWidth())/2,y+3,null);
            String quantity=(entry.group==BankPreparation.Group.MISSING && entry.row.unknown?"? ":"×")+entry.quantity;
            graphics.setColor(entry.group.color);graphics.drawString(quantity,x+(cell-graphics.getFontMetrics().stringWidth(quantity))/2,y+48);
        }
        return new Dimension(width,height);
    }
    String hovered(Point point)
    {for(int i=0;i<cards.size();i++)if(cards.get(i).contains(point))return entries.get(i).description();return null;}
}

