package com.herbrunplanner;

import java.util.*;
import java.util.regex.*;
import static com.herbrunplanner.PlanCatalog.*;
import net.runelite.api.gameval.ItemID;

/** Session-only observations. Exact game messages, never public/player chat. */
final class ObservedTeleportUses
{
    private static final Pattern CLOAK=Pattern.compile("You have used (\\d+) of your (3|5) Ardougne Farm teleports for today\\.");
    private static final Pattern XERIC=Pattern.compile("(?:The|Your) talisman(?: now)? has (one|no|[\\d,]+) charges?\\.");
    private int xeric=-1,cloakUsed=-1,cloakTotal=-1,checkTick=-100;
    private long day=Long.MIN_VALUE;
    void clear(){xeric=-1;cloakUsed=-1;cloakTotal=-1;checkTick=-100;day=Long.MIN_VALUE;}
    void invalidateXeric(){xeric=-1;checkTick=-100;}
    void click(int item,String option,int tick)
    {
        if(item==ItemID.XERIC_TALISMAN || item==ItemID.XERIC_TALISMAN_EMPTY)
        {
            invalidateXeric();
            if("Check".equals(option))checkTick=tick;
        }
    }
    void message(String message,int tick,long currentDay)
    {
        rollover(currentDay);
        String text=message.replaceAll("<[^>]*>","");
        Matcher cloak=CLOAK.matcher(text);
        if(cloak.matches())
        {
            int used=parse(cloak.group(1)),total=parse(cloak.group(2));
            if(used>=0 && used<=total){cloakUsed=used;cloakTotal=total;}
        }
        Matcher talisman=XERIC.matcher(text);
        if(tick>=checkTick && tick-checkTick<=5 && talisman.matches())
        {
            int count=talisman.group(1).equals("one")?1:talisman.group(1).equals("no")?0:parse(talisman.group(1).replace(",",""));
            if(count>=0 && count<=1000)xeric=count;
            checkTick=-100;
        }
    }
    Map<Travel,Integer> snapshot(int ringUsed,PlanInputs input,long currentDay)
    {
        rollover(currentDay);
        Map<Travel,Integer> counts=new EnumMap<>(Travel.class);
        int ring=TeleportUses.ringRemaining(ringUsed);if(ring>=0)counts.put(Travel.RING,ring);
        if(xeric>=0)counts.put(Travel.XERIC,xeric);
        int tier=0;
        for(int id:CLOAKS)if(ExtendedTravel.hasAny(input,new int[]{id}))
        {tier=id==ItemID.ARDY_CAPE_HARD?5:id==ItemID.ARDY_CAPE_MEDIUM?3:0;break;}
        if(cloakUsed>=0 && tier==cloakTotal)counts.put(Travel.CLOAK,Math.max(0,tier-cloakUsed));
        return counts;
    }
    private void rollover(long currentDay)
    {if(day!=currentDay){cloakUsed=-1;cloakTotal=-1;day=currentDay;}}
    private static int parse(String value){try{return Integer.parseInt(value);}catch(NumberFormatException e){return -1;}}
}

package com.herbrunplanner;

/** Immutable identity for one step, independent of overlay visibility. */
final class AutoStepRequest
{
    final long account;final RunProgress run;final int index,seed,compost,plantedState;
    final PlanCatalog.Patch patch;final boolean bank;
    AutoStepRequest(long account,RunProgress run,int index)
    {
        this.account=account;this.run=run;this.index=index;
        RunProgress.Step step=run.current();patch=step.patch;bank=step.bank;seed=run.choices.herb.id;
        int state=-1;
        // Initial herb growth states from RuneLite's farming PatchImplementation.HERB.
        for(int i=0;i<PlanCatalog.HERBS.length;i++)if(PlanCatalog.HERBS[i].id==seed)state=(i<8?4:12)+7*i;
        plantedState=state;
        compost=run.choices.compost==PlanCatalog.Compost.ULTRA?3:run.choices.compost==PlanCatalog.Compost.SUPER?2:1;
    }
}

