import java.util.concurrent.ConcurrentHashMap;
import java.util.Map;
import java.util.Set;

/** Public item-definition labels, filled on the client thread and read by Swing/workers. */
final class GearNames
{
    private static final Map<Integer,String> NAMES=new ConcurrentHashMap<>();
    private static final Map<Integer,Integer> SLOTS=new ConcurrentHashMap<>();
    private static final Set<Integer> TWO=ConcurrentHashMap.newKeySet();
    static int slot(int id){return SLOTS.getOrDefault(id,-1);}
    static boolean twoHanded(int id){return TWO.contains(id);}
    static void equipment(int id,int slot,boolean two){SLOTS.put(id,slot);if(two)TWO.add(id);}
    static boolean known(int id){return NAMES.containsKey(id);}
    static void register(int id,String name){if(id>0 && name!=null)NAMES.put(id,name);}
    static String name(int id){return NAMES.getOrDefault(id,"Item "+id);}
}

package com.herbrunplanner;

import java.util.*;
import java.util.function.Supplier;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;

/** Client-thread scene tracking and bounded path calculations, never render-time searches. */
final class HerbWalkingGuide
{
    static final class View
    {
        final WalkRequest request;
        final WorldView world;
        final int baseX,baseY,plane;
        final List<LocalWalkingPath.Tile> tiles;
        final String status;
        final PatchDestination.Bearing bearing;
        View(WalkRequest request,WorldView world,List<LocalWalkingPath.Tile> tiles,String status)
        {this(request,world,tiles,status,null);}
        View(WalkRequest request,WorldView world,List<LocalWalkingPath.Tile> tiles,String status,PatchDestination.Bearing bearing)
        {
            this.request=request;this.world=world;this.tiles=tiles;this.status=status;this.bearing=bearing;
            baseX=world==null?0:world.getBaseX();baseY=world==null?0:world.getBaseY();plane=world==null?0:world.getPlane();
        }
    }
    private final Client client;
    private final Supplier<WalkRequest> source;
    private final Set<GameObject> herbs=Collections.newSetFromMap(new IdentityHashMap<>());
    private boolean scan=true;
    private int scannedPlane=-1;
    private View current;
    HerbWalkingGuide(Client client,Supplier<WalkRequest> source){this.client=client;this.source=source;}
    void clear(){herbs.clear();scan=true;scannedPlane=-1;current=null;}
    void spawned(GameObject object)
    {if(HerbPatchObjects.herb(object.getId()))herbs.add(object);}
    void despawned(GameObject object){herbs.remove(object);}
    private WalkRequest request()
    {
        WalkRequest request=source.get();
        return request!=null && request.account==client.getAccountHash()?request:null;
    }
    View view()
    {
        WalkRequest request=request();if(request==null)return null;
        GameState state=client.getGameState();
        if(state==GameState.LOADING)return message(request,null,"Loading map · walking line paused.");
        if(state!=GameState.LOGGED_IN)return null;
        WorldView world=client.getTopLevelWorldView();
        if(current==null || current.request!=request || current.world!=world
            || world==null || current.baseX!=world.getBaseX() || current.baseY!=world.getBaseY() || current.plane!=world.getPlane())
            return message(request,world,"Updating walking guide…");
        return current;
    }
    private static View message(WalkRequest request,WorldView world,String message)
    {return new View(request,world,Collections.emptyList(),message);}
    private View direction(WalkRequest request,WorldView world,String reason)
    {
        PatchDestination destination=PatchDestination.forPatch(request.patch);
        if(destination==null || client.getLocalPlayer()==null)return message(request,world,reason);
        net.runelite.api.coords.WorldPoint player=client.getLocalPlayer().getWorldLocation();
        return new View(request,world,Collections.emptyList(),reason,
            destination.from(player.getX(),player.getY()));
    }
    boolean atPatch(PlanCatalog.Patch patch)
    {
        if(client.getLocalPlayer()==null)return false;
        WorldView world=client.getTopLevelWorldView();
        if(world==null || world.isInstance())return false;
        LocalPoint p=client.getLocalPlayer().getLocalLocation();
        for(GameObject object:herbs)
        {
            if(object.getWorldView()!=world || object.getPlane()!=world.getPlane()
                || HerbPatchObjects.patch(object.getWorldLocation().getRegionID())!=patch)continue;
            Point min=object.getSceneMinLocation(),max=object.getSceneMaxLocation();
            if(p.getSceneX()>=min.getX()-1 && p.getSceneX()<=max.getX()+1
                && p.getSceneY()>=min.getY()-1 && p.getSceneY()<=max.getY()+1)return true;
        }
        return false;
    }
    void tick()
    {
        WalkRequest request=request();
        if(request==null){current=null;return;}
        WorldView world=client.getTopLevelWorldView();
        if(world==null || client.getLocalPlayer()==null){current=message(request,world,"Walking map unavailable.");return;}
        if(request.patch==null){current=message(request,world,"Bank return · follow the teleport instructions.");return;}
        if(world.isInstance() || client.getLocalPlayer().getWorldView()!=world)
        {current=message(request,world,"Walking guidance unavailable in this area.");return;}
        int plane=world.getPlane();
        Tile[][][] scene=world.getScene().getTiles();
        if(plane<0 || plane>=scene.length || scene[plane]==null)
        {current=direction(request,world,"Walking map unavailable · direction only.");return;}
        Tile[][] tiles=scene[plane];
        if(scannedPlane!=plane)scan=true;
        if(scan)
        {
            // One seed scan after startup/region loading; subsequent changes use spawn events.
            for(Tile[] column:tiles)if(column!=null)for(Tile tile:column)if(tile!=null)
                for(GameObject object:tile.getGameObjects())if(object!=null)spawned(object);
            scan=false;scannedPlane=plane;
        }
        GameObject target=null;
        for(GameObject object:herbs)
            if(object.getWorldView()==world && object.getPlane()==plane
                && HerbPatchObjects.patch(object.getWorldLocation().getRegionID())==request.patch)
            {target=object;break;}

        CollisionData[] maps=world.getCollisionMaps();
        if(maps==null || plane>=maps.length || maps[plane]==null)
        {current=direction(request,world,"Collision data unavailable · direction only.");return;}
        LocalPoint player=client.getLocalPlayer().getLocalLocation();
        LocalWalkingPath.Target area;
        boolean mapped=target==null;
        if(mapped)
        {
            PatchDestination destination=PatchDestination.forPatch(request.patch);
            int x=destination.x-world.getBaseX(),y=destination.y-world.getBaseY();
            if(plane!=0 || request.patch==PlanCatalog.Patch.TROLL)
            {current=direction(request,world,"Direction only · reach the patch's level manually.");return;}
            if(x<0 || x>=tiles.length || tiles[x]==null || y<0 || y>=tiles[x].length || tiles[x][y]==null)
            {current=direction(request,world,"Patch area not loaded · direction only.");return;}
            area=new LocalWalkingPath.Target(x,y,x,y);
        }
        else
        {
            Point min=target.getSceneMinLocation(),max=target.getSceneMaxLocation();
            area=new LocalWalkingPath.Target(min.getX(),min.getY(),max.getX(),max.getY());
        }
        LocalWalkingPath.Result result=LocalWalkingPath.find(maps[plane].getFlags(),player.getSceneX(),player.getSceneY(),area,
            (x,y)->x>=0 && x<tiles.length && tiles[x]!=null && y>=0 && y<tiles[x].length && tiles[x][y]!=null);
        if(result.tiles.isEmpty())current=direction(request,world,result.status+" Direction only.");
        else if(mapped && result.tiles.size()==1)current=direction(request,world,"At mapped farming area · look for the herb patch.");
        else current=new View(request,world,result.tiles,mapped?"Walking toward mapped patch area · "+(result.tiles.size()-1)+" steps":result.status);
    }
}

