package com.herbrunplanner;

import java.util.Map;
import static com.herbrunplanner.PlanCatalog.*;

/** Provisional planning weights in seconds, not measured timings or global pathfinding.
 * Includes a nominal teleport/menu allowance and a running approach to the patch.
 * See TRAVEL_TIMES.md for assumptions and calibration limitations. */
final class TravelTime
{
    private TravelTime() {}
    static int seconds(Patch patch,Travel method)
    {
        int extra=extended(patch,method);if(extra>=0)return extra;
        switch(patch)
        {
            case GUILD: return method==Travel.SKILLS?20:-1;
            case FALADOR:
                switch(method){case RING:return 12;case GLORY:return 45;case FALADOR:case FALADOR_TAB:return 55;default:return -1;}
            case ARDOUGNE:
                switch(method){case CLOAK:return 12;case SKILLS:case FISHING:case FISHING_TAB:return 30;case COMBAT:return 40;case ARDOUGNE_TAB:return 60;default:return -1;}
            case HOSIDIUS:
                switch(method){case XERIC:return 20;case HOSIDIUS_TAB:return 35;case SKILLS:return 60;default:return -1;}
            case PHASMATYS:return method==Travel.ECTO?35:method==Travel.FENK_TAB?45:-1;
            case TROLL:return method==Travel.STONY?15:method==Travel.TROLLHEIM?90:-1;
            case WEISS:return method==Travel.ICY?15:-1;
            case FORTIS:return method==Travel.FORTIS?55:-1;
            case HARMONY:return method==Travel.HARMONY || method==Travel.HARMONY_TAB?20:-1;
            case CATHERBY:
                switch(method){case CATHERBY:case CATHERBY_TAB:return 15;case CAMELOT:case CAMELOT_TAB:return 35;default:return -1;}
            default:return -1;
        }
    }
    private static int extended(Patch p,Travel t)
    {
        if(ExtendedTravel.fairy(t))return 90;
        if(ExtendedTravel.spirit(t))return p==Patch.GUILD?30:55;
        if(ExtendedTravel.house(t))
        {
            switch(t)
            {
                case POH_HOSIDIUS:return 45;case POH_XERIC:return 35;
                case POH_GLORY:return 60;case POH_SKILLS_GUILD:return 35;case POH_SKILLS_FISHING:return 45;case POH_SKILLS_WOODCUTTING:return 75;
                case POH_TROLL:return 30;case POH_TROLLHEIM:return 105;case POH_WEISS:return 30;
                case POH_CATHERBY:return 30;case POH_CAMELOT:return 50;case POH_FISHING:return 45;
                case POH_FALADOR:return 70;case POH_ARDOUGNE:return 75;case POH_FENK:return 60;
                case POH_HARMONY:return 35;case POH_FORTIS:return 70;case POH_BATTLEFRONT:return 90;
                default:return -1;
            }
        }
        switch(t)
        {
            case FARM_CAPE:return 15;case ARDOUGNE:return 60;case FENK:return 45;
            case BATTLEFRONT:case BATTLEFRONT_TAB:return 75;case FORTIS_TAB:return 55;
            case TROLLHEIM_TAB:return 90;case CON_HOSIDIUS:return 35;case MEMOIRS:return 40;
            case QUETZAL:case HUNTER_CAPE:return 30;default:return -1;
        }
    }
    static int bankSeconds(ReturnToBank bank)
    {
        switch(bank)
        {
            case FINISH:return 0;case WALK:return 15;case GUILD_WALK:return 15;case DUELING:return 10;
            case GLORY:return 15;case CATHERBY:case CATHERBY_TAB:return 15;
            case CAMELOT:case CAMELOT_TAB:return 30;case FALADOR_TAB:return 25;
            case FARM_CAPE:case CRAFT_CAPE:return 10;case WEALTH:case EDGEVILLE:case FEROX:return 15;
            case SEED_POD:return 25;case HOUSE_DUELING:case HOUSE_WEALTH:return 25;case HOUSE_CATHERBY:return 30;
            default:return -1;
        }
    }
    static int unknown(PlanInputs.Choices c)
    {
        int count=bankSeconds(c.bankReturn)<0?1:0;
        for(Map.Entry<Patch,Travel> e:c.patches.entrySet())if(seconds(e.getKey(),e.getValue())<0)count++;
        return count;
    }
    static int total(PlanInputs.Choices c)
    {
        int sum=Math.max(0,bankSeconds(c.bankReturn));
        for(Map.Entry<Patch,Travel> e:c.patches.entrySet())sum+=Math.max(0,seconds(e.getKey(),e.getValue()));
        return sum;
    }
    static String summary(PlanInputs.Choices c)
    {
        int total=total(c),unknown=unknown(c);
        if(total==0 && unknown>0)return "Travel estimate unavailable for manual or unresolved travel.";
        int low=(int)Math.floor(total*0.5/5)*5,high=(int)Math.ceil(total*1.5/5)*5;
        return "Provisional travel estimate: "+low+"–"+high+" sec"+(unknown>0?" for timed legs only; "+unknown+" untimed.":".")
            +" Running assumed; farming, banking actions and delays excluded. Timings need in-game calibration.";
    }
}

package com.herbrunplanner;

import java.awt.Color;
import java.util.*;

/** Immutable, preformatted view passed from Swing to the overlay renderer. */
final class BankPreparation
{
    static final Color GREEN=new Color(109,180,130), GOLD=new Color(220,179,92),
        BLUE=new Color(105,175,225), RED=new Color(210,105,95);
    static final class Row
    {
        final int id,withdraw,collect,missing,need,have;
        final boolean unknown;
        final String name,action;
        final Color color;
        Row(PlanEngine.Supply s,boolean unknown)
        {
            id=s.id;withdraw=s.withdraw;collect=s.collect;missing=s.missing;need=s.need;have=s.have;this.unknown=unknown || s.storageUnknown;name=PlanCatalog.name(id);
            color=s.missing>0?RED:s.collect>0?BLUE:s.withdraw>0?GOLD:GREEN;
            List<String> parts=new ArrayList<>();
            if(s.withdraw>0)parts.add("Bank: "+s.withdraw);
            if(s.collect>0)parts.add("Leprechaun: "+s.collect);
            if(s.missing>0)parts.add((unknown || s.storageUnknown?"Unknown: ":"Missing: ")+s.missing);
            action=parts.isEmpty()?"Carried":String.join(" / ",parts);
        }
    }
    enum Group
    {
        WITHDRAW("Withdraw",GOLD), READY("Ready",GREEN), COLLECT("Collect from leprechaun",BLUE), MISSING("Missing / unknown",RED);
        final String label;final Color color;
        Group(String label,Color color){this.label=label;this.color=color;}
    }
    static final class Entry
    {
        final Row row;final int quantity;final Group group;
        Entry(Row row,int quantity,Group group){this.row=row;this.quantity=quantity;this.group=group;}
        String description(){return row.name+" · "+group.label+": "+quantity+" · Need "+row.need+" · Carried "+row.have;}
    }
    final Map<Group,List<Entry>> groups;
    final long account;
    final List<Row> rows;
    final Map<Integer,Row> items;
    final boolean review;
    BankPreparation(long account,PlanEngine.Report report,boolean unknown)
    {
        this.account=account;review=!report.problems.isEmpty();
        List<Row> list=new ArrayList<>();Map<Integer,Row> map=new HashMap<>();
        for(PlanEngine.Supply s:report.supplies){Row row=new Row(s,unknown);list.add(row);map.put(row.id,row);}
        rows=Collections.unmodifiableList(list);items=Collections.unmodifiableMap(map);
        EnumMap<Group,List<Entry>> grouped=new EnumMap<>(Group.class);
        for(Group group:Group.values())grouped.put(group,new ArrayList<>());
        for(Row row:list)
        {
            if(row.withdraw>0)grouped.get(Group.WITHDRAW).add(new Entry(row,row.withdraw,Group.WITHDRAW));
            if(row.have>=row.need)grouped.get(Group.READY).add(new Entry(row,row.need,Group.READY));
            if(row.collect>0)grouped.get(Group.COLLECT).add(new Entry(row,row.collect,Group.COLLECT));
            if(row.missing>0)grouped.get(Group.MISSING).add(new Entry(row,row.missing,Group.MISSING));
        }
        for(Group group:Group.values())grouped.put(group,Collections.unmodifiableList(grouped.get(group)));
        groups=Collections.unmodifiableMap(grouped);
    }
}

package com.herbrunplanner;

import java.util.function.*;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/** Observes user actions and game results. Never performs a game action. */
final class AutomaticRunProgress
{
    private final Client client;private final Supplier<AutoStepRequest> source;private final Consumer<AutoStepRequest> complete;
    private AutoStepRequest request;private ObservedPatchCompletion evidence=new ObservedPatchCompletion();
    private WorldPoint target;private int varbit=-1;private boolean sent;
    AutomaticRunProgress(Client client,Supplier<AutoStepRequest> source,Consumer<AutoStepRequest> complete)
    {this.client=client;this.source=source;this.complete=complete;}
    void clear(){request=null;target=null;varbit=-1;sent=false;evidence=new ObservedPatchCompletion();}
    private boolean sync()
    {
        AutoStepRequest next=source.get();
        if(next!=request){clear();request=next;}
        return request!=null && request.account==client.getAccountHash() && client.getGameState()==GameState.LOGGED_IN
            && client.getLocalPlayer()!=null && client.getTopLevelWorldView()!=null && !client.getTopLevelWorldView().isInstance()
            && client.getLocalPlayer().getWorldView()==client.getTopLevelWorldView();
    }
    private int seeds()
    {ItemContainer inv=client.getItemContainer(InventoryID.INV);return inv==null?Integer.MAX_VALUE:inv.count(request.seed);}
    private boolean beside()
    {return target!=null && client.getLocalPlayer()!=null && client.getLocalPlayer().getWorldLocation().distanceTo(target)<=4;}
    void click(MenuOptionClicked e)
    {
        if(!sync() || request.bank)return;
        switch(e.getMenuAction())
        {
            case WIDGET_TARGET_ON_GAME_OBJECT:case GAME_OBJECT_FIRST_OPTION:case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:case GAME_OBJECT_FOURTH_OPTION:case GAME_OBJECT_FIFTH_OPTION:break;
            default:return;
        }
        int x=e.getParam0(),y=e.getParam1(),plane=client.getLocalPlayer().getWorldLocation().getPlane();
        Tile[][] tiles=client.getTopLevelWorldView().getScene().getTiles()[plane];
        if(x<0 || x>=tiles.length || tiles[x]==null || y<0 || y>=tiles[x].length || tiles[x][y]==null)return;
        GameObject herb=null;
        for(GameObject object:tiles[x][y].getGameObjects())
            if(object!=null && HerbPatchObjects.herb(object.getId()) && (object.getId()==e.getId())){herb=object;break;}
        if(herb==null || HerbPatchObjects.patch(herb.getWorldLocation().getRegionID())!=request.patch)return;
        int observed=client.getObjectDefinition(herb.getId()).getVarbitId();if(observed<0)return;
        WorldPoint location=herb.getWorldLocation();
        if(target!=null && !target.equals(location))return;
        target=location;varbit=observed;
        Widget selected=client.getSelectedWidget();
        boolean use=e.getMenuAction()==MenuAction.WIDGET_TARGET_ON_GAME_OBJECT;
        int id=selected==null?-1:selected.getItemId();
        if(use && id==request.seed)evidence.planting(client.getTickCount(),seeds(),client.getVarbitValue(varbit),request.plantedState);
        int state=client.getVarbitValue(varbit);
        boolean freshSoil=state>=0 && state<=3 || state==request.plantedState;
        if(freshSoil && ("Inspect".equals(e.getMenuOption()) || (use && (id==ItemID.BUCKET_COMPOST || id==ItemID.BUCKET_SUPERCOMPOST
            || id==ItemID.BUCKET_ULTRACOMPOST || id==ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED
            || selected!=null && selected.getId()==InterfaceID.MagicSpellbook.FERTILE_SOIL))))evidence.composting(client.getTickCount());
    }
    void message(String text)
    {if(sync() && !request.bank)evidence.message(text,client.getTickCount(),beside());}
    void tick(boolean bankOpen)
    {
        if(!sync() || sent)return;
        boolean ready=request.bank && bankOpen;
        if(!request.bank && varbit>=0)
        {
            int state=client.getVarbitValue(varbit);
            if(!(state>=0 && state<=3 || state==request.plantedState))evidence.clearCompost();
            evidence.observe(client.getTickCount(),seeds(),state,beside());
            ready=evidence.takeCompletion(request.compost);
        }
        if(ready){sent=true;complete.accept(request);}
    }
}

