package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;

/** Explicit infrastructure confirmations are separate from observed item ownership. */
final class ExtendedTravel
{
    static final Map<String,String> CHECKS=new LinkedHashMap<>();
    static
    {
        CHECKS.put("MEMOIRS_CHARGES","Hosidius book page restored and enough book charges for this run");
        CHECKS.put("WHISTLE_CHARGES","Whistle can reach Hunter Guild and has enough charges for this run");
        CHECKS.put("HOUSE_FAIRY_RING","My house has a usable fairy ring");
        CHECKS.put("FAIRY_ACCESS","Fairy-ring travel is unlocked (Fairy Tale II progress checked)");
        CHECKS.put("HOUSE_SPIRIT_TREE","My house has a usable spirit tree");
        CHECKS.put("SPIRIT_GUILD_PLANTED","My Farming Guild spirit tree is fully grown and usable");
        CHECKS.put("SPIRIT_HOSIDIUS_PLANTED","My Hosidius spirit tree is fully grown and usable");
        CHECKS.put("JEWELLERY_SKILLS","My jewellery box has skills-necklace destinations");
        CHECKS.put("JEWELLERY_DUELING","My jewellery box has ring-of-dueling destinations");
        CHECKS.put("JEWELLERY_WEALTH","My jewellery box has ring-of-wealth destinations");
        CHECKS.put("MOUNTED_GLORY","My house has a mounted glory or glory jewellery-box destinations");
        CHECKS.put("MOUNTED_XERIC","My house has a usable mounted Xeric's talisman with Glade unlocked");
        for(Travel t:Travel.values())if(t.name().startsWith("POH_") && portal(t))CHECKS.put(t.name(),"Installed and usable: "+t.label);
    }
    private ExtendedTravel() {}
    static boolean house(Travel t){return t.name().startsWith("POH_") || fairy(t) || spirit(t);}
    static boolean fairy(Travel t){return t.name().startsWith("FAIRY_");}
    static boolean spirit(Travel t){return t.name().startsWith("SPIRIT_");}
    static boolean portal(Travel t)
    {return t.name().startsWith("POH_") && !t.name().startsWith("POH_SKILLS_") && !t.name().startsWith("POH_BANK_") && t!=Travel.POH_GLORY && t!=Travel.POH_XERIC && t!=Travel.POH_HOSIDIUS;}
    static List<String> requiredChecks(Travel t)
    {
        List<String> keys=new ArrayList<>();
        if(portal(t))keys.add(t.name());
        if(t.name().startsWith("POH_SKILLS_"))keys.add("JEWELLERY_SKILLS");
        if(t==Travel.POH_BANK_DUELING)keys.add("JEWELLERY_DUELING");
        if(t==Travel.POH_BANK_WEALTH)keys.add("JEWELLERY_WEALTH");
        if(t==Travel.POH_GLORY)keys.add("MOUNTED_GLORY");
        if(t==Travel.POH_XERIC)keys.add("MOUNTED_XERIC");
        if(fairy(t)){keys.add("HOUSE_FAIRY_RING");keys.add("FAIRY_ACCESS");}
        if(spirit(t)){keys.add("HOUSE_SPIRIT_TREE");keys.add(t==Travel.SPIRIT_GUILD?"SPIRIT_GUILD_PLANTED":"SPIRIT_HOSIDIUS_PLANTED");}
        return keys;
    }
    static String unavailable(PlanInputs in,Travel t,PlanInputs.Choices c)
    {
        List<String> reasons=new ArrayList<>();
        if(house(t))
        {
            boolean external=c.externalNetworks && (fairy(t) || spirit(t));
            if(!external && !in.knownGate("HOUSE_OWNED"))reasons.add("Own house not detected");
            for(String key:requiredChecks(t))
                if(!(external && (key.equals("HOUSE_FAIRY_RING") || key.equals("HOUSE_SPIRIT_TREE"))) && !c.travelChecks.contains(key))reasons.add("Confirm: "+CHECKS.get(key));
            if(t==Travel.POH_HOSIDIUS && !in.knownGate("HOUSE_HOSIDIUS"))reasons.add("Own house must be in Hosidius");
            if(spirit(t) && !in.knownGate("TREE_GNOME_VILLAGE"))reasons.add("Tree Gnome Village not complete");
            if(fairy(t) && !in.knownGate("Lumbridge Elite") && !hasAny(in,STAFFS))reasons.add("Carry or bank a dramen/lunar staff for fairy rings");
            Travel entry=entry(t,c);
            if(!external && !ENTRY.contains(entry))reasons.add("Select a usable house-entry method");
            else {String gate=PlanEngine.unavailable(in,entry);if(!gate.isEmpty())reasons.add("Entry: "+gate);}
        }
        if(t==Travel.SPIRIT_GUILD && in.farming<85)reasons.add("Maintain 85 Farming for the Guild spirit-tree wing");
        if(t==Travel.MEMOIRS && !c.travelChecks.contains("MEMOIRS_CHARGES"))reasons.add("Confirm restored Hosidius page and whole-run book charges");
        if(t==Travel.QUETZAL && !hasAny(in,new int[]{ItemID.HG_QUETZALWHISTLE_PERFECTED_INFINITE}) && !c.travelChecks.contains("WHISTLE_CHARGES"))reasons.add("Confirm whole-run whistle charges and Hunter Guild destination");
        return String.join("; ",reasons);
    }
    static Travel entry(Travel t,PlanInputs.Choices c)
    {return c.externalNetworks && fairy(t)?Travel.GLORY_EDGE:c.externalNetworks && spirit(t)?Travel.WEALTH:c.houseEntry;}
    static final Set<Travel> ENTRY=Collections.unmodifiableSet(EnumSet.of(Travel.HOUSE_TAB,Travel.HOUSE_SPELL,Travel.CON_CAPE));
    static final int[] STAFFS={ItemID.DRAMEN_STAFF,ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF};
    static boolean hasAny(PlanInputs in,int[] ids)
    {for(int id:ids)if(PlanInputs.count(in.inventory,id)+PlanInputs.count(in.equipment,id)+PlanInputs.count(in.bank,id)>0)return true;return false;}
    static int[] items(Travel t)
    {
        switch(t)
        {
            case FARM_CAPE:return new int[]{ItemID.SKILLCAPE_FARMING,ItemID.SKILLCAPE_FARMING_TRIMMED,ItemID.SKILLCAPE_MAX,ItemID.SKILLCAPE_MAX_WORN};
            case CRAFT_CAPE:return new int[]{ItemID.SKILLCAPE_CRAFTING,ItemID.SKILLCAPE_CRAFTING_TRIMMED,ItemID.SKILLCAPE_MAX,ItemID.SKILLCAPE_MAX_WORN};
            case CON_CAPE:case CON_HOSIDIUS:return new int[]{ItemID.SKILLCAPE_CONSTRUCTION,ItemID.SKILLCAPE_CONSTRUCTION_TRIMMED,ItemID.SKILLCAPE_MAX,ItemID.SKILLCAPE_MAX_WORN};
            case HUNTER_CAPE:return new int[]{ItemID.SKILLCAPE_HUNTING,ItemID.SKILLCAPE_HUNTING_TRIMMED,ItemID.SKILLCAPE_MAX,ItemID.SKILLCAPE_MAX_WORN};
            case MEMOIRS:return new int[]{ItemID.BOOK_OF_THE_DEAD,ItemID.VEOS_KHAREDSTS_MEMOIRS};
            case QUETZAL:return new int[]{ItemID.HG_QUETZALWHISTLE_PERFECTED_INFINITE,ItemID.HG_QUETZALWHISTLE_PERFECTED,ItemID.HG_QUETZALWHISTLE_ENHANCED,ItemID.HG_QUETZALWHISTLE_BASIC};
            case SEED_POD:return new int[]{ItemID.MM2_ROYAL_SEED_POD};
            default:return new int[0];
        }
    }
    static boolean allowance(Travel t,int item)
    {return t==Travel.XERIC || (t==Travel.RING && item==ItemID.LUMBRIDGE_RING_MEDIUM)
        || (t==Travel.CLOAK && item!=ItemID.ARDY_CAPE_ELITE);}
    static String instructions(Travel t,PlanInputs.Choices c)
    {
        String text=t.label;
        if(house(t))text=entry(t,c).label+"\n"+t.label;
        if(fairy(t))text+=(c.externalNetworks?"\nFrom Edgeville, cross the bridge east to fairy ring DKR, then enter the destination code.":"\nUse your house fairy ring.")+" Equip the counted dramen/lunar staff unless Lumbridge elite is complete.";
        if(spirit(t))text+=(c.externalNetworks?"\nUse the spirit tree northeast of the Grand Exchange.":"\nUse your house spirit tree.")+" Select the confirmed grown destination tree.";
        if(t==Travel.POH_HOSIDIUS)text+="\nTeleport outside (or leave the house), then walk to the patch.";
        if(t==Travel.QUETZAL || t==Travel.HUNTER_CAPE)text+="\nHunter Guild landing; walk north to the Fortis herb patch.";
        if(t==Travel.MEMOIRS)text+="\nSelect Lunch by the Lancalliums, then walk to the patch.";
        if(t==Travel.FAIRY_GUILD)text+="\nCIR: run southwest toward the Farming Guild.";
        if(t==Travel.FAIRY_ARDOUGNE)text+="\nBLR: walk west toward the Ardougne patch.";
        if(t==Travel.FAIRY_PHASMATYS)text+="\nALQ: walk north toward the farming area.";
        if(t==Travel.FAIRY_FORTIS)text+="\nAJP: walk northwest toward the farming area.";
        return text;
    }
}

package com.herbrunplanner;

import java.util.*;
import static com.herbrunplanner.PlanCatalog.*;

/** Bounded supply-feasibility and provisional travel-time improvement. No GP-cost model. */
final class AutoTravelPlanner
{
    private AutoTravelPlanner() {}
    static PlanEngine.Report choose(PlanInputs input,PlanInputs.Choices requested)
    {
        // Leaving a Hosidius house needs no furniture confirmation. Still compare
        // entry supplies when this route is available to the selected patch.
        boolean outsideHouse=(requested.patches.get(Patch.HOSIDIUS)==Travel.AUTO
            || requested.patches.get(Patch.HOSIDIUS)==Travel.POH_HOSIDIUS)
            && input.knownGate("HOUSE_HOSIDIUS");
        if(requested.houseEntry==Travel.AUTO && (!requested.travelChecks.isEmpty() || outsideHouse))
        {
            PlanEngine.Report result=null;
            for(Travel entry:new Travel[]{Travel.CON_CAPE,Travel.HOUSE_SPELL,Travel.HOUSE_TAB})
            {
                cancelled();
                PlanEngine.Report candidate=choose(input,requested.withTransport(requested.travelChecks,entry));
                if(result==null || compare(candidate,result)<0)result=candidate;
            }
            return result;
        }
        PlanEngine.Report best=chooseMethods(input,requested);
        if(best.supplies.isEmpty() || requested.bankReturn==ReturnToBank.FINISH)return best;
        // Explicit teleports/manual endings do not benefit from arbitrary reordering.
        if(requested.bankReturn!=ReturnToBank.AUTO && requested.bankReturn!=ReturnToBank.WALK
            && requested.bankReturn!=ReturnToBank.GUILD_WALK)return best;
        for(Patch last:requested.order)
        {
            cancelled();
            if(requested.bankReturn==ReturnToBank.WALK && last!=Patch.CATHERBY)continue;
            if(requested.bankReturn==ReturnToBank.GUILD_WALK && last!=Patch.GUILD)continue;
            List<Patch> order=new ArrayList<>(requested.order);order.remove(last);order.add(last);
            if(order.equals(requested.order))continue;
            PlanEngine.Report trial=chooseMethods(input,requested.withOrder(order));
            if((requested.includeObtain || trial.travelShortfall==0) && compare(trial,best)<0)best=trial;
        }
        return best;
    }
    private static PlanEngine.Report chooseMethods(PlanInputs input,PlanInputs.Choices requested)
    {
        PlanEngine.Report best=PlanEngine.evaluate(input,requested);
        if(best.supplies.isEmpty())return best;
        // Each trial budgets the entire candidate-order run, including the final bank teleport.
        // Only AUTO selections are adjustable; manual overrides and live-refresh choices stay fixed.
        for(int pass=0;pass<2;pass++)
        {
            boolean changed=false;
            for(Patch patch:requested.order)
            {
                if(requested.patches.get(patch)!=Travel.AUTO)continue;
                for(Travel method:patch.methods)
                {
                    cancelled();
                    if(!PlanEngine.unavailable(input,method,requested).isEmpty() || best.resolvedChoices.patches.get(patch)==method)continue;
                    EnumMap<Patch,Travel> alternatives=new EnumMap<>(best.resolvedChoices.patches);
                    alternatives.put(patch,method);
                    // Reconsider later automatic steps with the resources this trial leaves available.
                    for(Patch later:requested.order)
                        if(requested.order.indexOf(later)>requested.order.indexOf(patch) && requested.patches.get(later)==Travel.AUTO)alternatives.put(later,Travel.AUTO);
                    PlanEngine.Report candidate=PlanEngine.evaluate(input,copy(best.resolvedChoices,alternatives,requested.bankReturn==ReturnToBank.AUTO?ReturnToBank.AUTO:best.resolvedChoices.bankReturn));
                    if((requested.includeObtain || candidate.travelShortfall==0) && compare(candidate,best)<0){best=candidate;changed=true;}
                }
            }
            if(requested.bankReturn==ReturnToBank.AUTO)
            {
                for(ReturnToBank destination:ReturnToBank.values())
                {
                    cancelled();
                    if(destination.travel==null || !PlanEngine.unavailable(input,destination.travel,requested).isEmpty())continue;
                    PlanEngine.Report candidate=PlanEngine.evaluate(input,copy(best.resolvedChoices,best.resolvedChoices.patches,destination));
                    if((requested.includeObtain || candidate.travelShortfall==0) && compare(candidate,best)<0){best=candidate;changed=true;}
                }
            }
            if(!changed)break;
        }
        return best;
    }
    private static void cancelled(){if(Thread.currentThread().isInterrupted())throw new java.util.concurrent.CancellationException();}
    private static PlanInputs.Choices copy(PlanInputs.Choices c,Map<Patch,Travel> patches,ReturnToBank bank)
    {return new PlanInputs.Choices(c.herb,patches,bank,c.compost,c.weiss,c.harmony,c.charges,c.manualCompost,c.rake,c.secateurs,c.includeObtain).withTransport(c.travelChecks,c.houseEntry).withExternalNetworks(c.externalNetworks).withOrder(c.order);}
    private static int compare(PlanEngine.Report a,PlanEngine.Report b)
    {
        int[] left=score(a),right=score(b);
        for(int i=0;i<left.length;i++){int diff=Integer.compare(left[i],right[i]);if(diff!=0)return diff;}
        return 0;
    }
    private static int[] score(PlanEngine.Report report)
    {
        int missing=0,withdraw=0,preference=0;
        for(PlanEngine.Supply s:report.supplies){missing+=s.missing;withdraw+=s.withdraw;}
        for(Map.Entry<Patch,Travel> e:report.resolvedChoices.patches.entrySet())
        {
            Travel[] methods=e.getKey().methods;
            for(int i=0;i<methods.length;i++)if(methods[i]==e.getValue())preference+=i;
        }
        return new int[]{report.blockedSteps,report.manualSteps,missing,report.unconfirmedSteps,TravelTime.unknown(report.resolvedChoices),TravelTime.total(report.resolvedChoices),withdraw,preference};
    }
}

package com.herbrunplanner;

import java.awt.BorderLayout;
