        javax.swing.JToggleButton profile = new javax.swing.JToggleButton("Profile");
        javax.swing.JToggleButton bugPage = new javax.swing.JToggleButton("Report a bug");
        javax.swing.JLabel version=new javax.swing.JLabel("v"+BetaDiagnostics.VERSION);
        version.setForeground(new java.awt.Color(177,183,177));
        JButton diagnostics=new JButton("Copy diagnostics");
        diagnostics.setToolTipText("Copy routes and relevant supply counts; excludes account identifiers and credentials.");
        diagnostics.addActionListener(event -> {
            String report=plan.diagnostics();
            try
            {
                java.awt.Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new java.awt.datatransfer.StringSelection(report),null);
                javax.swing.JOptionPane.showMessageDialog(this,"Diagnostics copied. Paste into your bug report.\nIncludes route, requirement and relevant item counts.","Herb Run Planner",javax.swing.JOptionPane.INFORMATION_MESSAGE);
