    public void update(String accountText, String levelText, String questText, String patchText, String diaryText, String teleportText, String supplyText, String runeText, PlanInputs planInputs)
    {
        if (planInputs != null) plan.update(planInputs);
        else plan.suspend(!accountText.startsWith("Loading"));
        replace(summary, accountText);
        replace(levels, levelText);
        replace(quests, questText);
        replace(patches, patchText);
        replace(diaries, diaryText);
        replace(teleports, teleportText);
        replace(supplies, supplyText);
        replace(runes, runeText);
    }

