    java.util.Set<Integer> gearIds(){return plan.gearIds();}
    AutoStepRequest autoRequest(){return plan.autoRequest();}
    void automaticDone(AutoStepRequest request){plan.automaticDone(request);}
    void characterName(long account,String name){plan.characterName(account,name);}
    void updateSupplies(PlanInputs input){plan.update(input);}

    WalkRequest walkRequest() { return plan.walkRequest(); }

    RunOverlayState runOverlayState() { return plan.runOverlayState(); }

    void setRunItemsFilter(long account,boolean enabled) { plan.setRunItemsFilter(account,enabled); }

    void toggleRunItems(long account) { plan.toggleRunItems(account); }

    boolean showRunItems() { return plan.showRunItems(); }

    BankPreparation bankSearchPreparation() { return plan.bankSearchPreparation(); }

    BankPreparation bankPreparation() { return plan.bankPreparation(); }

    public void dispose() { plan.dispose(); }

    private static void replace(JTextArea area, String value)
    {
        if (!area.getText().equals(value))
        {
            int caret = area.getCaretPosition();
            area.setText(value);
            area.setCaretPosition(Math.min(caret, value.length()));
        }
    }

    private static JTextArea textArea()
    {
        JTextArea area = new JTextArea();
        area.setEditable(false);
        area.setLineWrap(true);
        area.setWrapStyleWord(true);
        return area;
    }
}

package com.herbrunplanner;

import java.awt.*;
import java.util.function.Supplier;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Draws decoration only; bank widgets and their click targets are untouched. */
final class HerbBankItemOverlay extends WidgetItemOverlay
{
    private final Supplier<BankPreparation> source;
    HerbBankItemOverlay(Supplier<BankPreparation> source)
    {
        this.source=source;drawAfterLayer(InterfaceID.Bankmain.ITEMS);
    }
    @Override public void renderItemOverlay(Graphics2D graphics,int itemId,WidgetItem item)
    {
        BankPreparation state=source.get();if(state==null)return;
        BankPreparation.Row row=state.items.get(itemId);if(row==null)return;
        Rectangle bounds=item.getCanvasBounds();
        Graphics2D g=(Graphics2D)graphics.create();
        try
        {
            g.setColor(row.color);g.setStroke(new BasicStroke(2));
            g.drawRect(bounds.x+1,bounds.y+1,Math.max(0,bounds.width-2),Math.max(0,bounds.height-2));
            if(row.withdraw>0)
            {
                String label="-"+row.withdraw;
                int x=bounds.x+bounds.width-g.getFontMetrics().stringWidth(label)-2;
                int y=bounds.y+bounds.height-2;
                g.setColor(Color.BLACK);g.drawString(label,x+1,y+1);
                g.setColor(BankPreparation.GOLD);g.drawString(label,x,y);
            }
        }
        finally{g.dispose();}
    }
}

package com.herbrunplanner;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/** Pure requirement evaluation. A missing flag always means unknown. */
public final class PatchEligibility
{
    private PatchEligibility() {}

    public static String evaluate(Map<String, Boolean> flags, int baseFarming, int currentFarming,
        boolean membersWorld)
    {
        List<String> rows = new ArrayList<>();
        rows.add("Patch access only; seed levels, supplies and teleports are checked separately.");
        rows.add("Standard worlds only. Special-mode area restrictions are not evaluated.");
        if (!membersWorld)
        {
            return "Locked: herb farming requires a members world. Switch worlds to check patches.";
        }
        rows.add("Falador — Available\nNo additional patch unlock.");
        rows.add("Catherby — Available\nNo additional patch unlock.");
        rows.add("Ardougne — Available\nNo additional patch unlock; diary teleport is separate.");
        rows.add("Hosidius — Available\nNo favour requirement; diary benefits are separate.");
        rows.add(quest("Port Phasmatys", "Priest in Peril", flags.get("PRIEST_IN_PERIL")));
        rows.add(quest("Troll Stronghold", "My Arm's Big Adventure", flags.get("MY_ARMS_BIG_ADVENTURE")));
        Boolean weiss = flags.get("MAKING_FRIENDS_WITH_MY_ARM");
        rows.add(Boolean.TRUE.equals(weiss)
            ? "Weiss — Unknown\nQuest complete. Fire of Nourishment construction is not detected yet; verify the fire is built."
            : quest("Weiss", "Making Friends with My Arm", weiss));
        rows.add(quest("Civitas illa Fortis", "Children of the Sun", flags.get("CHILDREN_OF_THE_SUN")));
        rows.add(currentFarming >= 65
            ? "Farming Guild — Available\n65 Farming requirement met."
                + (baseFarming < 65 ? " Temporary boost: maintain it to enter the intermediate wing." : "")
            : "Farming Guild — Locked\nRequires 65 current Farming for the intermediate wing (boostable). Current: "
                + currentFarming + "; base: " + baseFarming + ".");
        Boolean elite = flags.get("Morytania Elite");
        rows.add(elite == null ? "Harmony Island — Unknown\nMorytania Elite diary state unavailable."
            : !elite ? "Harmony Island — Locked\nComplete the Morytania Elite diary."
            : "Harmony Island — Unknown\nElite tasks complete. Reward collection is not verified yet; confirm rewards with the diary NPC.");
        return String.join("\n\n", rows);
    }

    private static String quest(String patch, String requirement, Boolean complete)
    {
        return patch + (complete == null ? " — Unknown\nCannot read " + requirement + "."
            : complete ? " — Available\n" + requirement + " complete."
            : " — Locked\nComplete " + requirement + ".");
    }
}

