package com.herbrunplanner;

import static com.herbrunplanner.PlanCatalog.Patch;

/** Approximate farming-area markers from RuneLite FarmingPatchLocation (see README attribution).
 * These are not herb-object footprints or confirmed interaction tiles. */
final class PatchDestination
{
    final int x,y;
    PatchDestination(int x,int y){this.x=x;this.y=y;}
    static PatchDestination forPatch(Patch patch)
    {
        if(patch==null)return null;
        switch(patch)
        {
            case GUILD:return new PatchDestination(1235,3724);
            case FALADOR:return new PatchDestination(3052,3309);
            case ARDOUGNE:return new PatchDestination(2663,3375);
            case HOSIDIUS:return new PatchDestination(1729,3558);
            case PHASMATYS:return new PatchDestination(3598,3524);
            case TROLL:return new PatchDestination(2828,3696);
            case WEISS:return new PatchDestination(2847,3933);
            case FORTIS:return new PatchDestination(1587,3101);
            case HARMONY:return new PatchDestination(3789,2840);
            case CATHERBY:return new PatchDestination(2810,3462);
            default:throw new IllegalArgumentException("Unknown patch");
        }
    }
    static final class Bearing
    {
        final int dx,dy,distance;
        final String direction;
        Bearing(int dx,int dy)
        {
            this.dx=dx;this.dy=dy;distance=(int)Math.ceil(Math.hypot(dx,dy));
            String[] names={"N","NE","E","SE","S","SW","W","NW"};
            int sector=(int)Math.round(Math.atan2(dx,dy)/(Math.PI/4));
            direction=distance==0?"Here":names[Math.floorMod(sector,8)];
        }
        String label(){return direction+" · about "+distance+" tiles (straight-line)";}
    }
    Bearing from(int playerX,int playerY){return new Bearing(x-playerX,y-playerY);}
}

package com.herbrunplanner;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
