import net.runelite.client.ui.overlay.worldmap.*;

/** Own minimap artwork and map point; never takes over the client's hint arrow. */
final class HerbNavigationOverlay extends Overlay
{
    private final Client client;
    private final Supplier<WalkRequest> source;
    private final WorldMapPointManager points;
    private DestinationPoint marker;
    private PlanCatalog.Patch patch;
    private long account=Long.MIN_VALUE;
    HerbNavigationOverlay(Client client,Supplier<WalkRequest> source,WorldMapPointManager points)
    {
        this.client=client;this.source=source;this.points=points;
        setPosition(OverlayPosition.DYNAMIC);setLayer(OverlayLayer.ABOVE_WIDGETS);
    }
    void clear(){if(marker!=null)points.remove(marker);marker=null;patch=null;account=Long.MIN_VALUE;}
    private WalkRequest request()
    {
        WalkRequest r=source.get();
        return r!=null && r.patch!=null && r.account==client.getAccountHash()
            && client.getGameState()==GameState.LOGGED_IN?r:null;
    }
    void update()
    {
        WalkRequest r=request();if(r==null){clear();return;}
        if(marker!=null && patch==r.patch && account==r.account)return;
        clear();patch=r.patch;account=r.account;
        PatchDestination d=PatchDestination.forPatch(patch);
        marker=new DestinationPoint(new WorldPoint(d.x,d.y,0),patch.label);points.add(marker);
    }
    @Override public Dimension render(Graphics2D graphics)
    {
        update();if(marker==null || client.getLocalPlayer()==null)return null;
        if(client.getTopLevelWorldView()==null || client.getTopLevelWorldView().isInstance()
            || client.getLocalPlayer().getWorldView()!=client.getTopLevelWorldView())return null;
        Widget minimap=client.getWidget(!client.isResized()?InterfaceID.Toplevel.MINIMAP:
            client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT)==1?InterfaceID.ToplevelPreEoc.MINIMAP:InterfaceID.ToplevelOsrsStretch.MINIMAP);
        if(minimap==null || minimap.isHidden())return null;
        int radius=Math.min(minimap.getWidth(),minimap.getHeight())/2-19;if(radius<=0)return null;
        WorldPoint player=client.getLocalPlayer().getWorldLocation(),dest=marker.getWorldPoint();
        double dx=dest.getX()-player.getX(),dy=dest.getY()-player.getY();
        java.awt.Point offset=NavigationMarker.project(dx,dy,(client.getCameraYawTarget()&0x3fff)*Math.PI/8192,client.getMinimapZoom(),radius);
        BufferedImage image=Math.hypot(dx*client.getMinimapZoom(),dy*client.getMinimapZoom())<=radius?NavigationMarker.PIN:NavigationMarker.direction(offset.x,offset.y);
        net.runelite.api.Point origin=minimap.getCanvasLocation();
        graphics.drawImage(image,origin.getX()+minimap.getWidth()/2+offset.x-14,origin.getY()+minimap.getHeight()/2+offset.y-14,null);
        return null;
    }
    private final class DestinationPoint extends WorldMapPoint
    {
        DestinationPoint(WorldPoint destination,String name)
        {
            super(destination,NavigationMarker.PIN);setSnapToEdge(true);setJumpOnClick(true);
            setName("Herb run: "+name);setTooltip(name+" herb patch area");
        }
        @Override public BufferedImage getImage()
        {
            if(!isCurrentlyEdgeSnapped())return NavigationMarker.PIN;
            net.runelite.api.Point center=client.getWorldMap().getWorldMapPosition();
            return NavigationMarker.direction(getWorldPoint().getX()-center.getX(),center.getY()-getWorldPoint().getY());
        }
    }
}

