/** Exact unnoted item IDs only. Notes/placeholders never imply usable supplies. */
public final class CarriedSupplies
{
    private CarriedSupplies() {}

    private static final class Variant
    {
        final String family;
        final int id;
        final String description;
        final boolean usableForm;
        Variant(String family, int id, String description, boolean usableForm)
        {
            this.family = family;
            this.id = id;
            this.description = description;
            this.usableForm = usableForm;
        }
    }

    private static final Variant[] VARIANTS = {
        new Variant("Ectophial", ItemID.ECTOPHIAL, "Filled ectophial", true),
        new Variant("Ectophial", ItemID.ECTOPHIAL_EMPTY, "Empty ectophial — refill before use", false),
