        new Variant("Amulet of glory", ItemID.AMULET_OF_GLORY_2, "Glory — 2 charges per item", true),
        new Variant("Amulet of glory", ItemID.AMULET_OF_GLORY_3, "Glory — 3 charges per item", true),
        new Variant("Amulet of glory", ItemID.AMULET_OF_GLORY_4, "Glory — 4 charges per item", true),
        new Variant("Amulet of glory", ItemID.AMULET_OF_GLORY_5, "Glory — 5 charges per item", true),
        new Variant("Amulet of glory", ItemID.AMULET_OF_GLORY_6, "Glory — 6 charges per item", true),
        new Variant("Amulet of glory", ItemID.TRAIL_AMULET_OF_GLORY, "Trimmed glory — uncharged", false),
        new Variant("Amulet of glory", ItemID.TRAIL_AMULET_OF_GLORY_1, "Trimmed glory — 1 charge per item", true),
        new Variant("Amulet of glory", ItemID.TRAIL_AMULET_OF_GLORY_2, "Trimmed glory — 2 charges per item", true),
        new Variant("Amulet of glory", ItemID.TRAIL_AMULET_OF_GLORY_3, "Trimmed glory — 3 charges per item", true),
        new Variant("Amulet of glory", ItemID.TRAIL_AMULET_OF_GLORY_4, "Trimmed glory — 4 charges per item", true),
        new Variant("Amulet of glory", ItemID.TRAIL_AMULET_OF_GLORY_5, "Trimmed glory — 5 charges per item", true),
        new Variant("Amulet of glory", ItemID.TRAIL_AMULET_OF_GLORY_6, "Trimmed glory — 6 charges per item", true),
        new Variant("Skills necklace", ItemID.JEWL_NECKLACE_OF_SKILLS, "Skills necklace — uncharged", false),
        new Variant("Skills necklace", ItemID.JEWL_NECKLACE_OF_SKILLS_1, "Skills necklace — 1 charge per item", true),
        new Variant("Skills necklace", ItemID.JEWL_NECKLACE_OF_SKILLS_2, "Skills necklace — 2 charges per item", true),
        new Variant("Skills necklace", ItemID.JEWL_NECKLACE_OF_SKILLS_3, "Skills necklace — 3 charges per item", true),
        new Variant("Skills necklace", ItemID.JEWL_NECKLACE_OF_SKILLS_4, "Skills necklace — 4 charges per item", true),
        new Variant("Skills necklace", ItemID.JEWL_NECKLACE_OF_SKILLS_5, "Skills necklace — 5 charges per item", true),
        new Variant("Skills necklace", ItemID.JEWL_NECKLACE_OF_SKILLS_6, "Skills necklace — 6 charges per item", true),
        new Variant("Amulet of glory", ItemID.AMULET_OF_GLORY_INF, "Eternal glory — unlimited charges", true),
        new Variant("Icy basalt", ItemID.WEISS_TELEPORT_BASALT, "Icy basalt — consumable", true),
        new Variant("Stony basalt", ItemID.STRONGHOLD_TELEPORT_BASALT, "Stony basalt — consumable", true),
        new Variant("Explorer's ring", ItemID.LUMBRIDGE_RING_EASY, "Ring 1 — no cabbage teleport", false),
        new Variant("Explorer's ring", ItemID.LUMBRIDGE_RING_MEDIUM, "Ring 2 — daily teleports unverified", false),
        new Variant("Explorer's ring", ItemID.LUMBRIDGE_RING_HARD, "Ring 3 — unlimited cabbage teleports", true),
        new Variant("Explorer's ring", ItemID.LUMBRIDGE_RING_ELITE, "Ring 4 — unlimited cabbage teleports", true),
        new Variant("Ardougne cloak", ItemID.ARDY_CAPE_EASY, "Cloak 1 — no farm-patch teleport", false),
        new Variant("Ardougne cloak", ItemID.ARDY_CAPE_MEDIUM, "Cloak 2 — daily farm teleports unverified", false),
        new Variant("Ardougne cloak", ItemID.ARDY_CAPE_HARD, "Cloak 3 — daily farm teleports unverified", false),
        new Variant("Ardougne cloak", ItemID.ARDY_CAPE_ELITE, "Cloak 4 — unlimited farm teleports", true),
        new Variant("Xeric's talisman", ItemID.XERIC_TALISMAN_EMPTY, "Inert talisman — charge before use", false),
        new Variant("Xeric's talisman", ItemID.XERIC_TALISMAN, "Talisman — remaining charges unverified", false)
    };

    private static java.util.List<Variant> allVariants()
    {
        java.util.List<Variant> variants=new java.util.ArrayList<>(java.util.Arrays.asList(VARIANTS));
        for(PlanCatalog.Travel t:PlanCatalog.Travel.values())
            if(t.item>0)variants.add(new Variant(t.label,t.item,t.label+" — consumable",true));
        for(PlanCatalog.Travel t:new PlanCatalog.Travel[]{PlanCatalog.Travel.COMBAT,PlanCatalog.Travel.DUELING})
        {
            int[] ids=PlanCatalog.jewelleryIds(t),charges=PlanCatalog.jewelleryCharges(t);
            for(int i=0;i<ids.length;i++)variants.add(new Variant(t==PlanCatalog.Travel.COMBAT?"Combat bracelet":"Ring of dueling",
                ids[i],PlanCatalog.name(ids[i])+" — "+charges[i]+" charges per item",true));
        }
        variants.add(new Variant("Combat bracelet",ItemID.JEWL_BRACELET_OF_COMBAT,"Combat bracelet — uncharged",false));
        return variants;
    }

    public static void add(Map<Integer, Integer> items, int id, int quantity)
    {
        if (id >= 0 && quantity > 0)
        {
            items.merge(id, quantity, Integer::sum);
        }
    }

    public static String render(Map<Integer, Integer> inventory, Map<Integer, Integer> equipment)
    {
        return render(inventory, equipment, null, "Bank unchecked.");
    }

    public static String render(Map<Integer, Integer> inventory, Map<Integer, Integer> equipment,
        Map<Integer, Integer> bank, String bankStatus)
    {
        Map<String, StringBuilder> carried = new LinkedHashMap<>();
        Map<String, StringBuilder> stored = new LinkedHashMap<>();
        Map<String, Boolean> usableCarried = new LinkedHashMap<>();
        Map<String, Variant> suggestions = new LinkedHashMap<>();
        for (Variant variant : allVariants())
        {
            StringBuilder lines = carried.computeIfAbsent(variant.family, key -> new StringBuilder());
            StringBuilder bankLines = stored.computeIfAbsent(variant.family, key -> new StringBuilder());
            append(lines, variant, inventory, "Inventory");
            append(lines, variant, equipment, "Equipped");
            append(bankLines, variant, bank, "Bank (observed)");
            if (variant.usableForm)
            {
                if (has(inventory, variant.id) || has(equipment, variant.id)) usableCarried.put(variant.family, true);
                if (has(bank, variant.id)) suggestions.put(variant.family, variant);
            }
        }
        StringBuilder text = new StringBuilder("Teleport supplies\n\n").append(bankStatus)
            .append("\n\nItem presence and form only. See Teleports and Patches for unlocks. Runes, other storage and location restrictions are not checked. Withdrawal suggestions are optional alternatives, not a complete loadout.\n\n");
        if (inventory == null || equipment == null)
        {
            text.append("Incomplete snapshot: ")
                .append(inventory == null ? "inventory unknown; " : "")
                .append(equipment == null ? "equipment unknown; " : "")
                .append("wait or refresh.\n\n");
        }
        for (Map.Entry<String, StringBuilder> entry : carried.entrySet())
        {
            String family = entry.getKey();
            StringBuilder bankLines = stored.get(family);
            text.append(family).append(" — ");
            if (entry.getValue().length() > 0) text.append("Carried\n");
            else if (bankLines.length() > 0) text.append("In bank (observed)\n");
            else if (inventory == null || equipment == null) text.append("Unknown\n");
            else if (bank == null) text.append("Not carried (bank unchecked)\n");
            else text.append("Not found in checked supplies\n");
            text.append(entry.getValue()).append(bankLines);
            if (!usableCarried.getOrDefault(family, false) && inventory != null && equipment != null)
            {
                Variant candidate = suggestions.get(family);
                if (candidate != null)
                {
                    text.append("If using this teleport, withdraw 1 unnoted: ").append(candidate.description)
                        .append(". Based on observed bank stock; confirm it is still there.\n");
                }
            }
            text.append("\n");
        }
        return text.append("Only listed item families are checked. Notes and placeholders do not count. Empty items and unverified allowances remain labelled; carried does not mean ready to teleport.").toString();
    }

    private static boolean has(Map<Integer, Integer> items, int id)
    {
        return items != null && items.getOrDefault(id, 0) > 0;
    }

    private static void append(StringBuilder text, Variant variant, Map<Integer, Integer> items, String location)
    {
        if (items == null) return;
        int quantity = items.getOrDefault(variant.id, 0);
        if (quantity > 0)
        {
            text.append(location).append(": ").append(quantity).append(" x ")
                .append(variant.description).append("\n");
        }
    }
}

