/** Owned, local-only bank header widgets; no game actions or synthetic clicks. */
final class HerbBankHeaderButton
{
    private final Client client;
    private final Runnable toggle;
    private Widget parent,background,icon;
    HerbBankHeaderButton(Client client,Runnable toggle){this.client=client;this.toggle=toggle;}
    void update(boolean prepared,boolean selected)
    {
        Widget bank=client.getWidget(InterfaceID.Bankmain.UNIVERSE);
        if(bank!=parent){destroy();parent=bank;}
        if(!prepared || bank==null || bank.isHidden()){hide();return;}
        List<Rectangle> occupied=new ArrayList<>();
        Widget[] children=bank.getDynamicChildren();
        if(children!=null)for(Widget child:children)
        {
            if(child==null || child==background || child==icon || child.isHidden())continue;
            String[] actions=child.getActions();boolean interactive=false;
            if(actions!=null)for(String action:actions)if(action!=null){interactive=true;break;}
            if(interactive)occupied.add(new Rectangle(child.getOriginalX(),child.getOriginalY(),child.getWidth(),child.getHeight()));
        }
        int x=BankHeaderPlacement.findX(bank.getWidth(),occupied);
        if(x<0){hide();return;}
        if(background==null)
        {
            background=bank.createChild(-1,WidgetType.GRAPHIC);
            background.setOriginalWidth(25);background.setOriginalHeight(25);
            background.setName("Herb Run Planner");background.setHasListener(true);
            background.setOnOpListener((JavaScriptCallback)event->{if(event.getOp()==2)toggle.run();});
            icon=bank.createChild(-1,WidgetType.GRAPHIC);
            icon.setOriginalWidth(19);icon.setOriginalHeight(19);
            icon.setSpriteId(SpriteID.Staticons2.FARMING);
        }
        background.setOriginalX(x);background.setOriginalY(5);
        background.setSpriteId(selected?SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED:SpriteID.Miscgraphics3.UNKNOWN_BUTTON_SQUARE_SMALL);
        background.setAction(1,selected?"Show all bank items":"View tab");
        icon.setOriginalX(x+3);icon.setOriginalY(8);
        background.setHidden(false);icon.setHidden(false);background.revalidate();icon.revalidate();
    }
    private void hide()
    {if(background!=null)background.setHidden(true);if(icon!=null)icon.setHidden(true);}
    void destroy()
    {
        hide();
        if(background!=null){background.setOnOpListener((Object[])null);background.setAction(1,null);}
        parent=null;background=null;icon=null;
    }
}

package com.herbrunplanner;

import java.awt.*;
import java.awt.image.BufferedImage;

/** A north-up compass cue, deliberately separate from the collision-aware scene line. */
final class CompassIcon
{
    static BufferedImage draw(PatchDestination.Bearing bearing)
    {
        BufferedImage image=new BufferedImage(92,68,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=image.createGraphics();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
            g.setFont(new Font(Font.SANS_SERIF,Font.BOLD,10));g.setColor(Color.LIGHT_GRAY);
            g.drawString("N",43,10);g.drawString("S",43,66);g.drawString("W",12,39);g.drawString("E",73,39);
            g.setColor(new Color(240,184,100));g.setStroke(new BasicStroke(3,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));
            if(bearing.distance==0){g.fillOval(42,31,8,8);return image;}
            double length=Math.hypot(bearing.dx,bearing.dy),ux=bearing.dx/length,uy=-bearing.dy/length;
            int cx=46,cy=35,tx=cx+(int)Math.round(ux*19),ty=cy+(int)Math.round(uy*19);
            g.drawLine(cx-(int)(ux*12),cy-(int)(uy*12),tx,ty);
            g.drawLine(tx,ty,tx-(int)(ux*8-uy*6),ty-(int)(uy*8+ux*6));
            g.drawLine(tx,ty,tx-(int)(ux*8+uy*6),ty-(int)(uy*8-ux*6));
        }
        finally{g.dispose();}
        return image;
    }
}

package com.herbrunplanner;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/** Requirement checks only. Never claims that supplies or charges are available. */
public final class TeleportEligibility
{
    private TeleportEligibility() {}

    public static String bookName(int book)
    {
        switch (book)
        {
            case 0: return "Standard";
            case 1: return "Ancient";
            case 2: return "Lunar";
            case 3: return "Arceuus";
            default: return "Unknown";
        }
    }

    public static String evaluate(Map<String, Boolean> flags, int magic, int book, boolean members)
    {
        if (!members) return "Switch to a members world to evaluate herb-run travel.";
        List<String> rows = new ArrayList<>();
        rows.add("Current Magic: " + magic + "\nSpellbook: " + bookName(book));
        rows.add("Unlock checks only. See Supplies for carried items, observed bank stock and known charge variants. See Runes for inventory, pouch, staff and combination-rune coverage. Reward collection and location restrictions are NOT checked. See Patches for access.");
        rows.add(spell("Falador spell → Falador patch", flags, null, 37, magic, 0, book));
        rows.add(spell("Camelot spell → Catherby patch", flags, null, 45, magic, 0, book));
        rows.add(spell("Catherby spell → Catherby patch", flags, "LUNAR_DIPLOMACY", 87, magic, 2, book));
        rows.add(spell("Fishing Guild spell → Ardougne patch", flags, "LUNAR_DIPLOMACY", 85, magic, 2, book));
        rows.add(spell("Trollheim spell → Troll Stronghold patch", flags, "EADGARS_RUSE", 61, magic, 0, book));
        rows.add(spell("Civitas illa Fortis spell → Fortis patch", flags, "TWILIGHTS_PROMISE", 54, magic, 0, book));
        rows.add(spell("Harmony Island spell → Harmony patch", flags, "THE_GREAT_BRAIN_ROBBERY", 65, magic, 3, book));
        rows.add(item("Ectophial → Port Phasmatys", flags, "GHOSTS_AHOY", "A filled ectophial"));
        rows.add(item("Icy basalt → Weiss", flags, "MAKING_FRIENDS_WITH_MY_ARM", "Icy basalt"));
        rows.add(item("Stony basalt → Troll Stronghold", flags, "MAKING_FRIENDS_WITH_MY_ARM", "Stony basalt; landing point/shortcut not evaluated"));
        rows.add(item("Explorer's ring 2+ → Falador patch", flags, "Lumbridge Medium", "Diary rewards, ring and remaining daily teleports"));
        rows.add(item("Ardougne cloak 2+ → Ardougne patch", flags, "Ardougne Medium", "Diary rewards, cloak and remaining daily teleports"));
        rows.add("Amulet of glory → Draynor (Falador patch) — Supplies unchecked\nNo quest/level gate for the item teleport; charged amulet required.");
        rows.add("Skills necklace → Farming Guild / Fishing Guild / Woodcutting Guild — Supplies unchecked\nNo quest/level gate for these item destinations. Farming Guild patch still needs its own access check.");
        rows.add("Xeric's talisman → Xeric's Glade (Hosidius) — Supplies unchecked\nTalisman ownership and charges not detected.");
        for(PlanCatalog.Travel t:PlanCatalog.Travel.values())
        {
            if(t.item>0)rows.add(t.gate==null?t.label+" — No spellbook/Magic gate\nAlready-made tablet required; patch access is separate."
                :item(t.label,flags,t.gate,"Already-made tablet; no spellbook or Magic level requirement"));
        }
        rows.add("Combat bracelet → Ranging Guild — Supplies unchecked\nCharged bracelet required; teleport is outside the guild. Walk to Ardougne patch.");
        rows.add("Ring of dueling → Castle Wars bank — Supplies unchecked\nCharged ring required.");
        rows.add("Other options — Unknown\nUnlisted tablets, fairy rings, house facilities, quetzal whistles and other travel methods are not evaluated yet.");
        return String.join("\n\n", rows);
    }

    static String spell(String name, Map<String, Boolean> flags, String quest, int level,
        int magic, int requiredBook, int currentBook)
    {
        List<String> blockers = new ArrayList<>();
        boolean unknown = false;
        if (quest != null)
        {
            Boolean done = flags.get(quest);
            if (done == null) unknown = true;
            else if (!done) blockers.add("Complete " + friendly(quest));
        }
        if (magic < level) blockers.add("Requires " + level + " current Magic (boostable)");
        if (currentBook < 0 || currentBook > 3) unknown = true;
        else if (currentBook != requiredBook) blockers.add("Switch to " + bookName(requiredBook) + " spellbook");
        if (!blockers.isEmpty()) return name + " — Requirements missing\n" + String.join("; ", blockers)
            + (unknown ? "; some requirement data is also unknown." : ".");
        if (unknown) return name + " — Unknown\nQuest or spellbook data unavailable.";
        return name + " — Requirements met\nRunes and ability to cast from your current location unchecked.";
    }

    static String item(String name, Map<String, Boolean> flags, String gate, String supplies)
    {
        Boolean done = flags.get(gate);
        if (done == null) return name + " — Unknown\nCannot verify " + friendly(gate) + ".";
        if (!done) return name + " — Locked\nComplete " + friendly(gate) + ".";
        return name + " — Gate met; supplies unchecked\nVerify: " + supplies + ".";
    }

    private static String friendly(String key)
    {
        switch (key)
        {
            case "PLAGUE_CITY": return "Plague City";
            case "LUNAR_DIPLOMACY": return "Lunar Diplomacy";
            case "EADGARS_RUSE": return "Eadgar's Ruse";
            case "TWILIGHTS_PROMISE": return "Twilight's Promise";
            case "THE_GREAT_BRAIN_ROBBERY": return "The Great Brain Robbery";
            case "GHOSTS_AHOY": return "Ghosts Ahoy";
            case "MAKING_FRIENDS_WITH_MY_ARM": return "Making Friends with My Arm";
            default: return key;
        }
    }
}

