    private void relevantControls()
    {
        weiss.setVisible(selected.get(Patch.WEISS).isSelected());
        harmony.setVisible(selected.get(Patch.HARMONY).isSelected());
        Set<Travel> relevant=EnumSet.noneOf(Travel.class);
        for(Patch p:Patch.values())
        {
            boolean enabled=snapshot!=null && selected.get(p).isSelected();
            methodRows.get(p).setVisible(enabled);
            Travel t=(Travel)methods.get(p).getSelectedItem();
            for(Travel limited:TeleportUses.METHODS)
                if(enabled && (t==limited || (t==Travel.AUTO && Arrays.asList(p.methods).contains(limited)
                    && PlanEngine.unavailable(snapshot,limited).isEmpty() && ExtendedTravel.hasAny(snapshot,PlanEngine.items(limited)))))relevant.add(limited);
        }
        for(Travel t:TeleportUses.METHODS)
        {
            JTextArea status=useStatus.get(t);boolean visible=snapshot!=null && relevant.contains(t);
            String value=visible?TeleportUses.status(snapshot,t):"";
            if(!status.getText().equals(value))status.setText(value);
            status.setVisible(visible);
            JCheckBox check=travelChecks.get(TeleportUses.key(t));
            boolean unknown=visible && TeleportUses.remaining(snapshot,t)<0;
            check.setVisible(unknown);
            if(!unknown)check.setSelected(false);
        }
        chargeConfirmation.setVisible(snapshot!=null && !relevant.isEmpty());
        ownCompost.setVisible(compost.getSelectedItem()==Compost.MANUAL);
        confirmations.setVisible(snapshot!=null && (weiss.isVisible() || harmony.isVisible() || ownCompost.isVisible()));
        revalidate();
    }
    public void update(PlanInputs next)
    {
        if(activeRun!=null && next.account==account)
        {
            snapshot=next;loading=false;
            resultStatus.setText(activeRun.complete()?"Run checklist complete":"Run in progress");
            return;
        }
        boolean different=loading || !next.sameState(snapshot);
        loading=false;
        boolean refreshPrepared=different && preparedChoices!=null && next.sameRequirements(snapshot);
        updating=true;
        boolean newAccount=next.account!=account;
        if(newAccount)
        {
            activeRun=null;autoRequest=null;walkRequest=null;timingRequest=null;runOverlayState=null;preparedReport=null;pages.setEnabledAt(0,true);pages.setEnabledAt(2,true);
            bankPreparation=null;bankSearchPreparation=null;showRunItems=false;preparedChoices=null;openResultsWhenReady=false;cancel();
            character="";account=next.account;for(JCheckBox check:travelChecks.values())check.setSelected(false);houseEntry.setSelectedItem(Travel.AUTO);externalNetworks.setSelected(false);travelTiming.setSelected(false);includeObtain.setSelected(false);
            for(JCheckBox c:new JCheckBox[]{weiss,harmony,ownCompost})c.setSelected(false);
            bankReturn.setSelectedItem(ReturnToBank.FINISH);
            herb.setSelectedIndex(4);compost.setSelectedItem(Compost.ULTRA);rake.setSelected(true);
            walkingPath.setSelected(true);runOverlay.setSelected(true);bankOverlay.setSelected(true);bankHelperVisible=true;
            preferences=RunPreferences.decode(preferenceStore.load(account));
            for(Patch p:Patch.values())
            {
                selected.get(p).setSelected(next.patchGate(p) && p!=Patch.WEISS && p!=Patch.HARMONY);
                methods.get(p).setSelectedItem(Travel.AUTO);
            }
            clearResult("Prepare a run to see your supplies and route.");
        }
        snapshot=next;
        if(!gearSignature().equals(gearLabelSignature))renderGear();
        for(Patch p:Patch.values())
        {
            JCheckBox check=selected.get(p);boolean gate=next.patchGate(p);
            if(!gate)check.setSelected(false);
            check.setEnabled(gate);check.setText(p.label);
            check.setToolTipText(gate?null:"Access not confirmed. See Account details → Patches.");
            JComboBox<Travel> combo=methods.get(p);
            Travel previous=(Travel)combo.getSelectedItem();
            java.util.List<Travel> allowed=new ArrayList<>();allowed.add(Travel.AUTO);
            for(Travel t:p.methods)if(PlanEngine.unavailable(next,t).isEmpty())allowed.add(t);
            allowed.add(Travel.MANUAL);
            java.util.List<String> excluded=new ArrayList<>();
            for(Travel t:p.methods)
            {
                String reason=PlanEngine.unavailable(next,t);
                for(String key:ExtendedTravel.requiredChecks(t))
                {
                    if(externalNetworks.isSelected() && (key.equals("HOUSE_SPIRIT_TREE") || key.equals("HOUSE_FAIRY_RING")))continue;
                    JCheckBox confirmation=travelChecks.get(key);
                    if(confirmation!=null && !confirmation.isSelected())reason+=(reason.isEmpty()?"":"; ")+"Confirm: "+ExtendedTravel.CHECKS.get(key);
                }
                if(!reason.isEmpty())excluded.add(t.label+": "+reason);
            }
            JTextArea reasons=methodReasons.get(p);
            String reasonText=String.join("\n",excluded);
            if(!reasons.getText().equals(reasonText))reasons.setText(reasonText);
            methodReasons.get(p).setVisible(!excluded.isEmpty());
            java.util.List<Travel> existing=new ArrayList<>();for(int i=0;i<combo.getItemCount();i++)existing.add(combo.getItemAt(i));
            if(!existing.equals(allowed))combo.setModel(new DefaultComboBoxModel<>(allowed.toArray(new Travel[0])));
            combo.setSelectedItem(allowed.contains(previous)?previous:Travel.AUTO);
        }
        if(newAccount)restorePreferences();
        build.setEnabled(worker==null);updating=false;relevantControls();
        if(preparedChoices!=null)
        {
            Set<String> retained=new HashSet<>(preparedChoices.travelChecks);
            for(Travel t:TeleportUses.METHODS)
                if(!travelChecks.get(TeleportUses.key(t)).isSelected())retained.remove(TeleportUses.key(t));
            preparedChoices=preparedChoices.withTransport(retained,preparedChoices.houseEntry);
        }
        if(different)
        {
            revision++;
            if(refreshPrepared)
            {
                cancel();calculate(true);
            }
            else
            {
                bankPreparation=null;bankSearchPreparation=null;showRunItems=false;preparedChoices=null;cancel();build.setEnabled(true);
                status.setText("Choose your run, then prepare.");resultStatus.setForeground(new Color(240,184,100));
                resultStatus.setText("Account requirements changed — prepare again before using these quantities.");
            }
        }
    }
    public void suspend(boolean reset)
    {
        if(!reset)
        {
            // A region load pauses reads; it does not end the prepared run.
            bankPreparation=null;bankSearchPreparation=null;loading=true;revision++;cancel();build.setEnabled(false);
            status.setText("Loading map… your prepared run is retained.");
            resultStatus.setForeground(new Color(240,184,100));
            resultStatus.setText(activeRun==null?"Loading map… route retained; supply updates resume afterward.":"Loading map… run progress retained.");
            for(JCheckBox c:selected.values())c.setEnabled(false);
            return;
        }
        loading=false;activeRun=null;autoRequest=null;walkRequest=null;timingRequest=null;runOverlayState=null;preparedReport=null;pages.setEnabledAt(0,true);pages.setEnabledAt(2,true);
        snapshot=null;bankPreparation=null;bankSearchPreparation=null;showRunItems=false;preparedChoices=null;openResultsWhenReady=false;revision++;cancel();build.setEnabled(false);updating=true;
        if(reset)
        {
            profileLabel.setText("Log in to load your profile");savedGear.clear();gearIds=Collections.emptySet();gearEditor.load(new RunPreferences());profileName.setText("");autoRequest=null;
            account=Long.MIN_VALUE;for(JCheckBox check:travelChecks.values())check.setSelected(false);
            for(JCheckBox c:new JCheckBox[]{weiss,harmony,ownCompost})c.setSelected(false);
            for(JCheckBox c:selected.values())c.setSelected(false);
        }
        for(JCheckBox c:selected.values())c.setEnabled(false);
        status.setText(reset?"Log in to prepare a run.":"Loading account data… selections retained.");
        clearResult("Waiting for account data. Prepare again after loading.");updating=false;relevantControls();
    }
