        gearEditor.load(preferences);savedGear.addAll(gearEditor.items());
        useGear.setSelected(preferences.flag("useGear",true));autoSteps.setSelected(preferences.flag("autoSteps",true));
        profileName.setText(preferences.values.getOrDefault("profileName",""));
        for(int i=0;i<3;i++)preparationExpanded[i]=preferences.flag("prepSection."+i,i<2);
        renderGear();updateProfileLabel();

        for(Herb h:HERBS)if(Integer.toString(h.id).equals(preferences.values.get("seed")))herb.setSelectedItem(h);
        compost.setSelectedItem(preferences.option("compost",Compost.ULTRA));
        bankReturn.setSelectedItem(preferences.option("finish",ReturnToBank.FINISH));
        externalNetworks.setSelected(preferences.flag("externalNetworks",false));
        Travel savedEntry=preferences.option("houseEntry",Travel.AUTO);houseEntry.setSelectedItem(savedEntry==Travel.AUTO || ExtendedTravel.ENTRY.contains(savedEntry)?savedEntry:Travel.AUTO);
        rake.setSelected(preferences.flag("rake",true));includeObtain.setSelected(preferences.flag("obtain",false));
        walkingPath.setSelected(preferences.flag("walking",true));runOverlay.setSelected(preferences.flag("overlay",true));
        bankOverlay.setSelected(preferences.flag("bankOverlay",true));bankHelperVisible=bankOverlay.isSelected();
        for(Patch p:Patch.values())
        {
            JCheckBox check=selected.get(p);
            check.setSelected(check.isEnabled() && preferences.flag("patch."+p.name(),check.isSelected()));
            JComboBox<Travel> combo=methods.get(p);Travel choice=preferences.option("travel."+p.name(),Travel.AUTO);
            for(int i=0;i<combo.getItemCount();i++)if(combo.getItemAt(i)==choice)combo.setSelectedItem(choice);
        }
    }
    private void savePreferences(boolean setup)
    {
        if(updating || loading || snapshot==null || account==Long.MIN_VALUE)return;
        if(setup)
        {
            preferences.put("seed",((Herb)herb.getSelectedItem()).id);
            preferences.put("compost",((Compost)compost.getSelectedItem()).name());
            preferences.put("finish",((ReturnToBank)bankReturn.getSelectedItem()).name());
            preferences.put("externalNetworks",externalNetworks.isSelected());
            preferences.put("houseEntry",((Travel)houseEntry.getSelectedItem()).name());
            preferences.put("rake",rake.isSelected());preferences.put("obtain",includeObtain.isSelected());
            for(Patch p:Patch.values())if(selected.get(p).isEnabled())
            {
                preferences.put("patch."+p.name(),selected.get(p).isSelected());
                preferences.put("travel."+p.name(),((Travel)methods.get(p).getSelectedItem()).name());
            }
        }
        for(int i=0;i<3;i++)preferences.put("prepSection."+i,preparationExpanded[i]);
        preferences.put("autoSteps",autoSteps.isSelected());
        preferences.put("walking",walkingPath.isSelected());preferences.put("overlay",runOverlay.isSelected());
        preferences.put("bankOverlay",bankOverlay.isSelected());
        preferenceStore.save(account,preferences.encode());
    }
    private Set<String> confirmedTravel()
    {Set<String> result=new HashSet<>();travelChecks.forEach((key,check)->{if(check.isSelected())result.add(key);});return result;}
    private PlanInputs.Choices choices()
    {
        EnumMap<Patch,Travel> patches=new EnumMap<>(Patch.class);
        for(Patch p:Patch.values())if(selected.get(p).isSelected())patches.put(p,(Travel)methods.get(p).getSelectedItem());
        return new PlanInputs.Choices((Herb)herb.getSelectedItem(),patches,(ReturnToBank)bankReturn.getSelectedItem(),
            (Compost)compost.getSelectedItem(),weiss.isSelected(),harmony.isSelected(),false,ownCompost.isSelected(),rake.isSelected(),snapshot.hasMagicSecateurs(),includeObtain.isSelected()).withTransport(confirmedTravel(),(Travel)houseEntry.getSelectedItem()).withExternalNetworks(externalNetworks.isSelected());
    }
    private void calculate(){calculate(false);}
    private void calculate(boolean automatic)
    {
        if(snapshot==null || loading || worker!=null || activeRun!=null)return;
        final PlanInputs captured=snapshot.withGear(useGear.isSelected()?savedGear:Collections.emptySet());
        final PlanInputs.Choices options=automatic?preparedChoices:choices();final long started=revision;
        if(options==null)return;
        if(!automatic)bankPreparation=null;if(!automatic)bankSearchPreparation=null;preparedChoices=options;
        if(!automatic)openResultsWhenReady=true;
        build.setEnabled(false);status.setText(automatic?"Updating supplies…":"Preparing supplies and travel…");
        if(automatic){resultStatus.setForeground(new Color(240,184,100));resultStatus.setText("Updating supplies…");}
        worker=new SwingWorker<PlanEngine.Report,Void>()
        {
            protected PlanEngine.Report doInBackground(){return PlanEngine.report(captured,options);}
            protected void done()
            {
                if(worker!=this)return;
                worker=null;build.setEnabled(snapshot!=null && !loading);
                if(snapshot==null || revision!=started){status.setText("Data changed. Prepare again.");return;}
                try
                {
                    PlanEngine.Report report=get();
                    preparedChoices=report.resolvedChoices;preparedReport=report;
                    bankPreparation=!report.supplies.isEmpty()?new BankPreparation(captured.account,report,captured.bank==null):null;
                    bankSearchPreparation=bankPreparation;
                    relevantControls();showReport(report,captured.bankStatus,captured.bank==null,automatic);
                    status.setText("Plan prepared. Supplies update automatically.");if(openResultsWhenReady){pages.setSelectedIndex(1);openResultsWhenReady=false;}
                }
                catch(Exception ex){bankPreparation=null;bankSearchPreparation=null;showRunItems=false;preparedChoices=null;status.setText("Could not prepare. Refresh account data and try again.");resultStatus.setText("Update failed — prepare again before using these quantities.");}
            }
        };worker.execute();
    }
    private void clearResult(String message){resultBody.removeAll();resultStatus.setText(message);resultBody.add(resultStatus);resultBody.revalidate();resultBody.repaint();}
    private void showReport(PlanEngine.Report report,String bankStatus,boolean unknown,boolean preserveView)
