{
    static boolean herb(int id)
    {
        return id==FARMING_HERB_PATCH_1 || id==FARMING_HERB_PATCH_2 || id==FARMING_HERB_PATCH_3
            || id==FARMING_HERB_PATCH_4 || id==FARMING_HERB_PATCH_5 || id==FARMING_HERB_PATCH_6
            || id==FARMING_HERB_PATCH_7 || id==FARMING_HERB_PATCH_8 || id==MYARM_HERBPATCH
            || id==MY2ARM_HERBPATCH || id==MY2ARM_HERBPATCH_ACCESS;
    }
    static PlanCatalog.Patch patch(int region)
    {
        switch(region)
        {
            case 10548:return ARDOUGNE;
            case 11062:case 11061:case 11318:case 11317:return CATHERBY;
            case 6192:case 6447:case 6448:case 6449:case 6191:case 6193:return FORTIS;
            case 12083:return FALADOR;
            case 15148:return HARMONY;
            case 6967:case 6711:return HOSIDIUS;
            case 14391:case 14390:return PHASMATYS;
            case 11321:return TROLL;
            case 11325:return WEISS;
            case 4922:case 5177:case 5178:case 5179:case 4921:case 4923:case 4665:case 4666:case 4667:return GUILD;
            default:return null;
        }
    }
}

