    @Override
    protected void startUp()
    {
        active = true;
        panel = new HerbRunPlannerPanel(() -> clientThread.invokeLater(() -> dirty = true), (id, label) -> {
            net.runelite.client.util.AsyncBufferedImage image = itemManager.getImage(id);
            if (image != null) { label.setText(""); image.addTo(label); }
        },new RunPreferences.Store()
        {
            public String load(long account){return configManager.getConfiguration("herbrunplanner","setup."+Long.toUnsignedString(account));}
            public void save(long account,String value){configManager.setConfiguration("herbrunplanner","setup."+Long.toUnsignedString(account),value);}
        });
        panel.gearSearch((slot,done)->clientThread.invokeLater(()->{
            if(!active || client.getGameState()!=net.runelite.api.GameState.LOGGED_IN)return;
            gearSearch=gearSearchProvider.get();
            gearSearch.onItemSelected(id->{int canonical=GearVariants.canonical(id);cacheGearItem(canonical);SwingUtilities.invokeLater(()->{if(active)done.accept(canonical);});})
                .tooltipText("Use in gear set").prompt("Search equipment").build();
        }));
        BufferedImage icon = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = icon.createGraphics();
        graphics.setColor(new Color(95, 190, 100));
        graphics.fillOval(3, 1, 11, 10);
        graphics.drawLine(3, 15, 10, 5);
        graphics.dispose();
        navigation = NavigationButton.builder().tooltip("Herb Run Planner").icon(icon)
            .priority(6).panel(panel).build();
        clientToolbar.addNavigation(navigation);
        automaticProgress=new AutomaticRunProgress(client,()->active && panel!=null?panel.autoRequest():null,request->{
            HerbRunPlannerPanel target=panel;SwingUtilities.invokeLater(()->{if(active && panel==target)target.automaticDone(request);});
        });
        bankLayout=new HerbBankLayout(client,itemManager);
        bankHeaderButton=new HerbBankHeaderButton(client,this::toggleFromBank);
        bankOverlay=new HerbBankOverlay(this::bankPreparation,client,itemManager,tooltipManager);
        bankItemOverlay=new HerbBankItemOverlay(this::bankPreparation);
        overlayManager.add(bankOverlay);overlayManager.add(bankItemOverlay);
        runOverlay=new HerbRunOverlay(this::runOverlayState,client,itemManager,spriteManager,tooltipManager);overlayManager.add(runOverlay);
        walkingGuide=new HerbWalkingGuide(client,()->{
            if(!active || panel==null)return null;
            WalkRequest walk=panel.walkRequest();TravelTimer.Request timing=panel.timingRequest();
