    @Override
    protected void shutDown()
    {
        active = false;
        clientThread.invokeLater(()->{if(gearSearch!=null && chatboxPanelManager.getCurrentInput()==gearSearch)chatboxPanelManager.close();gearSearch=null;});
        overlayManager.remove(bankOverlay);overlayManager.remove(bankItemOverlay);overlayManager.remove(runOverlay);
        overlayManager.remove(walkingLine);overlayManager.remove(navigationOverlay);
        navigationOverlay.clear();
        clientToolbar.removeNavigation(navigation);
