            if(bankHeaderButton!=null)bankHeaderButton.destroy();
            if(bankLayout!=null)bankLayout.clear();
            // Rebuild with our callback disabled so no filtered bank layout remains.
            if(isBankVisible())bankSearch.layoutBank();
            displayedRunFilter=false;displayedSearchItems=java.util.Collections.emptySet();
            questStates.clear();
            walkingGuide.clear();
            bankSnapshot.clear();
