    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        // Never display one account's snapshot while another account is loading.
        if (event.getGameState() == GameState.LOADING)
        {
            observedUses.invalidateXeric();
            if(automaticProgress!=null)automaticProgress.clear();
            if(bankHeaderButton!=null)bankHeaderButton.update(false,false);
            if(bankLayout!=null)bankLayout.clear();
            if(walkingGuide!=null)walkingGuide.clear();
            if(navigationOverlay!=null)navigationOverlay.clear();
            // Region loading is not logout. Keep this account's observed bank snapshot.
            questStates.clear();
            bankOpen = false;
            bankDirty = true;
            ticksSinceRead = 0;
            dirty = true;
            publish("Loading account data...", "", "", "", "", "", "", "", null);
        }
        else if (event.getGameState() != GameState.LOGGED_IN)
        {
            clearSession();
        }
        else
        {
            dirty = true;
        }
    }

    @Subscribe
    public void onGameObjectSpawned(net.runelite.api.events.GameObjectSpawned event)
