    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if(event.getContainerId()==InventoryID.BANK || event.getContainerId()==InventoryID.INV || event.getContainerId()==InventoryID.WORN)suppliesDirty=true;
        if (event.getContainerId() == InventoryID.BANK)
        {
            bankDirty = true;
            dirty = true;
            // Capture updates while visible, including a withdrawal followed by a quick close.
            if (active && client.getGameState() == GameState.LOGGED_IN && isBankVisible())
            {
                observeBank();
            }
        }
        if (event.getContainerId() == InventoryID.INV || event.getContainerId() == InventoryID.WORN)
        {
            dirty = true;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!active || client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            return;
        }
        long account = client.getAccountHash();
        if (account != lastAccount)
        {
            clearSession();
            lastAccount = account;
        }
        refreshHerbBankSearch();
        if(walkingGuide!=null)walkingGuide.tick();
        if(navigationOverlay!=null)navigationOverlay.update();
        TravelTimer.Request timing=panel.timingRequest();
        net.runelite.api.coords.WorldPoint position=client.getLocalPlayer().getWorldLocation();
        boolean supported=client.getTopLevelWorldView()!=null && !client.getTopLevelWorldView().isInstance()
            && client.getLocalPlayer().getWorldView()==client.getTopLevelWorldView();
        travelTimer.tick(timing!=null && timing.account==account?timing:null,position.getX(),position.getY(),position.getPlane(),
            System.nanoTime()/1_000_000L,timing!=null && walkingGuide.atPatch(timing.patch),supported);
        String timingText=travelTimer.describe();
        if(!timingText.equals(displayedTiming))
        {
            displayedTiming=timingText;HerbRunPlannerPanel target=panel;
            SwingUtilities.invokeLater(()->{if(active && panel==target)target.timingText(timingText);});
        }
        updateLeprechaun();
        updateBank();
        cacheGearNames(lastPlanInputs==null?null:lastPlanInputs.equipment);
        if(automaticProgress!=null)automaticProgress.tick(bankOpen);
        if(suppliesDirty && lastPlanInputs!=null && lastPlanInputs.account==account)refreshSupplies();
        // Coalesce changes; no quest scripts on every frame or every varbit event.
        if (++ticksSinceRead < 5 || !dirty)
        {
            return;
        }
        ticksSinceRead = 0;
        dirty = false;
        StringBuilder levels = new StringBuilder();
        for (Skill skill : Skill.values())
        {
            if (skill == Skill.OVERALL)
            {
                continue;
            }
            levels.append(skill.getName()).append(": ")
                .append(client.getRealSkillLevel(skill)).append(" (current ")
                .append(client.getBoostedSkillLevel(skill)).append(")\n");
        }
        questStates.clear();
        int unknown = 0;
        StringBuilder quests = new StringBuilder();
        for (Quest quest : Quest.values())
        {
            QuestState state = null;
            try
            {
                // Official API executes the local quest-status script, on the client thread.
                state = quest.getState(client);
            }
            catch (RuntimeException ex)
            {
                // Missing/loading state is unknown, never silently "not started".
                dirty = true;
            }
            if (state != null)
            {
                questStates.put(quest, state);
            }
            else
            {
                unknown++;
            }
            quests.append(quest.getName()).append(": ")
                .append(state == null ? "Unknown" : state.name().replace('_', ' ')).append("\n");
        }
        long finished = questStates.values().stream().filter(s -> s == QuestState.FINISHED).count();
        String summary = "Account: " + client.getLocalPlayer().getName()
            + "\nWorld: " + client.getWorld()
            + "\nCompleted quest entries: " + finished + " / " + Quest.values().length
            + "\nUnknown entries: " + unknown
            + "\n\nQuests include miniquests/subquests exposed by RuneLite."
            + "\nPatch access and diary tasks: see Patches and Diaries.\nTeleport unlocks: see Teleports. Carried and observed bank items: see Supplies. Rune sources: see Runes.";
        Map<String, Boolean> flags = new LinkedHashMap<>();
        for (Map.Entry<Quest, QuestState> entry : questStates.entrySet())
        {
            flags.put(entry.getKey().name(), entry.getValue() == QuestState.FINISHED);
        }
        String diaries = readDiaries(flags);
        String patches = PatchEligibility.evaluate(flags, client.getRealSkillLevel(Skill.FARMING),
            client.getBoostedSkillLevel(Skill.FARMING), client.getWorldType().contains(net.runelite.api.WorldType.MEMBERS));
        int spellbook = -1;
        try
        {
            spellbook = client.getVarbitValue(VarbitID.SPELLBOOK);
        }
        catch (RuntimeException ex)
        {
            dirty = true;
        }
        String teleports = TeleportEligibility.evaluate(flags, client.getBoostedSkillLevel(Skill.MAGIC),
            spellbook, client.getWorldType().contains(net.runelite.api.WorldType.MEMBERS));
        Map<Integer, Integer> inventory = readCarried(InventoryID.INV);
        Map<Integer, Integer> equipment = readCarried(InventoryID.WORN);
        cacheGearNames(equipment);
        String supplies = CarriedSupplies.render(inventory, equipment,
            bankSnapshot.items(), bankSnapshot.status(bankOpen));
        supplies += "\n\n" + LeprechaunStorage.describe(leprechaunItems);
        Map<Integer, Integer> pouch = RuneSources.pouch(client, inventory);
        if (pouch == null) dirty = true;
        String runes = AdvancedRuneSupplies.render(inventory, pouch, RuneEquipment.staffMask(equipment),
            equipment != null, bankSnapshot.items(), bankSnapshot.status(bankOpen));
        ItemContainer invContainer = client.getItemContainer(InventoryID.INV);
        int occupied = -1;
        if (invContainer != null)
        {
            occupied = 0;
            for (Item item : invContainer.getItems())
                if (item != null && item.getId() > 0 && item.getQuantity() > 0) occupied++;
        }
        flags.put("FARMING_99",client.getRealSkillLevel(Skill.FARMING)>=99);
        flags.put("CRAFTING_99",client.getRealSkillLevel(Skill.CRAFTING)>=99);
        flags.put("CONSTRUCTION_99",client.getRealSkillLevel(Skill.CONSTRUCTION)>=99);
        flags.put("HUNTER_99",client.getRealSkillLevel(Skill.HUNTER)>=99);
        int houseLocation=client.getVarbitValue(VarbitID.POH_HOUSE_LOCATION);
        flags.put("HOUSE_OWNED",houseLocation>0);
        flags.put("HOUSE_HOSIDIUS",houseLocation==8);
        PlanInputs planInputs = new PlanInputs(account, client.getBoostedSkillLevel(Skill.MAGIC),
            client.getBoostedSkillLevel(Skill.FARMING), client.getRealSkillLevel(Skill.FARMING),
            spellbook, RuneEquipment.staffMask(equipment), occupied,
            client.getWorldType().contains(net.runelite.api.WorldType.MEMBERS), bankOpen,
            bankSnapshot.status(bankOpen), flags, inventory, equipment, pouch, bankSnapshot.items(), leprechaunItems);
        planInputs=planInputs.withCompost(client.getVarbitValue(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE),client.getVarbitValue(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY));
        planInputs=planInputs.withTeleportUses(observedUses.snapshot(client.getVarbitValue(VarbitID.LUMBRIDGE_CABBAGE_TELEPORT),
            planInputs,java.time.LocalDate.now(java.time.ZoneOffset.UTC).toEpochDay()));
        lastPlanInputs=planInputs;suppliesDirty=false;
        publish(summary, levels.toString(), quests.toString(), patches, diaries, teleports, supplies, runes, planInputs);
    }

    private void cacheGearItem(int id)
    {
        GearNames.register(id,itemManager.getItemComposition(id).getName());
        net.runelite.client.game.ItemStats stats=itemManager.getItemStats(id);
        if(stats!=null && stats.getEquipment()!=null)
            GearNames.equipment(id,stats.getEquipment().getSlot(),stats.getEquipment().isTwoHanded());
    }

    private void cacheGearNames(Map<Integer,Integer> equipment)
    {
        java.util.Set<Integer> ids=new java.util.HashSet<>(panel.gearIds());
        if(equipment!=null)ids.addAll(equipment.keySet());
        boolean changed=false;
        for(int id:ids){int canonical=GearVariants.canonical(id);if(!GearNames.known(canonical)){cacheGearItem(canonical);changed=true;}}
        if(changed){HerbRunPlannerPanel target=panel;SwingUtilities.invokeLater(()->{if(active && panel==target)target.refreshGearLabels();});}
    }

    private void refreshSupplies()
    {
        PlanInputs old=lastPlanInputs;
        Map<Integer,Integer> inv=readCarried(InventoryID.INV),gear=readCarried(InventoryID.WORN);
        cacheGearNames(gear);
        Map<Integer,Integer> pouch=RuneSources.pouch(client,inv);
        int occupied=0;ItemContainer container=client.getItemContainer(InventoryID.INV);
        if(container==null)occupied=-1;
        else for(Item item:container.getItems())if(item!=null && item.getId()>0 && item.getQuantity()>0)occupied++;
        PlanInputs next=new PlanInputs(old.account,old.magic,old.farming,old.baseFarming,old.book,
            RuneEquipment.staffMask(gear),occupied,old.members,bankOpen,bankSnapshot.status(bankOpen),
            old.flags,inv,gear,pouch,bankSnapshot.items(),leprechaunItems)
            .withCompost(client.getVarbitValue(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_TYPE),client.getVarbitValue(VarbitID.FARMING_TOOLS_BOTTOMLESS_BUCKET_QUANTITY));
        next=next.withTeleportUses(observedUses.snapshot(client.getVarbitValue(VarbitID.LUMBRIDGE_CABBAGE_TELEPORT),next,
            java.time.LocalDate.now(java.time.ZoneOffset.UTC).toEpochDay()));
        lastPlanInputs=next;suppliesDirty=false;
        final PlanInputs captured=next;HerbRunPlannerPanel target=panel;
        SwingUtilities.invokeLater(()->{if(active && panel==target)target.updateSupplies(captured);});
    }

    private void updateLeprechaun()
    {
        Widget tools = client.getWidget(InterfaceID.FarmingTools.UNIVERSE);
        if (tools != null && !tools.isHidden()) leprechaunSeen = true;
        if (!leprechaunSeen) return;
        Map<Integer,Integer> next = null;
        try { next = LeprechaunStorage.read(client::getVarbitValue); }
        catch (RuntimeException ex) { /* Unreadable storage is unknown, never empty. */ }
        if (!java.util.Objects.equals(next, leprechaunItems))
        {
            leprechaunItems = next;
            dirty = true;
        }
    }

    private RunOverlayState runOverlayState()
    {
        if(!active || panel==null)return null;
        GameState state=client.getGameState();
        if(state!=GameState.LOGGED_IN && state!=GameState.LOADING)return null;
        RunOverlayState value=panel.runOverlayState();
        return value!=null && value.account==client.getAccountHash()?value:null;
    }

    private BankPreparation searchPreparation()
    {
        if(!active || panel==null || client.getGameState()!=GameState.LOGGED_IN || !isBankVisible())return null;
        BankPreparation state=panel.bankSearchPreparation();
        return state!=null && state.account==client.getAccountHash()?state:null;
    }

    @Subscribe(priority=-1)
    public void onScriptCallbackEvent(net.runelite.api.events.ScriptCallbackEvent event)
    {
        if(!active || !isBankVisible())return;
        BankPreparation prepared=searchPreparation();
        boolean toggle=prepared!=null && panel.showRunItems();
        int[] ints=client.getIntStack();int ni=client.getIntStackSize();
        String name=event.getEventName();
        if(toggle && ("getSearchingTagTab".equals(name) || "bankBuildTab".equals(name)))
        {
            // Use the native bank's virtual-search mode, with no chat/search text injection.
            if(ni>0)ints[ni-1]=1;
            return;
        }
        if(!"bankSearchFilter".equals(name))return;
        Object[] objects=client.getObjectStack();int no=client.getObjectStackSize();
        if(ni<2 || (!toggle && (no<1 || !HerbBankSearch.query(objects[no-1]))))return;
        ints[ni-2]=HerbBankSearch.includes(prepared,bankLayout.canonical(ints[ni-1]))?1:0;
    }

    @Subscribe(priority=-2)
    public void onScriptPreFired(net.runelite.api.events.ScriptPreFired event)
    {
        if(event.getScriptId()!=net.runelite.api.ScriptID.BANKMAIN_FINISHBUILDING || bankLayout==null)return;
        BankPreparation prepared=searchPreparation();
        if(prepared==null || !panel.showRunItems()){bankLayout.clear();return;}
        int height=bankLayout.layout(prepared);
        int n=client.getIntStackSize();
        if(height>0 && n>=9)client.getIntStack()[n-9]=height;
    }

    private void refreshHerbBankSearch()
    {
        BankPreparation prepared=searchPreparation();
        boolean toggle=prepared!=null && panel.showRunItems();
        java.util.Set<Integer> next=prepared==null?java.util.Collections.emptySet():prepared.items.keySet();
        boolean changed=toggle!=displayedRunFilter || !next.equals(displayedSearchItems);
        boolean enabling=toggle && !displayedRunFilter;
        displayedRunFilter=toggle;displayedSearchItems=new java.util.HashSet<>(next);
        if(changed && isBankVisible())
        {
            if(enabling)bankSearch.reset(true);
            else bankSearch.layoutBank();
        }
        if(bankHeaderButton!=null)bankHeaderButton.update(prepared!=null,toggle);
    }

    @Subscribe
    public void onMenuOptionClicked(net.runelite.api.events.MenuOptionClicked event)
    {
        if(active && automaticProgress!=null)automaticProgress.click(event);
        if(active)observedUses.click(event.getItemId(),event.getMenuOption(),client.getTickCount());
        BankPreparation prepared=searchPreparation();
        if(prepared==null || !panel.showRunItems())return;
        String option=event.getMenuOption(),menuTarget=event.getMenuTarget();
        if(menuTarget!=null && menuTarget.contains("Herb Run Planner"))return;
        if(option==null || !(option.startsWith("View tab") || option.startsWith("View tag tab") || option.equals("View all items")))return;
        HerbRunPlannerPanel target=panel;long account=prepared.account;
        SwingUtilities.invokeLater(()->{
            if(!active || target!=panel)return;
            target.setRunItemsFilter(account,false);
            clientThread.invokeLater(()->{if(active && target==panel)refreshHerbBankSearch();});
        });
    }

    private void toggleFromBank()
    {
        BankPreparation prepared=searchPreparation();if(prepared==null)return;
        HerbRunPlannerPanel target=panel;long account=prepared.account;
        SwingUtilities.invokeLater(()->{
            if(!active || target!=panel)return;
            target.toggleRunItems(account);
            clientThread.invokeLater(()->{if(active && target==panel)refreshHerbBankSearch();});
        });
    }

    private BankPreparation bankPreparation()
    {
        if(!active || panel==null || client.getGameState()!=GameState.LOGGED_IN || !isBankVisible())return null;
        BankPreparation value=panel.bankPreparation();
        return value!=null && value.account==client.getAccountHash()?value:null;
    }

    private boolean isBankVisible()
    {
        Widget bankItems = client.getWidget(InterfaceID.Bankmain.ITEMS);
        return bankItems != null && !bankItems.isHidden();
    }

    private void updateBank()
    {
        boolean visible = isBankVisible();
        if (visible != bankOpen)
        {
            bankOpen = visible;
            bankDirty = true;
            dirty = true;
        }
        if (visible && bankDirty) observeBank();
    }

    private void observeBank()
    {
        Map<Integer, Integer> items = readCarried(InventoryID.BANK);
        if (items != null)
        {
            bankSnapshot.observe(items, Instant.now());
            bankDirty = false;
            dirty = true;
        }
    }

    private Map<Integer, Integer> readCarried(int containerId)
    {
        ItemContainer container = client.getItemContainer(containerId);
        if (container == null)
        {
            dirty = true;
            return null;
        }
        Map<Integer, Integer> items = new LinkedHashMap<>();
        for (Item item : container.getItems())
        {
            if (item != null) CarriedSupplies.add(items, item.getId(), item.getQuantity());
        }
        return items;
    }

    private String readDiaries(Map<String, Boolean> flags)
    {
        StringBuilder text = new StringBuilder("Diary task completion. Reward collection, item ownership and daily teleport charges are not verified here.\n\n");
        readDiary(text, flags, "Morytania Easy", VarbitID.MORYTANIA_DIARY_EASY_COMPLETE);
        readDiary(text, flags, "Morytania Medium", VarbitID.MORYTANIA_DIARY_MEDIUM_COMPLETE);
        readDiary(text, flags, "Morytania Hard", VarbitID.MORYTANIA_DIARY_HARD_COMPLETE);
        readDiary(text, flags, "Morytania Elite", VarbitID.MORYTANIA_DIARY_ELITE_COMPLETE);
        readDiary(text, flags, "Ardougne Easy", VarbitID.ARDOUGNE_DIARY_EASY_COMPLETE);
        readDiary(text, flags, "Ardougne Medium", VarbitID.ARDOUGNE_DIARY_MEDIUM_COMPLETE);
        readDiary(text, flags, "Ardougne Hard", VarbitID.ARDOUGNE_DIARY_HARD_COMPLETE);
        readDiary(text, flags, "Ardougne Elite", VarbitID.ARDOUGNE_DIARY_ELITE_COMPLETE);
        readDiary(text, flags, "Lumbridge Easy", VarbitID.LUMBRIDGE_DIARY_EASY_COMPLETE);
        readDiary(text, flags, "Lumbridge Medium", VarbitID.LUMBRIDGE_DIARY_MEDIUM_COMPLETE);
        readDiary(text, flags, "Lumbridge Hard", VarbitID.LUMBRIDGE_DIARY_HARD_COMPLETE);
        readDiary(text, flags, "Lumbridge Elite", VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE);
        readDiary(text, flags, "Kourend Easy", VarbitID.KOUREND_DIARY_EASY_COMPLETE);
        readDiary(text, flags, "Kourend Medium", VarbitID.KOUREND_DIARY_MEDIUM_COMPLETE);
        readDiary(text, flags, "Kourend Hard", VarbitID.KOUREND_DIARY_HARD_COMPLETE);
        readDiary(text, flags, "Kourend Elite", VarbitID.KOUREND_DIARY_ELITE_COMPLETE);
        return text.toString();
    }

    private void readDiary(StringBuilder text, Map<String, Boolean> flags, String name, int varbit)
    {
        Boolean complete = null;
        try
        {
            int value = client.getVarbitValue(varbit);
            if (value == 0 || value == 1)
            {
                complete = value == 1;
                flags.put(name, complete);
            }
        }
        catch (RuntimeException ex)
        {
            dirty = true;
        }
        text.append(name).append(": ").append(complete == null ? "Unknown"
            : complete ? "Tasks complete" : "Tasks incomplete").append("\n");
    }

    private void clearSession()
    {
        observedUses.clear();
        if(automaticProgress!=null)automaticProgress.clear();
        travelTimer.clear();displayedTiming="";
        if(panel!=null){HerbRunPlannerPanel target=panel;SwingUtilities.invokeLater(()->target.timingText("No travel samples this login."));}

        if(bankHeaderButton!=null)bankHeaderButton.update(false,false);
        if(bankLayout!=null)bankLayout.clear();
        if(walkingGuide!=null)walkingGuide.clear();
            if(navigationOverlay!=null)navigationOverlay.clear();
        displayedRunFilter=false;displayedSearchItems=java.util.Collections.emptySet();
        questStates.clear();
        bankSnapshot.clear();
        leprechaunItems = null;
        leprechaunSeen = false;
        lastPlanInputs=null;suppliesDirty=false;
        bankOpen = false;
        bankDirty = true;
        lastAccount = -1;
        ticksSinceRead = 0;
        dirty = true;
        publish("Waiting for account data. Log in and allow a few game ticks.", "", "", "", "", "", "", "", null);
    }

    private void publish(String summary, String levels, String quests, String patches, String diaries, String teleports, String supplies, String runes, PlanInputs planInputs)
    {
        HerbRunPlannerPanel target = panel;
        String character=planInputs!=null && client.getLocalPlayer()!=null?client.getLocalPlayer().getName():null;
        SwingUtilities.invokeLater(() -> {
            if (active && target == panel)
            {
                target.update(summary, levels, quests, patches, diaries, teleports, supplies, runes, planInputs);
                if(character!=null)target.characterName(planInputs.account,character);
            }
        });
    }
}

package com.herbrunplanner;

import java.util.*;

/** Immutable rendering snapshot; progress remains owned by the Swing panel. */
final class RunOverlayState
{
    final long account;
    final String heading,next;
    final List<String> instructions;
    final boolean complete;
    final TravelIcon icon;
    RunOverlayState(long account,RunProgress run)
    {
        this.account=account;complete=run.complete();
        if(complete)
        {
            icon=null;
            heading="Run checklist complete";next="";
            instructions=Collections.singletonList("Done: "+run.count(RunProgress.State.DONE)+" · Skipped: "+run.count(RunProgress.State.SKIPPED));
        }
        else
        {
            RunProgress.Step step=run.current();
            PlanCatalog.Travel method=step.bank?run.choices.bankReturn.travel:run.choices.patches.get(step.patch);
            if(method!=null && ExtendedTravel.house(method))method=ExtendedTravel.entry(method,run.choices);
            icon=TravelIcon.of(method,run.supplies);
            int patches=0;for(RunProgress.Step s:run.steps)if(!s.bank)patches++;
            heading=step.bank?"Bank return":step.title+" · "+(run.index()+1)+" of "+patches;
            instructions=Collections.unmodifiableList(Arrays.asList(step.travel.split("\n")));
            next=run.index()+1<run.steps.size()?"Next: "+run.steps.get(run.index()+1).title:"Last stop";
        }
    }
}

