import net.runelite.client.ui.overlay.*;
import net.runelite.client.ui.overlay.components.ImageComponent;
import net.runelite.client.ui.overlay.tooltip.*;

/** Read-only travel instructions driven by the manual sidebar checklist. */
final class HerbRunOverlay extends OverlayPanel
{
    private final Supplier<RunOverlayState> source;
    private final Client client;
    private final ItemManager items;
    private final SpriteManager sprites;
    private final TooltipManager tooltips;
    HerbRunOverlay(Supplier<RunOverlayState> source,Client client,ItemManager items,SpriteManager sprites,TooltipManager tooltips)
    {
        this.source=source;this.client=client;this.items=items;this.sprites=sprites;this.tooltips=tooltips;
        setPosition(OverlayPosition.TOP_LEFT);setLayer(OverlayLayer.ABOVE_WIDGETS);
        HerbOverlayStyle.configure(panelComponent);
    }
    @Override public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();
        RunOverlayState state=source.get();if(state==null)return null;
        HerbOverlayStyle.heading(panelComponent,state.complete?"Complete":"Your run");
        line(state.heading,Color.WHITE);
        BufferedImage image=state.icon==null?null:state.icon.item>0?items.getImage(state.icon.item):sprites.getSprite(state.icon.sprite,0);
        ImageComponent icon=image==null?null:new ImageComponent(image);
        if(icon!=null)panelComponent.getChildren().add(icon);
        // Retain the label if an icon is unavailable, and keep multi-hop directions.
        for(int i=icon==null?0:1;i<state.instructions.size();i++)
            line(state.instructions.get(i),i==0?HerbOverlayStyle.ACCENT:HerbOverlayStyle.MUTED);
        if(!state.next.isEmpty())line(state.next,HerbOverlayStyle.MUTED);
        line(state.complete?"Prepare another run in sidebar":"Mark progress in Your run",HerbOverlayStyle.MUTED);
        Dimension size=super.render(graphics);
        if(icon!=null)
        {
            net.runelite.api.Point mouse=client.getMouseCanvasPosition();
            Point relative=new Point(mouse.getX()-getBounds().x,mouse.getY()-getBounds().y);
            if(icon.getBounds().contains(relative))tooltips.add(new Tooltip(state.icon.label));
        }
        return size;
    }
    private void line(String text,Color color)
    {HerbOverlayStyle.line(panelComponent,text,color);}
}

package com.herbrunplanner;

import java.util.*;
import net.runelite.api.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.EnumID;

public final class RuneSources
{
    private RuneSources() {}
    public static Map<Integer,Integer> pouch(Client client,Map<Integer,Integer> inv)
    {
        if(inv==null) return null;
        if(!RuneEquipment.hasPouch(inv)) return Collections.emptyMap();
        int[] types={VarbitID.RUNE_POUCH_TYPE_1,VarbitID.RUNE_POUCH_TYPE_2,VarbitID.RUNE_POUCH_TYPE_3,
            VarbitID.RUNE_POUCH_TYPE_4,VarbitID.RUNE_POUCH_TYPE_5,VarbitID.RUNE_POUCH_TYPE_6};
        int[] amounts={VarbitID.RUNE_POUCH_QUANTITY_1,VarbitID.RUNE_POUCH_QUANTITY_2,VarbitID.RUNE_POUCH_QUANTITY_3,
            VarbitID.RUNE_POUCH_QUANTITY_4,VarbitID.RUNE_POUCH_QUANTITY_5,VarbitID.RUNE_POUCH_QUANTITY_6};
        try
        {
            EnumComposition mapping=client.getEnum(EnumID.RUNEPOUCH_RUNE);
            if(mapping==null) return null;
            Map<Integer,Integer> result=new LinkedHashMap<>();
            for(int i=0;i<types.length;i++)
            {
                int type=client.getVarbitValue(types[i]), amount=client.getVarbitValue(amounts[i]);
                if(type==0 && amount==0) continue;
                if(type<=0 || amount<0) return null;
                int id=mapping.getIntValue(type);
                if(id<=0) return null;
                if(amount>0) result.merge(id,amount,Integer::sum);
            }
            return result;
        }
        catch(RuntimeException ex) { return null; }
    }
}

package com.herbrunplanner;

import java.util.*;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/** Read-only decoder matching the game's farming_tools_getstored client script. */
final class LeprechaunStorage
{
    private LeprechaunStorage() {}
    static Map<Integer,Integer> read(IntUnaryOperator value)
    {
        Map<Integer,Integer> items=new LinkedHashMap<>();
        items.put(ItemID.RAKE,combined(value,VarbitID.FARMING_TOOLS_RAKE,VarbitID.FARMING_TOOLS_EXTRARAKES,2));
        items.put(ItemID.DIBBER,combined(value,VarbitID.FARMING_TOOLS_DIBBER,VarbitID.FARMING_TOOLS_EXTRADIBBERS,2));
        items.put(ItemID.SPADE,combined(value,VarbitID.FARMING_TOOLS_SPADE,VarbitID.FARMING_TOOLS_EXTRASPADES,2));
        int secateurs=combined(value,VarbitID.FARMING_TOOLS_SECATEURS,VarbitID.FARMING_TOOLS_EXTRASECATEURS,2);
        int magic=checked(value.applyAsInt(VarbitID.FARMING_TOOLS_FAIRYSECATEURS));
        if(magic>1)throw new IllegalArgumentException("Unknown secateurs type");
        items.put(ItemID.FAIRY_ENCHANTED_SECATEURS,magic==1?secateurs:0);
        items.put(ItemID.BUCKET_COMPOST,combined(value,VarbitID.FARMING_TOOLS_COMPOST,VarbitID.FARMING_TOOLS_EXTRACOMPOST,256));
        items.put(ItemID.BUCKET_SUPERCOMPOST,combined(value,VarbitID.FARMING_TOOLS_SUPERCOMPOST,VarbitID.FARMING_TOOLS_EXTRASUPERCOMPOST,256));
        items.put(ItemID.BUCKET_ULTRACOMPOST,checked(value.applyAsInt(VarbitID.FARMING_TOOLS_ULTRACOMPOST)));
        return Collections.unmodifiableMap(items);
    }
    private static int checked(int n){if(n<0)throw new IllegalArgumentException("Unknown storage value");return n;}
    private static int combined(IntUnaryOperator value,int low,int high,int multiplier)
    {
        long n=checked(value.applyAsInt(low))+(long)multiplier*checked(value.applyAsInt(high));
        if(n>Integer.MAX_VALUE)throw new IllegalArgumentException("Storage value overflow");
        return (int)n;
    }
    static boolean supports(int id)
    {return id==ItemID.RAKE || id==ItemID.DIBBER || id==ItemID.SPADE || id==ItemID.FAIRY_ENCHANTED_SECATEURS
        || id==ItemID.BUCKET_COMPOST || id==ItemID.BUCKET_SUPERCOMPOST || id==ItemID.BUCKET_ULTRACOMPOST;}
    static String status(Map<Integer,Integer> items)
    {return items==null?"Tool leprechaun: unknown — open its storage once this login to check compost and tools."
        :"Tool leprechaun: observed this login. Collect allocated supplies from a leprechaun, not the bank.";}
    static String describe(Map<Integer,Integer> items)
    {
        StringBuilder out=new StringBuilder(status(items));
        if(items!=null)items.forEach((id,n)->out.append('\n').append(PlanCatalog.name(id)).append(": ").append(n));
        return out.toString();
    }
}

package com.herbrunplanner;

import java.util.*;

public final class AdvancedRuneSupplies
{
    private AdvancedRuneSupplies() {}
    static Map<Integer,Integer> merge(Map<Integer,Integer> inv,Map<Integer,Integer> pouch)
    {
        Map<Integer,Integer> result=new LinkedHashMap<>();
        for(Map<Integer,Integer> source:Arrays.asList(inv,pouch)) if(source!=null)
            source.forEach((id,n)-> { if(n>0) result.merge(id,n,(a,b)->(int)Math.min(Integer.MAX_VALUE,(long)a+b)); });
        return result;
    }
    public static String render(Map<Integer,Integer> inv,Map<Integer,Integer> pouch,
        int staffMask,boolean equipmentKnown,Map<Integer,Integer> bank,String bankStatus)
    {
        Map<Integer,Integer> carried=merge(inv,pouch);
        boolean known=inv!=null && pouch!=null && equipmentKnown;
        StringBuilder t=new StringBuilder("Rune supplies — one cast per spell\n\n").append(bankStatus)
            .append("\n\nInventory + carried pouch + supported equipped staves + combination runes. Quest, Magic, spellbook and location checks remain separate. Banked pouches/staves and other rune-providing equipment are not counted.\n\n");
        t.append("Pouch: ").append(pouch==null?"Unknown":pouch.isEmpty()?"No rune contents counted (absent or empty)":describe(pouch)).append("\n");
        t.append("Equipped staff coverage: ");
        if(!equipmentKnown) t.append("Unknown");
        else if(staffMask==0) t.append("None from supported staff types");
        else for(int i=1;i<=4;i++) if((staffMask&(1<<i))!=0) t.append(RuneSupplies.NAMES[i]).append(" unlimited; ");
        if(!known) t.append("\nSome sources are unknown; displayed shortfalls are provisional.");
        t.append("\n\nCounted carried rune stacks: ").append(describe(carried));
        t.append("\n\nIndependent alternatives; not totals for a full run. Bank suggestions use last-observed quantities.\n\n");
        for(int s=0;s<RuneSupplies.SPELLS.length;s++)
        {
            t.append(RuneSupplies.SPELLS[s]).append(" — ");
            RuneAllocation.Result carriedResult=RuneAllocation.solve(RuneSupplies.COSTS[s],carried,null,staffMask);
            if(carriedResult.deficit()==0) t.append("Counted carried sources cover 1 cast.");
            else
            {
                RuneAllocation.Result result=RuneAllocation.solve(RuneSupplies.COSTS[s],carried,bank,staffMask);
                if(!known) t.append("Unknown sources may cover the shortfall. ");
                if(bank==null) t.append("Bank unknown. ");
                else if(result.deficit()==0) t.append("Observed bank can cover the shortfall. ");
                if(!result.withdraw.isEmpty()) t.append("Withdraw (if still needed): ").append(describe(result.withdraw)).append(". ");
                if(result.deficit()>0)
                {
                    t.append("Still short in counted sources: ");
                    for(int i=0;i<result.remaining.length;i++) if(result.remaining[i]>0)
                        t.append(result.remaining[i]).append(" ").append(RuneSupplies.NAMES[i]).append("; ");
                }
            }
            t.append("\n\n");
        }
        return t.toString();
    }
    private static String describe(Map<Integer,Integer> items)
    {
        List<String> parts=new ArrayList<>();
        for(Map.Entry<Integer,Integer> item:items.entrySet())
        {
            String name=RuneAllocation.name(item.getKey());
            if(!name.equals("Unmapped rune") && item.getValue()>0) parts.add(item.getValue()+" "+name);
        }
        return parts.isEmpty()?"None relevant to these spells":String.join(", ",parts);
    }
}

