    BiConsumer<Integer,Consumer<Integer>> search=(slot,done)->{};
    GearSetPanel(BiConsumer<Integer,JLabel> icons,BooleanSupplier editable,Supplier<Map<Integer,Integer>> worn,Runnable changed)
