            if(sets.outfits.isEmpty())sets.add("My gear");else sets.selected=sets.outfits.keySet().iterator().next();commit();});
        list.addActionListener(e->{if(updating)return;if(!editable.getAsBoolean()){refresh();return;}GearSets.Outfit o=(GearSets.Outfit)list.getSelectedItem();if(o!=null){sets.selected=o.id;commit();}});
