            String tooltip=NAMES.get(slot)+(item>0?": "+GearNames.name(item):"");cell.setToolTipText(tooltip);icon.setToolTipText(tooltip);
            JPopupMenu menu=new JPopupMenu();JMenuItem find=new JMenuItem("Search item"),copy=new JMenuItem("Copy currently worn slot"),clear=new JMenuItem("Clear slot");menu.add(find);menu.add(copy);menu.add(clear);
            Runnable findItem=()->{if(!editable.getAsBoolean())return;GearSets owner=sets;GearSets.Outfit outfit=sets.current();
                search.accept(slot,id->{if(sets!=owner || sets.current()!=outfit || !editable.getAsBoolean())return;if(GearNames.slot(id)!=slot){message.setText("Choose an item for "+NAMES.get(slot)+".");return;}message.setText(" ");put(slot,id);});};
            find.addActionListener(e->findItem.run());copy.addActionListener(e->{if(editable.getAsBoolean())put(slot,worn.get().keySet().stream().map(GearVariants::canonical).filter(id->GearNames.slot(id)==slot).findFirst().orElse(-1));});
            clear.addActionListener(e->{if(editable.getAsBoolean())put(slot,-1);});
            cell.setComponentPopupMenu(menu);icon.setComponentPopupMenu(menu);
            java.awt.event.MouseAdapter mouse=new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){if(SwingUtilities.isLeftMouseButton(e))findItem.run();}};
            cell.addMouseListener(mouse);icon.addMouseListener(mouse);grid.add(cell);
        }
        for(int id:sets.current().items)if(!NAMES.containsKey(GearNames.slot(id)))
        {
            JButton unknown=new JButton(GearNames.name(id)+" · Remove");unknown.addActionListener(e->{if(editable.getAsBoolean()){sets.current().items.remove(id);commit();}});extras.add(unknown);
        }
        revalidate();repaint();
    }
}

package com.herbrunplanner;

import java.util.*;

/** Opt-in session measurements. A large displacement is only a candidate teleport. */
final class TravelTimer
{
    static final class Request
    {
        final long account;
        final PlanCatalog.Patch patch;
        final PlanCatalog.Travel method;
        final WalkRequest walk;
        Request(long account,PlanCatalog.Patch patch,PlanCatalog.Travel method)
        {this.account=account;this.patch=patch;this.method=method;walk=new WalkRequest(account,patch);}
    }
    private Request current;
    private long account=Long.MIN_VALUE,lastTime,start;
    private int x,y;
    private boolean previous,measuring,finished;
    private String status="Enable travel timing in Advanced settings, then start a run.";
    private final Deque<String> samples=new ArrayDeque<>();
    void clear(){current=null;account=Long.MIN_VALUE;previous=false;measuring=false;finished=false;samples.clear();status="No travel samples this login.";}
    void tick(Request request,int px,int py,int p,long now,boolean atPatch,boolean supported)
    {
        if(request==null){current=null;previous=false;measuring=false;status="Timer off or no active patch.";return;}
        if(account!=request.account){clear();account=request.account;}
        if(current!=request){current=request;previous=false;measuring=false;finished=false;status="Waiting for a candidate teleport to "+request.patch.label+".";}
        if(!supported || request.method==PlanCatalog.Travel.MANUAL || request.method==PlanCatalog.Travel.AUTO)
        {previous=false;measuring=false;status="Timing unavailable for this area or manual travel.";return;}
        if(finished)return;
        long gap=now-lastTime;
        if(previous && (gap<0 || gap>15_000))
        {previous=false;measuring=false;status="Sample discarded: observation gap.";}
        if(previous && Math.max(Math.abs(px-x),Math.abs(py-y))>=16)
        {
            if(measuring){measuring=false;finished=true;status="Sample discarded: another large movement.";}
            else {measuring=true;start=now;status="Measuring approach to "+request.patch.label+" (candidate teleport).";}
        }
        if(measuring && now-start>180_000){measuring=false;finished=true;status="Sample discarded: approach exceeded three minutes.";}
        if(measuring && atPatch)
        {
            long elapsed=Math.max(0,now-start);
            samples.addFirst(request.patch.label+" · "+request.method.label+"\n"+String.format(Locale.ROOT,"%.1f",elapsed/1000d)+" sec approach — candidate sample; confirm the teleport used.");
            while(samples.size()>20)samples.removeLast();
            measuring=false;finished=true;status="Approach recorded at detected herb-patch edge.";
        }
        x=px;y=py;lastTime=now;previous=true;
    }
    String describe()
    {
        return status+"\n\nSession samples (up to 20)\nTeleport animation before arrival is excluded. Pauses and walking are included. Tick sampling is approximate. Large movement does not prove which teleport was used. Samples do not change route estimates.\n\n"+String.join("\n\n",samples);
    }
}

package com.herbrunplanner;

import net.runelite.api.gameval.ItemID;

/** Charges are applications, not buckets: never double the observed quantity. */
final class BottomlessCompost
{
    static boolean owned(PlanInputs in)
    {return PlanInputs.count(in.inventory,ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED)>0
        || PlanInputs.count(in.bank,ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED)>0;}
    static int available(PlanInputs in,PlanCatalog.Compost selected)
    {
        int type=selected==PlanCatalog.Compost.NORMAL?1:selected==PlanCatalog.Compost.SUPER?2:selected==PlanCatalog.Compost.ULTRA?3:-1;
        return owned(in) && type>0 && in.compostType==type && in.compostApplications>=0 && in.compostApplications<=10000
            ?in.compostApplications:0;
    }
}

package com.herbrunplanner;

import java.util.*;
import static com.herbrunplanner.PlanCatalog.*;

/** Manual checklist progress. No client reads or gameplay actions. */
final class RunProgress
{
    enum State { PENDING, DONE, SKIPPED }
    static final class Step
    {
        final String title,travel;
        final boolean bank;
        final Patch patch;
        Step(String title,String travel,boolean bank,Patch patch){this.title=title;this.travel=travel;this.bank=bank;this.patch=patch;}
    }
    final List<Step> steps;
    final PlanInputs.Choices choices;
    final List<PlanEngine.Supply> supplies;
    private final State[] states;
    private int index;
    RunProgress(PlanInputs.Choices choices)
    {this(choices,Collections.emptyList());}
    RunProgress(PlanInputs.Choices choices,List<PlanEngine.Supply> supplies)
    {
        this.choices=choices;this.supplies=Collections.unmodifiableList(new ArrayList<>(supplies));
        List<Step> list=new ArrayList<>();
        for(Patch patch:choices.order)
        {
            Travel method=choices.patches.get(patch);
            String travel=ExtendedTravel.instructions(method,choices);
            if(method==Travel.SKILLS)travel+="\nDestination: "+(patch==Patch.GUILD?"Farming Guild":patch==Patch.HOSIDIUS?"Woodcutting Guild entrance":"Fishing Guild");
            if(method.item>0 || method==Travel.COMBAT || method==Travel.SKILLS)travel+="\nWalk from arrival to the patch.";
            if(method==Travel.ECTO)travel+="\nAllow the ectophial to refill before leaving.";
            list.add(new Step(patch.label,travel,false,patch));
        }
        if(list.isEmpty())throw new IllegalArgumentException("A run needs a patch");
        if(choices.bankReturn!=ReturnToBank.FINISH)list.add(new Step("Bank return",choices.bankReturn.travel==null?choices.bankReturn.label:ExtendedTravel.instructions(choices.bankReturn.travel,choices)+"\nContinue to the bank.",true,null));
        steps=Collections.unmodifiableList(list);states=new State[steps.size()];Arrays.fill(states,State.PENDING);
    }
    int index(){return index;}
    boolean complete(){return index==steps.size();}
    Step current(){return complete()?null:steps.get(index);}
    State state(int step){return states[step];}
    void advance(boolean skipped){if(!complete())states[index++]=skipped?State.SKIPPED:State.DONE;}
    void back(){if(index>0)states[--index]=State.PENDING;}
    int count(State state){int count=0;for(State s:states)if(s==state)count++;return count;}
}

package com.herbrunplanner;

import java.util.*;

/** Versioned explicit text values only; no game state or Java serialization. */
final class RunPreferences
{
    interface Store {String load(long account);void save(long account,String value);}
    static final Store NONE=new Store(){public String load(long account){return null;}public void save(long account,String value){}};
    final Map<String,String> values=new TreeMap<>();
    static RunPreferences decode(String text)
    {
        RunPreferences p=new RunPreferences();
        if(text==null || !text.startsWith("v1\n"))return p;
        for(String line:text.substring(3).split("\n"))
        {
            int eq=line.indexOf('=');
            if(eq>0 && line.length()<120)p.values.put(line.substring(0,eq),line.substring(eq+1));
        }
        return p;
    }
    String encode(){StringBuilder s=new StringBuilder("v1\n");values.forEach((k,v)->s.append(k).append('=').append(v).append('\n'));return s.toString();}
    boolean flag(String key,boolean fallback)
    {String s=values.get(key);return "true".equals(s)?true:"false".equals(s)?false:fallback;}
    <T extends Enum<T>> T option(String key,T fallback)
    {try{return Enum.valueOf(fallback.getDeclaringClass(),values.get(key));}catch(IllegalArgumentException|NullPointerException e){return fallback;}}
    void put(String key,Object value){values.put(key,String.valueOf(value));}
}

package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;
import static com.herbrunplanner.PlanCatalog.*;

/** Pure, advisory plan generation. No client access or game actions. */
public final class PlanEngine
{
    private final PlanInputs input;
    private final PlanInputs.Choices choice;
    private final Set<Integer> travelItems=new HashSet<>();
    private final Map<Integer,Integer> required = new LinkedHashMap<>();
    private final Map<Integer,Integer> runeCarried, runeBank;
    private final Set<Travel> hypotheticalCharges=EnumSet.noneOf(Travel.class);
    private final Map<Travel,Integer> usesSpent=new EnumMap<>(Travel.class);
    private final Map<Travel,Integer> chargesLeft = new EnumMap<>(Travel.class);
    private final Set<String> notes = new LinkedHashSet<>();
    private final StringBuilder route = new StringBuilder();
    private boolean unresolved;
    private boolean usesSpell,equipStaffRequired;
    private int blockedSteps,manualSteps,unconfirmedSteps;
    private final EnumMap<Patch,Travel> resolvedMethods=new EnumMap<>(Patch.class);
    private ReturnToBank resolvedReturn;
    private final List<Supply> supplies = new ArrayList<>();
    private final Set<String> problems = new LinkedHashSet<>();
    private String readiness = "REVIEW NEEDED";
    public static final class Supply
    {
        final int id, need, have, bank, withdraw, missing, leprechaun, collect;
        final boolean storageUnknown;
        Supply(int id,int need,int have,int bank,int withdraw,int missing,int leprechaun,int collect,boolean storageUnknown)
        {this.id=id;this.need=need;this.have=have;this.bank=bank;this.withdraw=withdraw;this.missing=missing;this.leprechaun=leprechaun;this.collect=collect;this.storageUnknown=storageUnknown;}
    }
    public static final class Report
    {
        final String status, route, detail;
        final PlanInputs.Choices resolvedChoices;
        final int blockedSteps,manualSteps,unconfirmedSteps;
        final List<Supply> supplies,obtain;
        final int travelShortfall;
        final List<String> problems;
        final boolean equipStaffRequired;
        Report(PlanEngine e,String detail)
        {
            equipStaffRequired=e.equipStaffRequired;
            blockedSteps=e.blockedSteps;manualSteps=e.manualSteps;unconfirmedSteps=e.unconfirmedSteps;
            PlanInputs.Choices c=e.choice;
            resolvedChoices=new PlanInputs.Choices(c.herb,e.resolvedMethods.isEmpty()?c.patches:e.resolvedMethods,
                e.resolvedReturn==null?c.bankReturn:e.resolvedReturn,c.compost,c.weiss,c.harmony,c.charges,c.manualCompost,c.rake,e.input.hasMagicSecateurs(),c.includeObtain).withTransport(c.travelChecks,c.houseEntry).withExternalNetworks(c.externalNetworks).withOrder(c.order);
            status=e.readiness;route=e.route.toString();this.detail=detail+"\n\n"+TravelTime.summary(resolvedChoices);
            supplies=Collections.unmodifiableList(new ArrayList<>(e.supplies));
            List<Supply> missing=new ArrayList<>();int shortfall=0;
            for(Supply s:supplies)if(e.travelItems.contains(s.id) && s.missing>0){missing.add(s);shortfall+=s.missing;}
            obtain=Collections.unmodifiableList(missing);travelShortfall=shortfall;
            problems=Collections.unmodifiableList(new ArrayList<>(e.problems));
        }
    }
    public static Report report(PlanInputs input,PlanInputs.Choices choice)
    {return AutoTravelPlanner.choose(input,choice);}
    static Report evaluate(PlanInputs input,PlanInputs.Choices choice)
    {
        PlanEngine engine=new PlanEngine(input,choice);
        String detail=engine.build();
        if(engine.supplies.isEmpty())engine.problems.add(detail);
        return new Report(engine,detail);
    }
    static String unavailable(PlanInputs input,Travel t)
    {
        List<String> reasons=new ArrayList<>();
        if(!input.knownGate(t.gate))reasons.add("Requirement not confirmed: "+t.gate.replace('_',' '));
        if(t.spell>=0)
        {
            if(input.magic<t.level)reasons.add("Needs "+t.level+" Magic (current "+input.magic+")");
            if(input.book!=t.book)reasons.add("Needs "+TeleportEligibility.bookName(t.book)+" spellbook");
        }
        return String.join("; ",reasons);
    }
    static String unavailable(PlanInputs input,Travel t,PlanInputs.Choices choice)
    {
        String base=unavailable(input,t),extra=ExtendedTravel.unavailable(input,t,choice);
        if(TeleportUses.remaining(input,t)==0)extra+=(extra.isEmpty()?"":"; ")+t.label+": no teleport uses remaining";
        return base.isEmpty()?extra:extra.isEmpty()?base:base+"; "+extra;
    }
    private PlanEngine(PlanInputs input, PlanInputs.Choices choice)
    {
        this.input=input; this.choice=choice;
        runeCarried=new LinkedHashMap<>(PlanInputs.sum(input.inventory,input.pouch));
        runeBank=new LinkedHashMap<>(input.bank==null?Collections.emptyMap():input.bank);
    }
    public static String build(PlanInputs input, PlanInputs.Choices choice)
    { return report(input,choice).detail; }

    private String build()
    {
        if(choice.patches.isEmpty()) return "Select at least one patch, then update the plan.";
        if(!input.members) return "A members world is required for this plan.";
        if(input.farming<choice.herb.level) return "Cannot plan "+choice.herb.name+": needs "+choice.herb.level+" current Farming.";
        for(Patch p:choice.patches.keySet())
        {
            if(!input.patchGate(p))return p.label+": access requirement is not confirmed. Deselect this patch or refresh account data.";
            if(p==Patch.WEISS && !choice.weiss)return "Confirm that the Weiss Fire of Nourishment is built, or deselect Weiss.";
            if(p==Patch.HARMONY && !choice.harmony)return "Confirm that the Morytania elite reward is claimed, or deselect Harmony Island.";
        }
        if(input.baseFarming<choice.herb.level || (choice.patches.containsKey(Patch.GUILD) && input.baseFarming<65))
            warn("This plan depends on a Farming boost. Maintain it when planting or entering the guild.","Keep your Farming boost active for planting and Guild entry.");
        if(input.bank==null)warn("Open your bank to check travel supplies, then Prepare run again. Unseen bank items are not treated as owned.","Open your bank, then prepare the run again.");
        if(input.inventory==null || input.equipment==null || input.pouch==null)
            warn("Some carried sources are unknown. Refresh before relying on quantities.","Refresh account details to check your inventory and equipment.");
        add(choice.herb.id,choice.patches.size());
        add(ItemID.SPADE,1); add(ItemID.DIBBER,1);
        if(choice.rake)add(ItemID.RAKE,1);
        if(input.hasMagicSecateurs())add(ItemID.FAIRY_ENCHANTED_SECATEURS,1);
        if(choice.compost.id>0)
        {
            int applications=BottomlessCompost.available(input,choice.compost);
            int used=Math.min(choice.patches.size(),applications);
            if(used>0)
            {
                add(ItemID.BOTTOMLESS_COMPOST_BUCKET_FILLED,1);
                notes.add("Bottomless bucket: "+used+" applications allocated; "+applications+" available.");
            }
            if(used<choice.patches.size())add(choice.compost.id,choice.patches.size()-used);
            if(BottomlessCompost.owned(input) && input.compostType<0)
                notes.add("Check your bottomless bucket in game to detect its compost type and applications.");
        }
        else if(!choice.manualCompost)warn("Confirm your own compost setup has "+choice.patches.size()+" applications ready.");
        else notes.add("Own compost setup: "+choice.patches.size()+" applications confirmed manually; contents are not detected.");
        int number=0; Patch last=null;
        for(Patch patch:choice.order)
        {
            last=patch;
            Travel method=choice.patches.get(patch);
            if(method==Travel.AUTO)method=suggest(patch.methods);
            resolvedMethods.put(patch,method);
            boolean shortTravel=method!=Travel.MANUAL && unlocked(method) && !stocked(method);
            if(shortTravel)warn(patch.label+": travel needs setup — supplies for "+method.label+" are missing or unverified.",patch.label+": get supplies for "+method.label+" or change teleport.");
            route.append(++number).append(". ").append(patch.label).append("\n   ").append(method==Travel.MANUAL?"Travel needs setup (manual)":shortTravel?"Travel needs setup — "+ExtendedTravel.instructions(method,choice):unlocked(method)?ExtendedTravel.instructions(method,choice):"BLOCKED — "+method.label).append('\n');
            use(method);
            if(method==Travel.MANUAL)
            {
                String explanation=patch.label+": "+fallback(patch);
                notes.add(explanation);
                warn(patch.methods.length<=2?explanation:patch.label+": manual travel selected. See the detailed checklist for supported alternatives and missing requirements.",manualAction(patch));
            }
            if(method.item>0 || method==Travel.COMBAT)route.append("   Walk from arrival point to patch.\n");
            if(method==Travel.SKILLS)route.append("   Destination: ").append(patch==Patch.GUILD?"Farming Guild":patch==Patch.HOSIDIUS?"Woodcutting Guild entrance; walk to patch":"Fishing Guild; walk to patch").append('\n');
            if(method==Travel.ECTO)notes.add("Allow the ectophial to refill after teleporting.");
        }
        ReturnToBank bankReturn=choice.bankReturn;
        if(bankReturn==ReturnToBank.AUTO)
        {
            if(last==Patch.CATHERBY)bankReturn=ReturnToBank.WALK;
            else if(last==Patch.GUILD)bankReturn=ReturnToBank.GUILD_WALK;
            else
            {
                Travel best=suggest(Arrays.stream(ReturnToBank.values()).filter(b->b.travel!=null).map(b->b.travel).toArray(Travel[]::new));
                bankReturn=ReturnToBank.MANUAL;
                for(ReturnToBank b:ReturnToBank.values())if(b.travel==best){bankReturn=b;break;}
            }
        }
        resolvedReturn=bankReturn;
        if(bankReturn!=ReturnToBank.FINISH) route.append(++number).append(". Bank return\n   ").append(bankReturn.travel==null?bankReturn.label:ExtendedTravel.instructions(bankReturn.travel,choice)+"\n   Continue to the bank.").append('\n');
        if(bankReturn.travel!=null)
        {
            if(!stocked(bankReturn.travel))warn("Bank return: travel needs setup — verify supplies for "+bankReturn.travel.label+".","Bank return: check supplies for "+bankReturn.travel.label+".");
            use(bankReturn.travel);
        }
        else switch(bankReturn)
        {
            case FINISH:route.append("Finish at ").append(last.label).append(".\n");break;
            case GUILD_WALK:if(last!=Patch.GUILD){blockedSteps++;warn("Walk-to-Guild return requires Farming Guild as the last selected patch.");}break;
            case WALK:if(last!=Patch.CATHERBY){blockedSteps++;warn("Walk-to-Catherby return requires Catherby as the last selected patch.");}break;
            default:manualSteps++;warn("Bank return: travel needs setup. No automatic return with counted supplies; choose a supported owned option or arrange manual travel.","Choose a bank-return method or finish at the last patch.");
        }
        for(int id:input.gear)if(id>0)required.merge(id,1,Math::max);
        StringBuilder checklist=new StringBuilder();
        int extraSlots=0,missingTotal=0,withdrawTotal=0;
        for(Map.Entry<Integer,Integer> entry:required.entrySet())
        {
            int id=entry.getKey(),need=entry.getValue();
            int carried=input.gear.contains(id)?GearVariants.count(input.inventory,id)+GearVariants.count(input.equipment,id):PlanInputs.count(input.inventory,id)+PlanInputs.count(input.equipment,id);
            if(!RuneAllocation.name(id).equals("Unmapped rune"))carried+=PlanInputs.count(input.pouch,id);
            int shortfall=Math.max(0,need-carried), withdraw=Math.min(shortfall,PlanInputs.count(input.bank,id));
            int stored=LeprechaunStorage.supports(id)?PlanInputs.count(input.leprechaun,id):0;
            int collect=Math.min(shortfall-withdraw,stored);
            int missing=shortfall-withdraw-collect;
            boolean storageUnknown=LeprechaunStorage.supports(id) && input.leprechaun==null;
            missingTotal+=missing; withdrawTotal+=withdraw;
            supplies.add(new Supply(id,need,Math.min(carried,need),PlanInputs.count(input.bank,id),withdraw,missing,stored,collect,storageUnknown));
            if(missing>0)problems.add(storageUnknown?"Check leprechaun storage: "+PlanCatalog.name(id)+" × "+missing+" needed.":input.bank==null?"Open bank to check: "+PlanCatalog.name(id)+" × "+missing+" needed.":"Get "+missing+" × "+PlanCatalog.name(id)+".");
            if(missing>0 && travelItems.contains(id))checklist.append("TO OBTAIN / VERIFY: ");
            checklist.append(PlanCatalog.name(id)).append(" × ").append(need)
                .append("\n   Carried ").append(Math.min(carried,need));
            if(withdraw>0)checklist.append(" • withdraw ").append(withdraw);
            if(collect>0)checklist.append(" • collect from leprechaun ").append(collect);
            if(missing>0)checklist.append(storageUnknown?" • leprechaun unchecked: need ":input.bank==null?" • bank unknown: need ":" • not in snapshot: ").append(missing);
            checklist.append('\n');
            if(shortfall>0)extraSlots+=stackable(id)?(PlanInputs.count(input.inventory,id)>0?0:1):shortfall;
        }
        if(missingTotal>0)unresolved=true;
        int collectTotal=supplies.stream().mapToInt(s->s.collect).sum();
        if(collectTotal>0)notes.add("Collect the allocated tools/compost from a tool leprechaun before using them. Bank withdrawals alone do not finish this setup.");
        if(input.leprechaun==null)notes.add(LeprechaunStorage.status(null));
        if(input.occupied<0)warn("Inventory space is unknown.","Refresh account details to check inventory space.");
        else if(input.occupied+extraSlots>28)warn("Current inventory plus remaining checklist items needs about "+(input.occupied+extraSlots)+" slots. Deposit items or adjust your setup.","Free at least "+(input.occupied+extraSlots-28)+" inventory slots.");
        if(usesSpell && input.runeStaffMask!=0)
        {
            if(input.plannedStaff>0 && PlanInputs.count(input.equipment,input.plannedStaff)==0)
            {
                equipStaffRequired=true;
                warn("Equip "+PlanCatalog.name(input.plannedStaff)+" before starting. Rune totals rely on this staff.","Equip "+PlanCatalog.name(input.plannedStaff)+".");
            }
            else notes.add("Rune totals use your equipped elemental staff. Keep it equipped for spell teleports; re-equip it after any fairy-ring staff swap.");
        }
        notes.add("Keep the detected rune pouch with you. Bank runes are budgeted as loose withdrawals.");
        notes.add("Withdraw seeds and consumables unnoted. Leave space for harvested herbs; note herbs with a tool leprechaun as needed.");
        notes.add("Only the listed methods are checked. Manual travel and manually confirmed supplies remain your responsibility.");
        String status=unresolved?"REVIEW NEEDED":collectTotal>0?"COLLECT LEPRECHAUN SUPPLIES":withdrawTotal>0?"WITHDRAW ITEMS BELOW":"LISTED SUPPLIES CARRIED";
        readiness=status;
        StringBuilder out=new StringBuilder(status).append("\n\n").append(choice.herb.name).append(" • ")
            .append(choice.patches.size()).append(" patches\nPatch order and automatic travel checked against the selected ending; timings are provisional.\n\n")
            .append("ROUTE\n").append(route).append("\nCOMBINED LOADOUT\n").append(input.bankStatus).append("\n\n").append(checklist)
            .append("\nCHECK BEFORE LEAVING\n");
        for(String note:notes)out.append("• ").append(note).append('\n');
        return out.toString();
    }
    private boolean unlocked(Travel t)
    {return unavailable(input,t,choice).isEmpty();}
    private boolean stocked(Travel t)
    {
        if(!unlocked(t))return false;
        int remaining=TeleportUses.remaining(input,t);
        if(remaining>=0 && remaining!=Integer.MAX_VALUE && usesSpent.getOrDefault(t,0)>=remaining)return false;
        if(ExtendedTravel.house(t))return stocked(ExtendedTravel.entry(t,choice));
        if(t.spell>=0)return RuneAllocation.solve(RuneSupplies.COSTS[t.spell],runeCarried,runeBank,input.runeStaffMask).deficit()==0;
        if(jewelleryIds(t).length>0)
        {
            if(chargesLeft.getOrDefault(jewelleryFamily(t),0)>0 && !hypotheticalCharges.contains(jewelleryFamily(t)))return true;
            for(int id:jewelleryIds(t))if(available(id)>0)return true;
            return false;
        }
        for(int id:items(t))if((consumable(t)?available(id):total(id))>0)return true;
        return false;
    }
    private Travel suggest(Travel[] methods)
    {
        for(Travel t:methods)if(stocked(t))return t;
        if(choice.includeObtain)for(Travel t:methods)if(unlocked(t))return t;
        return Travel.MANUAL;
    }
    private void use(Travel t)
    {
        Map<Integer,Integer> before=new HashMap<>(required);
        useInternal(t);
        for(Map.Entry<Integer,Integer> e:required.entrySet())
            if(e.getValue()>before.getOrDefault(e.getKey(),0))travelItems.add(e.getKey());
    }
    private void useInternal(Travel t)
    {
        if(!unlocked(t)) {blockedSteps++;warn(t.label+": "+unavailable(input,t,choice)+" (quest, diary, Magic level or active spellbook requirement is not met).",t.label+": "+compactRequirements(t));return;}
        if(ExtendedTravel.house(t))
        {
            useInternal(ExtendedTravel.entry(t,choice));
            if(ExtendedTravel.fairy(t) && !input.knownGate("Lumbridge Elite"))
            {
                int staff=ExtendedTravel.STAFFS[0];
                for(int id:ExtendedTravel.STAFFS)if(total(id)>0){staff=id;break;}
                required.put(staff,Math.max(1,required.getOrDefault(staff,0)));
                notes.add("Equip the counted dramen/lunar staff when using fairy rings. It is not used to reduce spell rune costs.");
            }
            notes.add("House/network route confirmed manually: "+t.label+". Entry is budgeted once for each use.");
            return;
        }
        if(t.spell>=0)
        {
            usesSpell=true;
            RuneAllocation.Result result=RuneAllocation.solve(RuneSupplies.COSTS[t.spell],runeCarried,runeBank,input.runeStaffMask);
            for(Map.Entry<Integer,Integer> e:result.used.entrySet())
            {
                int bank=result.withdraw.getOrDefault(e.getKey(),0);
                runeCarried.merge(e.getKey(),-(e.getValue()-bank),Integer::sum);
                runeBank.merge(e.getKey(),-bank,Integer::sum);
                add(e.getKey(),e.getValue());
            }
            for(int i=0;i<result.remaining.length;i++)if(result.remaining[i]>0)add(RuneSupplies.IDS[i],result.remaining[i]);
            if(result.deficit()>0)warn("Rune budget has a shortfall. Allocation is conservative across casts; alternate combination-rune choices may change the loadout.","Get the missing runes listed below, or change teleports.");
            return;
        }
        if(jewelleryIds(t).length>0)
        {
            Travel family=jewelleryFamily(t);
            int remaining=chargesLeft.getOrDefault(family,0);
            if(remaining==0)
            {
                int[] ids=jewelleryIds(t);
                int[] charges=jewelleryCharges(t);
                int selected=-1;
                for(int source=0;source<2 && selected<0;source++)for(int i=0;i<ids.length;i++)
                {
                    int carried=PlanInputs.count(input.inventory,ids[i])+PlanInputs.count(input.equipment,ids[i]);
                    int stock=source==0?carried:total(ids[i]);
                    if(stock>required.getOrDefault(ids[i],0)){selected=i;break;}
                }
                if(selected<0){hypotheticalCharges.add(family);selected=family==Travel.GLORY?1:0;}
                else hypotheticalCharges.remove(family);
                add(ids[selected],1); remaining=charges[selected];
            }
            chargesLeft.put(family,remaining-1); return;
        }
        int[] ids=items(t);
        if(ids.length==0){manualSteps++;warn("Manual travel: arrange its supplies yourself.",null);return;}
        int selected=ids[0];
        boolean found=false;
        for(int source=0;source<2 && !found;source++)for(int id:ids)
            if((source==0?PlanInputs.count(input.inventory,id)+PlanInputs.count(input.equipment,id):total(id))>0){selected=id;found=true;break;}
        if(t==Travel.RING || t==Travel.CLOAK || t==Travel.QUETZAL)
            for(int id:ids)if(total(id)>0){selected=id;break;}
        if(consumable(t))add(selected,1);
        else required.put(selected,Math.max(1,required.getOrDefault(selected,0)));
        if(ExtendedTravel.allowance(t,selected))
        {
            int remaining=TeleportUses.remaining(input,t);
            int spent=usesSpent.merge(t,1,Integer::sum);
            if(remaining<0)
            {
                if(!TeleportUses.confirmed(choice,t))
                {unconfirmedSteps++;warn(t.label+": remaining uses unknown. Check this item in game, then confirm it under Advanced settings → Limited teleports.",t.label+": check remaining uses, then confirm in Advanced settings.");}
                else notes.add(t.label+": whole-run uses manually confirmed because the count is unknown.");
            }
            else if(spent>remaining){blockedSteps++;warn(t.label+": not enough detected uses for the whole run.",t.label+": need "+spent+" uses; "+remaining+" left.");}
            else notes.add(t.label+": "+remaining+" uses detected; "+spent+" allocated.");
        }
    }
    private static boolean consumable(Travel t){return t.item>0 || t==Travel.ICY || t==Travel.STONY;}
    private String compactRequirements(Travel method)
    {
        String result=unavailable(input,method,choice);
        if(method.gate!=null)
        {
            String raw=method.gate.replace('_',' ');StringBuilder name=new StringBuilder();
            for(String word:raw.toLowerCase(Locale.ROOT).split(" "))if(!word.isEmpty())
            {if(name.length()>0)name.append(' ');name.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));}
            result=result.replace("Requirement not confirmed: "+raw,"Confirm "+name);
        }
        return result;
    }
    private String manualAction(Patch patch)
    {
        List<Travel> alternatives=new ArrayList<>();
        for(Travel t:patch.methods)if(t!=Travel.MANUAL && t!=Travel.AUTO)alternatives.add(t);
        if(alternatives.size()==1)
        {
            Travel method=alternatives.get(0);String missing=compactRequirements(method);
            if(!missing.isEmpty())return patch.label+": "+missing;
        }
        return patch.label+": choose travel in Advanced settings, or travel there yourself.";
    }
    private String fallback(Patch patch)
    {
        List<String> reasons=new ArrayList<>();
        for(Travel t:patch.methods)
        {
            String gate=unavailable(input,t,choice);
            reasons.add(t.label+" — "+(!gate.isEmpty()?gate:stocked(t)?"supplies detected; select this in Advanced settings":input.bank==null?"supplies not carried; open bank to check":"required supplies not available in the remaining counted stock"));
        }
        return "Travel needs setup. Supported alternatives: " + String.join("; ",reasons)+".";
    }
    static int[] items(Travel t)
    {
        if(t.item>0)return new int[]{t.item};
        switch(t)
        {
            case RING:return RINGS;
            case CLOAK:return CLOAKS;
            case XERIC:return new int[]{ItemID.XERIC_TALISMAN};
            case ECTO:return new int[]{ItemID.ECTOPHIAL};
            case ICY:return new int[]{ItemID.WEISS_TELEPORT_BASALT};
            case STONY:return new int[]{ItemID.STRONGHOLD_TELEPORT_BASALT};
            default:return ExtendedTravel.items(t);
        }
    }
    private int total(int id){return PlanInputs.count(input.inventory,id)+PlanInputs.count(input.equipment,id)+PlanInputs.count(input.bank,id);}
    private int available(int id){return total(id)-required.getOrDefault(id,0);}
    private void add(int id,int amount){if(amount>0)required.merge(id,amount,Integer::sum);}
    private void warn(String text){warn(text,text);}
    private void warn(String detail,String action){unresolved=true;notes.add(detail);if(action!=null)problems.add(action);}
}

package com.herbrunplanner;

import java.awt.*;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/** Original blue navigation art and pure minimap projection, independent of the client. */
final class NavigationMarker
{
    private NavigationMarker() {}
    static final BufferedImage PIN=pin();
    private static final BufferedImage[] ARROWS=new BufferedImage[64];
    static {for(int i=0;i<ARROWS.length;i++)ARROWS[i]=arrow(i*Math.PI*2/ARROWS.length);}
    static BufferedImage direction(double x,double y)
    {return ARROWS[Math.floorMod((int)Math.round(Math.atan2(y,x)*ARROWS.length/(2*Math.PI)),ARROWS.length)];}
    static Point project(double dx,double dy,double angle,double scale,int radius)
    {
        double x=(Math.cos(angle)*dx+Math.sin(angle)*dy)*scale;
        double y=(Math.sin(angle)*dx-Math.cos(angle)*dy)*scale;
        double length=Math.hypot(x,y);
        if(length>radius){x*=radius/length;y*=radius/length;}
        return new Point((int)Math.round(x),(int)Math.round(y));
    }
    private static BufferedImage arrow(double angle)
    {
        BufferedImage image=new BufferedImage(28,28,BufferedImage.TYPE_INT_ARGB);
        Graphics2D g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
        g.translate(14,14);g.rotate(angle);
        Path2D shape=new Path2D.Double();shape.moveTo(11,0);shape.lineTo(-9,-9);shape.lineTo(-4,0);shape.lineTo(-9,9);shape.closePath();
        g.setColor(new Color(22,43,83));g.setStroke(new BasicStroke(4));g.draw(shape);
        g.setColor(new Color(30,147,255));g.fill(shape);g.setColor(new Color(135,237,255));g.setStroke(new BasicStroke(1.5f));g.draw(shape);g.dispose();return image;
    }
    private static BufferedImage pin()
    {
        BufferedImage image=new BufferedImage(28,28,BufferedImage.TYPE_INT_ARGB);Graphics2D g=image.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(22,43,83));g.fillOval(3,3,22,22);g.setColor(new Color(30,147,255));g.fillOval(5,5,18,18);
        g.setColor(new Color(170,245,255));g.setStroke(new BasicStroke(2));g.drawOval(5,5,18,18);
        g.setColor(Color.WHITE);g.fillOval(11,11,6,6);g.dispose();return image;
    }
}

package com.herbrunplanner;

import java.awt.Rectangle;
import java.util.List;

/** Reserve the close-button area and Quest Helper's usual header slot. */
final class BankHeaderPlacement
{
    static final int SIZE=25,Y=5;
    static int findX(int bankWidth,List<Rectangle> occupied)
    {
        for(int x=bankWidth-110;x>=120;x-=30)
        {
            Rectangle candidate=new Rectangle(x,Y,SIZE,SIZE);
            boolean clear=true;
            for(Rectangle other:occupied)if(candidate.intersects(other)){clear=false;break;}
            if(clear)return x;
        }
        return -1;
    }
}

package com.herbrunplanner;

import java.awt.*;
import java.util.function.Supplier;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.*;

/** Projects the computed route only; no clicks, navigation or path searches. */
final class HerbWalkingLineOverlay extends Overlay
{
    private final Client client;
    private final Supplier<HerbWalkingGuide.View> source;
    HerbWalkingLineOverlay(Client client,Supplier<HerbWalkingGuide.View> source)
    {this.client=client;this.source=source;setPosition(OverlayPosition.DYNAMIC);setLayer(OverlayLayer.ABOVE_SCENE);}
    @Override public Dimension render(Graphics2D graphics)
    {
        HerbWalkingGuide.View view=source.get();if(view==null || view.tiles.size()<2)return null;
        Graphics2D g=(Graphics2D)graphics.create();
        try
        {
            g.setColor(new Color(85,220,215,210));g.setStroke(new BasicStroke(3,BasicStroke.CAP_ROUND,BasicStroke.JOIN_ROUND));
            net.runelite.api.Point previous=null;
            for(int i=0;i<Math.min(80,view.tiles.size());i++)
            {
                LocalWalkingPath.Tile tile=view.tiles.get(i);
                net.runelite.api.Point point=Perspective.localToCanvas(client,LocalPoint.fromScene(tile.x,tile.y,view.world),view.plane);
                if(point!=null && previous!=null)g.drawLine(previous.getX(),previous.getY(),point.getX(),point.getY());
                previous=point;
            }
        }
        finally{g.dispose();}
        return null;
    }
}

