    static final int[] WEALTH_CHARGES={5,5,4,4,3,3,2,2,1,1};
    static Travel jewelleryFamily(Travel t){return t==Travel.DUELING_FEROX?Travel.DUELING:t==Travel.GLORY_EDGE?Travel.GLORY:t;}
    static int[] jewelleryIds(Travel t)
    {
        switch(jewelleryFamily(t)){case WEALTH:return WEALTHS;case GLORY:return GLORIES;case SKILLS:return NECKLACES;case COMBAT:return BRACELETS;
            case DUELING:return DUELING_RINGS;default:return new int[0];}
    }
    static int[] jewelleryCharges(Travel t)
    {t=jewelleryFamily(t);return t==Travel.WEALTH?WEALTH_CHARGES:t==Travel.GLORY?GLORY_CHARGES:t==Travel.DUELING?DUELING_CHARGES:NECKLACE_CHARGES;}
    static final int[] RINGS={ItemID.LUMBRIDGE_RING_ELITE,ItemID.LUMBRIDGE_RING_HARD,ItemID.LUMBRIDGE_RING_MEDIUM};
    static final int[] CLOAKS={ItemID.ARDY_CAPE_ELITE,ItemID.ARDY_CAPE_HARD,ItemID.ARDY_CAPE_MEDIUM};
    static String name(int id)
