        for(int i=0;i<NECKLACES.length;i++)if(NECKLACES[i]==id)return "Skills necklace ("+NECKLACE_CHARGES[i]+")";
        for(Travel t:Travel.values())if(t.item==id && id>0)return t.label;
        for(int i=0;i<BRACELETS.length;i++)if(BRACELETS[i]==id)return "Combat bracelet ("+NECKLACE_CHARGES[i]+")";
        for(int i=0;i<DUELING_RINGS.length;i++)if(DUELING_RINGS[i]==id)return "Dueling ring ("+DUELING_CHARGES[i]+")";
        for(int i=0;i<RINGS.length;i++)if(RINGS[i]==id)return "Explorer's ring "+(4-i);
        for(int i=0;i<CLOAKS.length;i++)if(CLOAKS[i]==id)return "Ardougne cloak "+(4-i);
        for(int i=0;i<WEALTHS.length;i++)if(WEALTHS[i]==id)return "Ring of wealth ("+WEALTH_CHARGES[i]+")"+(i%2==1?" imbued":"");
        for(Travel t:Travel.values())for(int item:ExtendedTravel.items(t))if(item==id)
        {
            if(id==ItemID.SKILLCAPE_MAX || id==ItemID.SKILLCAPE_MAX_WORN)return "Max cape";
            if(id==ItemID.BOOK_OF_THE_DEAD)return "Book of the dead";
            if(id==ItemID.VEOS_KHAREDSTS_MEMOIRS)return "Kharedst's memoirs";
            if(t==Travel.QUETZAL)return id==ItemID.HG_QUETZALWHISTLE_PERFECTED_INFINITE?"Infinite quetzal whistle":id==ItemID.HG_QUETZALWHISTLE_PERFECTED?"Perfected quetzal whistle":id==ItemID.HG_QUETZALWHISTLE_ENHANCED?"Enhanced quetzal whistle":"Basic quetzal whistle";
            return t==Travel.FARM_CAPE?"Farming cape":t==Travel.CRAFT_CAPE?"Crafting cape":t==Travel.CON_CAPE?"Construction cape":t==Travel.HUNTER_CAPE?"Hunter cape":"Royal seed pod";
        }
        switch(id)
        {
            case ItemID.DRAMEN_STAFF:return "Dramen staff";
            case ItemID.LUNAR_MOONCLAN_LIMINAL_STAFF:return "Lunar staff";
            case ItemID.SPADE:return "Spade";
            case ItemID.DIBBER:return "Seed dibber";
            case ItemID.RAKE:return "Rake";
            case ItemID.FAIRY_ENCHANTED_SECATEURS:return "Magic secateurs";
            case ItemID.BUCKET_ULTRACOMPOST:return "Ultracompost bucket";
            case ItemID.BUCKET_SUPERCOMPOST:return "Supercompost bucket";
            case ItemID.BUCKET_COMPOST:return "Compost bucket";
            case ItemID.ECTOPHIAL:return "Filled ectophial";
            case ItemID.XERIC_TALISMAN:return "Xeric's talisman";
            case ItemID.WEISS_TELEPORT_BASALT:return "Icy basalt";
            case ItemID.STRONGHOLD_TELEPORT_BASALT:return "Stony basalt";
            default:return GearNames.name(id);
        }
    }
    static boolean stackable(int id)
    {
        if(!RuneAllocation.name(id).equals("Unmapped rune"))return true;
        for(Herb h:HERBS)if(h.id==id)return true;
        for(Travel t:Travel.values())if(t.item==id && id>0)return true;
        return id==ItemID.WEISS_TELEPORT_BASALT || id==ItemID.STRONGHOLD_TELEPORT_BASALT;
    }
}

package com.herbrunplanner;

import java.util.*;
import net.runelite.api.gameval.ItemID;

/** Bounded exact allocation for one cast. A combination rune covers both elements once. */
public final class RuneAllocation
{
    static final int[] COMBOS = {ItemID.MISTRUNE, ItemID.DUSTRUNE, ItemID.MUDRUNE,
        ItemID.SMOKERUNE, ItemID.STEAMRUNE, ItemID.LAVARUNE};
    static final String[] COMBO_NAMES = {"Mist", "Dust", "Mud", "Smoke", "Steam", "Lava"};
    static final int[] MASKS = {6,10,12,18,20,24}; // air/water/earth/fire occupy bits 1..4
    public static final class Result
    {
        public final int[] remaining;
        public final Map<Integer, Integer> withdraw;
        public final Map<Integer, Integer> used;
        Result(int[] remaining, Map<Integer, Integer> withdraw)
        { this(remaining, withdraw, Collections.emptyMap()); }
        Result(int[] remaining, Map<Integer, Integer> withdraw, Map<Integer, Integer> used)
        { this.remaining = remaining.clone(); this.withdraw = new LinkedHashMap<>(withdraw); this.used = new LinkedHashMap<>(used); }
        int deficit() { return Arrays.stream(remaining).sum(); }
        int bankUnits() { return withdraw.values().stream().mapToInt(Integer::intValue).sum(); }
    }
    private static final class Pool
    {
        final int id, mask, amount; final boolean bank;
        Pool(int id, int mask, int amount, boolean bank)
        { this.id=id; this.mask=mask; this.amount=amount; this.bank=bank; }
    }
    public static Result solve(int[] cost, Map<Integer,Integer> carried, Map<Integer,Integer> bank, int staffMask)
    {
        int[] need=cost.clone();
        for(int i=0;i<need.length;i++) if((staffMask & (1<<i))!=0) need[i]=0;
        List<Pool> pools=new ArrayList<>();
        addPools(pools,carried,false); addPools(pools,bank,true);
        return search(pools,0,need,new HashMap<>());
    }
    private static void addPools(List<Pool> pools,Map<Integer,Integer> items,boolean bank)
    {
        if(items==null) return;
        for(int i=0;i<RuneSupplies.IDS.length;i++) add(pools,items,RuneSupplies.IDS[i],1<<i,bank);
        for(int i=0;i<COMBOS.length;i++) add(pools,items,COMBOS[i],MASKS[i],bank);
    }
    private static void add(List<Pool> p,Map<Integer,Integer> m,int id,int mask,boolean bank)
    { int n=m.getOrDefault(id,0); if(n>0) p.add(new Pool(id,mask,n,bank)); }
    private static Result search(List<Pool> pools,int index,int[] need,Map<String,Result> memo)
    {
        if(Thread.currentThread().isInterrupted()) throw new java.util.concurrent.CancellationException();
        if(index==pools.size()) return new Result(need,Collections.emptyMap());
        String key=index+Arrays.toString(need);
        if(memo.containsKey(key)) return memo.get(key);
        Pool pool=pools.get(index); int limit=0;
        for(int i=0;i<need.length;i++) if((pool.mask & (1<<i))!=0) limit=Math.max(limit,need[i]);
        limit=Math.min(limit,pool.amount); Result best=null;
        for(int count=0;count<=limit;count++)
        {
            int[] next=need.clone();
            for(int i=0;i<next.length;i++) if((pool.mask & (1<<i))!=0) next[i]=Math.max(0,next[i]-count);
            Result tail=search(pools,index+1,next,memo);
            Map<Integer,Integer> withdrawal=new LinkedHashMap<>(tail.withdraw);
            if(pool.bank && count>0) withdrawal.merge(pool.id,count,Integer::sum);
            Map<Integer,Integer> used=new LinkedHashMap<>(tail.used);
            if(count>0) used.merge(pool.id,count,Integer::sum);
            Result candidate=new Result(tail.remaining,withdrawal,used);
            if(best==null || candidate.deficit()<best.deficit()
                || (candidate.deficit()==best.deficit() && candidate.bankUnits()<best.bankUnits())) best=candidate;
        }
        memo.put(key,best); return best;
    }
    public static String name(int id)
    {
        for(int i=0;i<RuneSupplies.IDS.length;i++) if(id==RuneSupplies.IDS[i]) return RuneSupplies.NAMES[i];
        for(int i=0;i<COMBOS.length;i++) if(id==COMBOS[i]) return COMBO_NAMES[i];
        return "Unmapped rune";
    }
}

package com.herbrunplanner;

import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.game.ItemManager;

/** Rearranges visible bank slots only. Missing items get inert, plugin-owned graphics. */
final class HerbBankLayout
{
    private final Client client;
    private final ItemManager items;
    private Widget parent;
    private final Map<Integer,Integer> slots=new LinkedHashMap<>();
    private final Map<Integer,Widget> ghosts=new HashMap<>();
    HerbBankLayout(Client client,ItemManager items){this.client=client;this.items=items;}
    int canonical(int id)
    {
        if(id<=0)return id;
        ItemComposition def=items.getItemComposition(id);
        return def.getPlaceholderTemplateId()!=-1 && def.getPlaceholderId()!=-1?def.getPlaceholderId():id;
    }
    void clear()
    {
        for(Widget ghost:ghosts.values())ghost.setHidden(true);
        slots.clear();
    }
    int layout(BankPreparation prepared)
    {
        Widget bank=client.getWidget(InterfaceID.Bankmain.ITEMS);
        if(bank==null || bank.isHidden())return 0;
        if(parent!=bank){clear();ghosts.clear();parent=bank;}
        for(BankPreparation.Row row:prepared.rows)slots.computeIfAbsent(row.id,id->slots.size());
        for(Widget ghost:ghosts.values())ghost.setHidden(true);
        Set<Integer> found=new HashSet<>();
        Widget[] children=bank.getDynamicChildren();
        if(children!=null)for(Widget child:children)
        {
            if(child==null || child.isSelfHidden() || ghosts.containsValue(child))continue;
            int id=canonical(child.getItemId());Integer slot=slots.get(id);
            if(slot==null || !prepared.items.containsKey(id))continue;
            place(child,slot);found.add(id);
        }
        for(int id:prepared.items.keySet())if(!found.contains(id))
        {
            Widget ghost=ghosts.get(id);
            if(ghost==null || bank.getChild(ghost.getIndex())!=ghost)
            {
                ghost=bank.createChild(-1,WidgetType.GRAPHIC);ghosts.put(id,ghost);
                ghost.setOriginalWidth(36);ghost.setOriginalHeight(32);
                ghost.setItemId(id);ghost.setItemQuantity(0);ghost.setOpacity(160);
                // No actions, listeners or withdrawal callback on an empty slot.
            }
            ghost.setHidden(false);place(ghost,slots.get(id));
        }
        return ((slots.size()+7)/8)*36;
    }
    private void place(Widget child,int slot)
    {child.setOriginalX(51+(slot%8)*48);child.setOriginalY((slot/8)*36);child.revalidate();}
}

