package com.herbrunplanner;

import static com.herbrunplanner.PlanCatalog.*;

/** Remaining-use observations: -1 unknown, 0 exhausted, MAX_VALUE unlimited. */
final class TeleportUses
{
    static final Travel[] METHODS={Travel.RING,Travel.CLOAK,Travel.XERIC};
    private TeleportUses() {}
    static String key(Travel t){return "USES_"+t.name();}
    static int ringRemaining(int used){return used>=0 && used<=3?3-used:-1;}
    static int remaining(PlanInputs in,Travel t)
    {
        if(t!=Travel.RING && t!=Travel.CLOAK && t!=Travel.XERIC)return Integer.MAX_VALUE;
        if(t!=Travel.XERIC)
            for(int id:PlanEngine.items(t))if(ExtendedTravel.hasAny(in,new int[]{id}))
            {
                if(!ExtendedTravel.allowance(t,id))return Integer.MAX_VALUE;
                break;
            }
        return in.teleportUses.getOrDefault(t,-1);
    }
    static boolean confirmed(PlanInputs.Choices c,Travel t)
    {return c.travelChecks.contains(key(t));}
    static String status(PlanInputs in,Travel t)
    {
        int n=remaining(in,t);
        return t.label+": "+(n<0?"remaining uses unknown":n==Integer.MAX_VALUE?"unlimited":n+" uses remaining");
    }
}

package com.herbrunplanner;

import java.util.*;

/** Account-owned named outfits. Only explicit text preferences are persisted. */
final class GearSets
{
    static final class Outfit
    {
        final int id;
        String name;
        final Set<Integer> items=new LinkedHashSet<>();
        Outfit(int id,String name){this.id=id;this.name=name;}
        public String toString(){return name;}
    }
    final Map<Integer,Outfit> outfits=new LinkedHashMap<>();
    int selected,defaultId;
    Outfit current(){return outfits.get(selected);}
    static String clean(String name)
    {
        String value=name.replaceAll("[\\r\\n=]"," ").trim();
        return value.substring(0,Math.min(50,value.length()));
    }
    Outfit add(String name)
    {
        int id=1;while(outfits.containsKey(id))id++;
        Outfit o=new Outfit(id,clean(name));outfits.put(id,o);selected=id;return o;
    }
    static GearSets load(RunPreferences p)
    {
        GearSets sets=new GearSets();
        for(Map.Entry<String,String> e:p.values.entrySet())
        {
            String[] parts=e.getKey().split("\\.");
            if(parts.length==3 && parts[0].equals("outfit") && parts[2].equals("name"))
                try{int id=Integer.parseInt(parts[1]);if(id>0)sets.outfits.put(id,new Outfit(id,clean(e.getValue())));}catch(NumberFormatException ignored){}
        }
        for(Outfit o:sets.outfits.values())
            for(String key:p.values.keySet())if(key.startsWith("outfit."+o.id+".item."))
                try{int id=Integer.parseInt(key.substring(key.lastIndexOf('.')+1));if(id>0 && p.flag(key,false))o.items.add(GearVariants.canonical(id));}catch(NumberFormatException ignored){}
        if(sets.outfits.isEmpty())
        {
            Outfit legacy=sets.add("My gear");
            for(String key:p.values.keySet())if(key.startsWith("gear."))
                try{int id=Integer.parseInt(key.substring(5));if(id>0 && p.flag(key,false))legacy.items.add(GearVariants.canonical(id));}catch(NumberFormatException ignored){}
        }
        try{sets.defaultId=Integer.parseInt(p.values.getOrDefault("outfitDefault","0"));}catch(NumberFormatException ignored){}
        try{sets.selected=Integer.parseInt(p.values.getOrDefault("outfitSelected","0"));}catch(NumberFormatException ignored){}
        if(sets.outfits.containsKey(sets.defaultId))sets.selected=sets.defaultId;
        else sets.defaultId=0;
        if(!sets.outfits.containsKey(sets.selected))sets.selected=sets.outfits.keySet().iterator().next();
        return sets;
    }
    void save(RunPreferences p)
    {
        p.values.keySet().removeIf(k->k.startsWith("outfit.") || k.startsWith("gear."));
        for(Outfit o:outfits.values())
        {
            p.put("outfit."+o.id+".name",o.name);
            for(int id:o.items)p.put("outfit."+o.id+".item."+id,true);
        }
        p.put("outfitSelected",selected);p.put("outfitDefault",defaultId);
    }
}

package com.herbrunplanner;

import java.util.regex.*;

/** Local evidence only; each new request/region starts with no completion evidence. */
final class ObservedPatchCompletion
{
    private static final Pattern TREAT=Pattern.compile("You treat the .+ with (ultra|super|)compost\\.");
    private static final Pattern SPELL=Pattern.compile("The .+ has been treated with (ultra|super|)compost.*");
    private static final Pattern INSPECT=Pattern.compile("This is an? .+\\. The soil has been treated with (ultra|super|)compost\\..*");
    private static final Pattern ALREADY=Pattern.compile("This .+ has already been (?:treated|fertilised) with (ultra|super|)compost(?: - the spell can't make it any more fertile)?\\.");
    private boolean planted,sent;private int compost,plantUntil=-1,compostUntil=-1,seedBefore,varbitBefore,expectedState;
    void planting(int tick,int seeds,int state,int expected){expectedState=expected;plantUntil=tick+30;seedBefore=seeds;varbitBefore=state;}
    void clearCompost(){compost=0;compostUntil=-1;}
    void composting(int tick){compostUntil=tick+30;}
    void observe(int tick,int seeds,int state,boolean beside)
    {if(beside && tick<=plantUntil && seeds<seedBefore && state!=varbitBefore && state==expectedState && expectedState>=4){planted=true;plantUntil=-1;}}
    void message(String raw,int tick,boolean beside)
    {
        if(!beside || tick>compostUntil)return;
        String text=raw.replaceAll("<[^>]*>","");
        for(Pattern pattern:new Pattern[]{TREAT,SPELL,INSPECT,ALREADY})
        {
            Matcher m=pattern.matcher(text);if(!m.matches())continue;
            compost="ultra".equals(m.group(1))?3:"super".equals(m.group(1))?2:1;compostUntil=-1;return;
        }
    }
    boolean takeCompletion(int required)
    {if(sent || !planted || compost<required)return false;sent=true;return true;}
}

package com.herbrunplanner;

import java.util.*;
import static com.herbrunplanner.PlanCatalog.*;

/** Explicit allowlist: no account identifiers, raw logs, bank dumps or environment. */
final class BetaDiagnostics
{
    static final String VERSION="0.33.4 beta";
    private BetaDiagnostics() {}
    static String render(PlanInputs current,PlanInputs.Choices requested,PlanEngine.Report report,RunProgress run,boolean loading,boolean pending)
    {
        StringBuilder out=new StringBuilder("Herb Run Planner "+VERSION+"\n")
            .append("Loading: ").append(loading).append("; calculation pending: ").append(pending).append('\n')
            .append("Contains selected routes, requirements and relevant supply counts. No account identifiers or credentials.\n");
        if(current==null)return out.append("No current account snapshot.\n").toString();
        out.append("Current observed state: Magic ").append(current.magic).append("; Farming ").append(current.farming)
            .append(" (base ").append(current.baseFarming).append("); spellbook ").append(TeleportEligibility.bookName(current.book))
            .append("; elemental staff mask ").append(current.staffMask).append("; members ").append(current.members)
            .append("; bank open ").append(current.bankOpen).append("; bank observed ").append(current.bank!=null)
            .append("; pouch observed ").append(current.pouch!=null).append("; leprechaun observed ").append(current.leprechaun!=null).append('\n');
        out.append("Bottomless bucket type: ").append(current.compostType).append("; applications: ").append(current.compostApplications).append('\n');
        for(Travel t:TeleportUses.METHODS)out.append(TeleportUses.status(current,t)).append('\n');
        choices(out,"Requested setup",requested,current);
        if(report!=null)
        {
            choices(out,"Last prepared route (frozen during a run)",report.resolvedChoices,current);
            out.append("Prepared status: ").append(report.status).append("; blocked ").append(report.blockedSteps)
                .append("; manual ").append(report.manualSteps).append("; unconfirmed ").append(report.unconfirmedSteps).append('\n');
            out.append("Last prepared quantities; these are not remaining-run quantities:\n");
            for(PlanEngine.Supply s:report.supplies)
                out.append(PlanCatalog.name(s.id)).append(" [").append(s.id).append("]: need ").append(s.need)
                    .append(", have ").append(s.have).append(", bank ").append(s.bank).append(", withdraw ").append(s.withdraw)
                    .append(", collect ").append(s.collect).append(", missing ").append(s.missing).append('\n');
            out.append("Current observed counts for those items only (unknown sources shown as ?):\n");
            for(PlanEngine.Supply s:report.supplies)
                out.append(s.id).append(": inventory ").append(count(current.inventory,s.id)).append(", equipment ").append(count(current.equipment,s.id))
                    .append(", pouch ").append(count(current.pouch,s.id)).append(", bank ").append(count(current.bank,s.id))
                    .append(", leprechaun ").append(count(current.leprechaun,s.id)).append('\n');
        }
        else out.append("No valid prepared report. Prepare the run to include supply calculations.\n");
        if(run!=null)out.append("Run progress: ").append(run.complete()?"complete":run.current().title)
            .append("; done ").append(run.count(RunProgress.State.DONE)).append("; skipped ").append(run.count(RunProgress.State.SKIPPED)).append('\n');
        return out.toString();
    }
    private static String count(Map<Integer,Integer> source,int id){return source==null?"?":Integer.toString(PlanInputs.count(source,id));}
    private static void choices(StringBuilder out,String title,PlanInputs.Choices c,PlanInputs in)
    {
        if(c==null)return;
        out.append(title).append(": ").append(c.herb.name).append("; compost ").append(c.compost.name())
            .append("; ending ").append(c.bankReturn.name()).append("; house entry ").append(c.houseEntry.name())
            .append("; external entry ").append(c.externalNetworks).append("; include items to obtain ").append(c.includeObtain).append('\n');
        out.append("Confirmations: Weiss ").append(c.weiss).append("; Harmony ").append(c.harmony)
            .append("; own compost ").append(c.manualCompost).append('\n');
        for(Travel t:TeleportUses.METHODS)if(TeleportUses.confirmed(c,t))out.append("Uses manually confirmed: ").append(t.label).append('\n');
        for(String key:ExtendedTravel.CHECKS.keySet())if(c.travelChecks.contains(key))out.append("Confirmed: ").append(key).append('\n');
        for(Patch patch:c.order)
        {
            Travel travel=c.patches.get(patch);
            out.append(patch.label).append(": ").append(travel.label).append("; patch access ").append(in.patchGate(patch)).append('\n');
            String reason=PlanEngine.unavailable(in,travel,c);
            if(!reason.isEmpty())out.append("Current requirement: ").append(reason).append('\n');
        }
        if(c.bankReturn.travel!=null)
        {
            String reason=PlanEngine.unavailable(in,c.bankReturn.travel,c);
            if(!reason.isEmpty())out.append("Bank return requirement: ").append(reason).append('\n');
        }
    }
}

package com.herbrunplanner;

import java.util.*;
import java.util.function.BiPredicate;
import static net.runelite.api.CollisionDataFlag.*;

/** Bounded eight-direction A* search over loaded walking collision. */
final class LocalWalkingPath
{
    static final int MAX_VISITS=6000;
    private static final int[][] CARDINAL={{1,0},{-1,0},{0,1},{0,-1}};
    static final class Tile
    {
        final int x,y;
        Tile(int x,int y){this.x=x;this.y=y;}
    }
    static final class Target
    {
        final int minX,minY,maxX,maxY;
        Target(int minX,int minY,int maxX,int maxY){this.minX=minX;this.minY=minY;this.maxX=maxX;this.maxY=maxY;}
        boolean contains(int x,int y){return x>=minX && x<=maxX && y>=minY && y<=maxY;}
    }
    static final class Result
    {
        final List<Tile> tiles;final String status;
        Result(List<Tile> tiles,String status){this.tiles=Collections.unmodifiableList(tiles);this.status=status;}
    }
    private static boolean inside(int[][] flags,int x,int y)
    {return x>=0 && x<flags.length && flags[x]!=null && y>=0 && y<flags[x].length;}
    private static int wall(int dx,int dy)
    {
        if(dx<0)return dy<0?BLOCK_MOVEMENT_SOUTH_WEST:dy>0?BLOCK_MOVEMENT_NORTH_WEST:BLOCK_MOVEMENT_WEST;
        if(dx>0)return dy<0?BLOCK_MOVEMENT_SOUTH_EAST:dy>0?BLOCK_MOVEMENT_NORTH_EAST:BLOCK_MOVEMENT_EAST;
        return dy<0?BLOCK_MOVEMENT_SOUTH:BLOCK_MOVEMENT_NORTH;
    }
    private static boolean edge(int[][] flags,int x,int y,int dx,int dy)
    {return (flags[x][y]&wall(dx,dy))==0 && (flags[x+dx][y+dy]&wall(-dx,-dy))==0;}
    static boolean canMove(int[][] flags,int x,int y,int dx,int dy,BiPredicate<Integer,Integer> loaded)
    {
        int nx=x+dx,ny=y+dy;
        if(!inside(flags,x,y) || !inside(flags,nx,ny) || !loaded.test(nx,ny) || (flags[nx][ny]&BLOCK_MOVEMENT_FULL)!=0)return false;
        if(!edge(flags,x,y,dx,dy))return false;
        if(dx!=0 && dy!=0)
        {
            // Both corner tiles and all four cardinal edges must be clear.
            return canMove(flags,x,y,dx,0,loaded) && canMove(flags,x,y,0,dy,loaded)
                && canMove(flags,x+dx,y,0,dy,loaded) && canMove(flags,x,y+dy,dx,0,loaded);
        }
        return true;
    }
    private static boolean beside(int[][] flags,int x,int y,Target target)
    {
        for(int[] d:CARDINAL)
        {
            int nx=x+d[0],ny=y+d[1];
            if(target.contains(nx,ny) && inside(flags,nx,ny) && edge(flags,x,y,d[0],d[1]))return true;
        }
        return false;
    }
    static Result find(int[][] flags,int sx,int sy,Target target,BiPredicate<Integer,Integer> loaded)
    {
        if(flags==null || !inside(flags,sx,sy) || !loaded.test(sx,sy))return new Result(Collections.emptyList(),"Walking map unavailable.");
        int height=flags[sx].length,width=flags.length;
        if(height==0 || width>256 || height>256)return new Result(Collections.emptyList(),"Walking map unsupported.");
        int[] parent=new int[width*height],cost=new int[width*height];Arrays.fill(parent,-1);Arrays.fill(cost,Integer.MAX_VALUE);
        PriorityQueue<int[]> queue=new PriorityQueue<>(Comparator.<int[]>comparingInt(n->n[2]).thenComparingInt(n->n[3]).thenComparingInt(n->n[0]));
        int start=sx*height+sy,head=0;parent[start]=start;cost[start]=0;queue.add(new int[]{start,0,0,0});
        while(!queue.isEmpty() && head<MAX_VISITS)
        {
            int[] visit=queue.remove();int node=visit[0],x=node/height,y=node%height;
            if(visit[1]!=cost[node])continue;
            head++;
            if(beside(flags,x,y,target))
            {
                List<Tile> path=new ArrayList<>();int n=node;
                while(n!=start){path.add(new Tile(n/height,n%height));n=parent[n];}
                path.add(new Tile(sx,sy));Collections.reverse(path);
                return new Result(path,path.size()==1?"Beside patch · finish it, then press Done.":"Loaded walking route · "+(path.size()-1)+" steps");
            }
            for(int dx=-1;dx<=1;dx++)for(int dy=-1;dy<=1;dy++)
            {
                if(dx==0 && dy==0)continue;
                int nx=x+dx,ny=y+dy;
                if(ny<0 || ny>=height || !inside(flags,nx,ny) || target.contains(nx,ny))continue;
                int next=nx*height+ny;
                if(!canMove(flags,x,y,dx,dy,loaded))continue;
                // Minimize walking ticks first, then unnecessary diagonal detours.
                int candidate=cost[node]+1000+(dx!=0 && dy!=0?1:0);
                if(candidate>=cost[next])continue;
                cost[next]=candidate;parent[next]=node;
                int tx=Math.max(target.minX,Math.min(nx,target.maxX)),ty=Math.max(target.minY,Math.min(ny,target.maxY));
                int estimate=Math.max(0,Math.max(Math.abs(nx-tx),Math.abs(ny-ty))-1)*1000;
                int deviation=Math.abs((nx-sx)*(target.minY-sy)-(ny-sy)*(target.minX-sx));
                queue.add(new int[]{next,candidate,candidate+estimate,deviation});
            }
        }
        return new Result(Collections.emptyList(),head>=MAX_VISITS?"Search limit reached · move closer to patch.":"No loaded walking route · check gates or change level.");
    }
}
